// ─── Lesson "Deep Dive" sections ─────────────────────────────────────────────
// One extra, self-contained section appended to every lesson to add depth. Each
// entry carries the section's heading + body (paragraphs split on \n\n) in all
// six languages. These are merged in at the render boundary by
// getTranslatedLesson, so they show consistently everywhere a lesson renders and
// require no edits to the large lesson-data or split-translation files.
//
// English (en) is always present; other languages fall back to en when missing,
// exactly like the rest of the content pipeline.
import type { Language } from './translations';

export interface DeepDiveSection { heading: string; body: string; }
export type DeepDive = { en: DeepDiveSection } & Partial<Record<Language, DeepDiveSection>>;

export const LESSON_DEEP_DIVES: Record<string, DeepDive> = {
  // ══════════════════════════ ANCIENT ══════════════════════════
  'ancient-01': {
    en: { heading: "The Indus Valley: A Third River Civilization",
      body: "While Mesopotamia and Egypt flourished, a third great civilization arose along the Indus River in what is now Pakistan and northwest India. The Harappan civilization (c.2600–1900 BCE) built remarkable planned cities such as Harappa and Mohenjo-daro, laid out on precise grids with baked-brick houses, covered drains, and the world's first urban sanitation systems.\n\nThe Harappans standardized weights and measures, traded with Mesopotamia by sea, and produced a script that has never been deciphered. Unlike their contemporaries, they left no palaces, royal tombs, or monuments to war — hinting at a society organized in a strikingly different way. Around 1900 BCE the cities were gradually abandoned, likely as shifting rivers and a changing climate undermined their farmland." },
    es: { heading: "El valle del Indo: una tercera civilización fluvial",
      body: "Mientras Mesopotamia y Egipto florecían, una tercera gran civilización surgió a lo largo del río Indo, en lo que hoy son Pakistán y el noroeste de la India. La civilización harappa (c.2600–1900 a.C.) construyó ciudades notablemente planificadas, como Harappa y Mohenjo-daro, trazadas en cuadrículas precisas, con casas de ladrillo cocido, alcantarillas cubiertas y los primeros sistemas urbanos de saneamiento del mundo.\n\nLos harappas estandarizaron pesos y medidas, comerciaron por mar con Mesopotamia y crearon una escritura que nunca ha sido descifrada. A diferencia de sus contemporáneos, no dejaron palacios, tumbas reales ni monumentos a la guerra, lo que sugiere una sociedad organizada de un modo muy distinto. Hacia el 1900 a.C. las ciudades fueron abandonadas poco a poco, probablemente porque el cambio de los ríos y del clima arruinó sus tierras de cultivo." },
    ru: { heading: "Долина Инда: третья речная цивилизация",
      body: "Пока процветали Месопотамия и Египет, третья великая цивилизация возникла в долине реки Инд — на территории современного Пакистана и северо-западной Индии. Хараппская цивилизация (ок. 2600–1900 гг. до н.э.) строила удивительно спланированные города, такие как Хараппа и Мохенджо-Даро, с чёткой сеткой улиц, домами из обожжённого кирпича, крытыми стоками и первыми в мире городскими системами канализации.\n\nХараппцы ввели единые меры веса и длины, торговали с Месопотамией по морю и создали письменность, которая до сих пор не расшифрована. В отличие от современников, они не оставили ни дворцов, ни царских гробниц, ни памятников войнам — что указывает на совершенно иначе устроенное общество. Около 1900 г. до н.э. города постепенно опустели, вероятно, из-за того что смещение рек и изменение климата подорвали их земледелие." },
    mk: { heading: "Долината на Инд: трета речна цивилизација",
      body: "Додека Месопотамија и Египет цветаа, трета голема цивилизација се појави долж реката Инд, на територијата на денешен Пакистан и северозападна Индија. Харапската цивилизација (о. 2600–1900 п.н.е.) градела извонредно испланирани градови како Харапа и Мохенџо-Даро, поставени во прецизни мрежи, со куќи од печена тула, покриени одводи и првите урбани системи за санитарна хигиена во светот.\n\nХарапците вовеле стандардни мерки за тежина и должина, тргувале со Месопотамија по море и создале писмо што досега не е дешифрирано. За разлика од своите современици, не оставиле ниту палати, ниту кралски гробници, ниту споменици на војна — што укажува на општество организирано на впечатливо поинаков начин. Околу 1900 п.н.е. градовите постепено биле напуштени, најверојатно бидејќи поместувањето на реките и климатските промени го уништиле нивното земјоделство." },
    de: { heading: "Das Industal: eine dritte Stromkultur",
      body: "Während Mesopotamien und Ägypten blühten, entstand am Indus im heutigen Pakistan und Nordwestindien eine dritte große Zivilisation. Die Harappa-Kultur (ca. 2600–1900 v. Chr.) errichtete bemerkenswert geplante Städte wie Harappa und Mohenjo-daro, angelegt in präzisen Rastern, mit Häusern aus gebranntem Ziegel, überdachten Abwasserkanälen und den ersten städtischen Sanitärsystemen der Welt.\n\nDie Harappaner vereinheitlichten Maße und Gewichte, trieben über das Meer Handel mit Mesopotamien und schufen eine bis heute nicht entzifferte Schrift. Anders als ihre Zeitgenossen hinterließen sie weder Paläste noch Königsgräber oder Kriegsdenkmäler — ein Hinweis auf eine ganz anders organisierte Gesellschaft. Um 1900 v. Chr. wurden die Städte allmählich verlassen, wahrscheinlich weil sich verlagernde Flüsse und ein Klimawandel ihre Felder zerstörten." },
    fr: { heading: "La vallée de l'Indus : une troisième civilisation fluviale",
      body: "Tandis que la Mésopotamie et l'Égypte prospéraient, une troisième grande civilisation naquit le long de l'Indus, dans l'actuel Pakistan et le nord-ouest de l'Inde. La civilisation harappéenne (v. 2600–1900 av. J.-C.) bâtit des villes remarquablement planifiées, comme Harappa et Mohenjo-daro, tracées selon des grilles précises, avec des maisons en brique cuite, des égouts couverts et les premiers systèmes urbains d'assainissement au monde.\n\nLes Harappéens normalisèrent poids et mesures, commercèrent par mer avec la Mésopotamie et créèrent une écriture jamais déchiffrée. Contrairement à leurs contemporains, ils ne laissèrent ni palais, ni tombes royales, ni monuments guerriers — signe d'une société organisée de façon très différente. Vers 1900 av. J.-C., les villes furent peu à peu abandonnées, sans doute parce que le déplacement des rivières et un changement climatique ruinèrent leurs terres agricoles." },
  },
  'ancient-02': {
    en: { heading: "The Birth of Theatre",
      body: "Classical Athens gave the world theatre. Drama grew out of religious festivals honoring Dionysus, the god of wine and ecstasy, where choruses sang and danced. In the fifth century BCE, playwrights transformed these rituals into a new art form performed in vast open-air theatres carved into hillsides, some seating over 15,000 spectators with acoustics so fine that a whisper on stage carried to the last row.\n\nThree great tragedians — Aeschylus, Sophocles, and Euripides — probed fate, justice, and human suffering in plays still staged today, from Oedipus Rex to Antigone. Aristophanes perfected comedy, mocking politicians and philosophers without mercy. Greek audiences believed that watching tragedy produced catharsis, a purifying release of pity and fear that left citizens wiser and more compassionate." },
    es: { heading: "El nacimiento del teatro",
      body: "La Atenas clásica dio al mundo el teatro. El drama surgió de las fiestas religiosas en honor a Dioniso, dios del vino y el éxtasis, donde los coros cantaban y bailaban. En el siglo V a.C., los dramaturgos transformaron esos rituales en un nuevo arte representado en enormes teatros al aire libre excavados en las laderas, algunos con capacidad para más de 15.000 espectadores y una acústica tan perfecta que un susurro en el escenario llegaba a la última fila.\n\nTres grandes trágicos —Esquilo, Sófocles y Eurípides— exploraron el destino, la justicia y el sufrimiento humano en obras que aún se representan hoy, desde Edipo rey hasta Antígona. Aristófanes perfeccionó la comedia, burlándose sin piedad de políticos y filósofos. El público griego creía que ver una tragedia producía catarsis, una liberación purificadora de la compasión y el miedo que dejaba a los ciudadanos más sabios y humanos." },
    ru: { heading: "Рождение театра",
      body: "Классические Афины подарили миру театр. Драма выросла из религиозных праздников в честь Диониса, бога вина и экстаза, где хоры пели и танцевали. В V веке до н.э. драматурги превратили эти обряды в новое искусство, которое разыгрывалось в огромных театрах под открытым небом, вырубленных в склонах холмов; некоторые вмещали более 15 000 зрителей, а их акустика была так хороша, что шёпот на сцене доносился до последнего ряда.\n\nТри великих трагика — Эсхил, Софокл и Еврипид — исследовали судьбу, справедливость и человеческое страдание в пьесах, которые ставят и сегодня, от «Царя Эдипа» до «Антигоны». Аристофан довёл до совершенства комедию, безжалостно высмеивая политиков и философов. Греки верили, что созерцание трагедии вызывает катарсис — очищающее освобождение от жалости и страха, делавшее граждан мудрее и человечнее." },
    mk: { heading: "Раѓањето на театарот",
      body: "Класична Атина му го подари театарот на светот. Драмата израсна од религиозните празници во чест на Дионис, богот на виното и екстазата, каде што хоровите пееја и играа. Во петтиот век п.н.е. драматурзите ги преобразија тие обреди во нова уметност изведувана во огромни театри на отворено, вклепани во падините на ридовите; некои примале над 15.000 гледачи, а акустиката им била толку добра што шепот на сцената стигнувал до последниот ред.\n\nТројца големи трагичари — Есхил, Софокле и Еврипид — ги истражуваа судбината, правдата и човечкото страдање во дела што и денес се играат, од „Цар Едип“ до „Антигона“. Аристофан ја усоврши комедијата, безмилосно исмевајќи ги политичарите и филозофите. Грците верувале дека гледањето трагедија предизвикува катарза — прочистувачко ослободување од сожалување и страв што ги оставало граѓаните помудри и почовечни." },
    de: { heading: "Die Geburt des Theaters",
      body: "Das klassische Athen schenkte der Welt das Theater. Das Drama erwuchs aus religiösen Festen zu Ehren des Dionysos, des Gottes des Weins und der Ekstase, bei denen Chöre sangen und tanzten. Im fünften Jahrhundert v. Chr. verwandelten Dichter diese Rituale in eine neue Kunstform, aufgeführt in gewaltigen Freilufttheatern, die in Hänge gehauen waren; manche fassten über 15.000 Zuschauer, mit einer Akustik, die selbst ein Flüstern auf der Bühne bis in die letzte Reihe trug.\n\nDrei große Tragiker — Aischylos, Sophokles und Euripides — ergründeten Schicksal, Gerechtigkeit und menschliches Leid in Stücken, die bis heute gespielt werden, von König Ödipus bis Antigone. Aristophanes vervollkommnete die Komödie und verspottete Politiker und Philosophen schonungslos. Die Griechen glaubten, das Betrachten einer Tragödie bewirke Katharsis — eine reinigende Befreiung von Mitleid und Furcht, die die Bürger weiser und mitfühlender zurückließ." },
    fr: { heading: "La naissance du théâtre",
      body: "L'Athènes classique offrit le théâtre au monde. Le drame naquit des fêtes religieuses en l'honneur de Dionysos, dieu du vin et de l'extase, où des chœurs chantaient et dansaient. Au Ve siècle av. J.-C., les auteurs transformèrent ces rites en un art nouveau, joué dans d'immenses théâtres de plein air taillés à flanc de colline ; certains pouvaient accueillir plus de 15 000 spectateurs, avec une acoustique si fine qu'un murmure sur scène parvenait au dernier rang.\n\nTrois grands tragiques — Eschyle, Sophocle et Euripide — sondèrent le destin, la justice et la souffrance humaine dans des pièces encore jouées aujourd'hui, d'Œdipe roi à Antigone. Aristophane perfectionna la comédie, raillant sans pitié politiciens et philosophes. Les Grecs croyaient que regarder une tragédie produisait la catharsis, une libération purificatrice de la pitié et de la peur qui rendait les citoyens plus sages et plus humains." },
  },
  'ancient-03': {
    en: { heading: "The Legions: Engine of Empire",
      body: "Rome's empire was built and held by the most formidable military machine of the ancient world: the legion. Each legion of roughly 5,000 men was divided into cohorts and centuries, drilled into a discipline so relentless that the Jewish historian Josephus called their exercises 'bloodless battles and their battles bloody exercises.' Around 107 BCE the general Marius opened the ranks to landless citizens, turning the army into a profession and giving soldiers a stake in their commanders' success.\n\nBeyond fighting, legionaries were builders. On campaign they raised a fortified camp every night; in peacetime they paved roads, dug aqueducts, and threw bridges across rivers. Twenty-five years of service earned a soldier Roman citizenship or a plot of land, spreading Roman culture to every frontier. Yet the army's loyalty to its generals rather than the state also made it the maker — and destroyer — of emperors." },
    es: { heading: "Las legiones: motor del imperio",
      body: "El imperio de Roma fue construido y sostenido por la máquina militar más formidable del mundo antiguo: la legión. Cada legión, de unos 5.000 hombres, se dividía en cohortes y centurias, adiestradas con una disciplina tan implacable que el historiador judío Josefo llamó a sus ejercicios 'batallas sin sangre, y a sus batallas ejercicios sangrientos'. Hacia el 107 a.C. el general Mario abrió las filas a los ciudadanos sin tierra, convirtiendo el ejército en una profesión y dando a los soldados un interés en el éxito de sus jefes.\n\nAdemás de combatir, los legionarios eran constructores. En campaña levantaban un campamento fortificado cada noche; en tiempos de paz pavimentaban calzadas, excavaban acueductos y tendían puentes sobre los ríos. Veinticinco años de servicio daban al soldado la ciudadanía romana o una parcela de tierra, difundiendo la cultura romana por cada frontera. Pero la lealtad del ejército a sus generales, más que al Estado, lo convirtió también en el hacedor —y destructor— de emperadores." },
    ru: { heading: "Легионы: двигатель империи",
      body: "Империю Рима создала и удерживала самая грозная военная машина древнего мира — легион. Каждый легион примерно из 5000 человек делился на когорты и центурии, вымуштрованные с такой беспощадной дисциплиной, что иудейский историк Иосиф Флавий называл их учения «бескровными сражениями, а сражения — кровавыми учениями». Около 107 г. до н.э. полководец Марий открыл ряды безземельным гражданам, превратив армию в профессию и дав солдатам заинтересованность в успехе своих командиров.\n\nЛегионеры были не только воинами, но и строителями. В походе они каждую ночь возводили укреплённый лагерь; в мирное время мостили дороги, копали акведуки и наводили мосты через реки. Двадцать пять лет службы приносили солдату римское гражданство или надел земли, разнося римскую культуру по всем рубежам. Но верность армии своим полководцам, а не государству, сделала её и создателем, и погубителем императоров." },
    mk: { heading: "Легиите: моторот на империјата",
      body: "Римската империја беше изградена и одржувана од најстрашната воена машина на античкиот свет — легијата. Секоја легија од околу 5.000 луѓе се делеше на кохорти и центурии, извежбани со толку немилосрдна дисциплина што еврејскиот историчар Јосиф Флавиј нивните вежби ги нарече „бескрвни битки, а битките — крвави вежби“. Околу 107 п.н.е. војсководецот Мариј ги отвори редовите за безземјашките граѓани, претворајќи ја војската во професија и давајќи им на војниците интерес за успехот на своите команданти.\n\nОсвен што се бореа, легионерите беа и градители. На поход секоја ноќ подигаа утврден логор; во мирнодопски услови поплочуваа патишта, копаа аквадукти и фрлаа мостови преку реките. Дваесет и пет години служба му носеа на војникот римско државјанство или парче земја, ширејќи ја римската култура по секоја граница. Но верноста на војската кон своите војсководци, а не кон државата, ја направи и создавач и уништувач на императорите." },
    de: { heading: "Die Legionen: Motor des Reiches",
      body: "Roms Reich wurde von der furchterregendsten Militärmaschine der Antike errichtet und gehalten: der Legion. Jede Legion von rund 5.000 Mann war in Kohorten und Zenturien gegliedert und mit einer so unerbittlichen Disziplin gedrillt, dass der jüdische Geschichtsschreiber Josephus ihre Übungen 'unblutige Schlachten und ihre Schlachten blutige Übungen' nannte. Um 107 v. Chr. öffnete der Feldherr Marius die Reihen für besitzlose Bürger und machte das Heer zum Beruf, sodass die Soldaten am Erfolg ihrer Feldherren beteiligt waren.\n\nDie Legionäre waren nicht nur Kämpfer, sondern auch Baumeister. Auf dem Feldzug errichteten sie jede Nacht ein befestigtes Lager; in Friedenszeiten pflasterten sie Straßen, gruben Aquädukte und schlugen Brücken über Flüsse. Fünfundzwanzig Dienstjahre brachten dem Soldaten das römische Bürgerrecht oder ein Stück Land und trugen die römische Kultur an jede Grenze. Doch die Treue des Heeres zu seinen Feldherren statt zum Staat machte es auch zum Macher — und Zerstörer — von Kaisern." },
    fr: { heading: "Les légions : moteur de l'empire",
      body: "L'empire de Rome fut bâti et maintenu par la plus redoutable machine militaire du monde antique : la légion. Chaque légion d'environ 5 000 hommes se divisait en cohortes et centuries, entraînées avec une discipline si implacable que l'historien juif Flavius Josèphe qualifiait leurs exercices de 'batailles sans effusion de sang, et leurs batailles d'exercices sanglants'. Vers 107 av. J.-C., le général Marius ouvrit les rangs aux citoyens sans terre, faisant de l'armée un métier et donnant aux soldats un intérêt dans le succès de leurs chefs.\n\nAu-delà du combat, les légionnaires étaient bâtisseurs. En campagne, ils dressaient chaque nuit un camp fortifié ; en temps de paix, ils pavaient des routes, creusaient des aqueducs et jetaient des ponts sur les rivières. Vingt-cinq ans de service valaient au soldat la citoyenneté romaine ou un lopin de terre, répandant la culture romaine sur chaque frontière. Mais la fidélité de l'armée à ses généraux plutôt qu'à l'État en fit aussi le faiseur — et le destructeur — d'empereurs." },
  },
  'ancient-04': {
    en: { heading: "Nomads of the Steppe",
      body: "The great settled empires of Persia, India, and China all shared one restless neighbor: the nomads of the Eurasian steppe. Mounted herders such as the Scythians and the Xiongnu mastered the horse and the composite bow, becoming the finest cavalry of the ancient world. Able to appear suddenly and vanish across grasslands that stretched thousands of kilometers, they raided rich farmland and taxed the caravans of the Silk Road.\n\nTheir pressure shaped history. China built and rebuilt the Great Wall to hold back the Xiongnu, whose confederation rivaled the Han in power. Persia's King Cyrus the Great died fighting steppe nomads. Far from being mere destroyers, these horse peoples carried goods, technologies, and ideas between distant civilizations, knitting the ancient world together even as they threatened it." },
    es: { heading: "Los nómadas de la estepa",
      body: "Los grandes imperios sedentarios de Persia, India y China compartían un vecino inquieto: los nómadas de la estepa euroasiática. Pastores a caballo como los escitas y los xiongnu dominaron el caballo y el arco compuesto, y se convirtieron en la mejor caballería del mundo antiguo. Capaces de aparecer de pronto y esfumarse por praderas que se extendían miles de kilómetros, saqueaban las ricas tierras de labor y cobraban tributo a las caravanas de la Ruta de la Seda.\n\nSu presión moldeó la historia. China construyó y reconstruyó la Gran Muralla para contener a los xiongnu, cuya confederación rivalizaba en poder con la dinastía Han. El rey persa Ciro el Grande murió luchando contra nómadas de la estepa. Lejos de ser simples destructores, estos pueblos jinetes transportaban mercancías, tecnologías e ideas entre civilizaciones lejanas, entrelazando el mundo antiguo aun cuando lo amenazaban." },
    ru: { heading: "Кочевники степи",
      body: "У великих оседлых империй Персии, Индии и Китая был один беспокойный сосед — кочевники евразийской степи. Конные скотоводы, такие как скифы и хунну, в совершенстве владели конём и составным луком и стали лучшей конницей древнего мира. Способные внезапно появиться и раствориться в травяных просторах, тянувшихся на тысячи километров, они разоряли богатые пашни и облагали данью караваны Шёлкового пути.\n\nИх натиск определял ход истории. Китай строил и перестраивал Великую стену, чтобы сдержать хунну, чей союз соперничал по мощи с империей Хань. Персидский царь Кир Великий погиб в войне со степными кочевниками. Отнюдь не будучи лишь разрушителями, эти конные народы переносили товары, технологии и идеи между далёкими цивилизациями, связывая древний мир, даже когда угрожали ему." },
    mk: { heading: "Номадите на степата",
      body: "Големите населени империи на Персија, Индија и Кина имаа еден немирен сосед: номадите на евроазиската степа. Коњанички сточари како Скитите и Ксионгну (Хунну) го совладаа коњот и сложениот лак и станаа најдобрата коњица на античкиот свет. Способни одненадеж да се појават и да исчезнат низ тревниците што се протегаа илјадници километри, ги пустошеа плодните ниви и им наплаќаа данок на караваните на Патот на свилата.\n\nНивниот притисок ја обликуваше историјата. Кина го градеше и повторно го градеше Кинескиот ѕид за да ги задржи Ксионгну, чија конфедерација се натпреваруваше со Хан по моќ. Персискиот крал Кир Велики загина борејќи се против степски номади. Далеку од тоа да бидат само уништувачи, овие коњанички народи пренесуваа стоки, технологии и идеи меѓу далечни цивилизации, поврзувајќи го античкиот свет дури и додека го загрозуваа." },
    de: { heading: "Nomaden der Steppe",
      body: "Die großen sesshaften Reiche Persiens, Indiens und Chinas hatten alle einen ruhelosen Nachbarn: die Nomaden der eurasischen Steppe. Berittene Hirten wie die Skythen und die Xiongnu beherrschten Pferd und Kompositbogen und wurden zur besten Reiterei der Antike. Fähig, plötzlich aufzutauchen und über tausende Kilometer weites Grasland wieder zu verschwinden, plünderten sie fruchtbares Ackerland und besteuerten die Karawanen der Seidenstraße.\n\nIhr Druck formte die Geschichte. China baute die Große Mauer immer wieder, um die Xiongnu abzuwehren, deren Bund es an Macht mit den Han aufnahm. Der persische König Kyros der Große fiel im Kampf gegen Steppennomaden. Weit davon entfernt, bloße Zerstörer zu sein, trugen diese Reitervölker Waren, Techniken und Ideen zwischen fernen Kulturen hin und her und verknüpften so die antike Welt, noch während sie sie bedrohten." },
    fr: { heading: "Les nomades de la steppe",
      body: "Les grands empires sédentaires de Perse, d'Inde et de Chine partageaient tous un voisin turbulent : les nomades de la steppe eurasienne. Des éleveurs cavaliers comme les Scythes et les Xiongnu maîtrisèrent le cheval et l'arc composite et devinrent la meilleure cavalerie du monde antique. Capables de surgir soudain et de s'évanouir dans des prairies longues de milliers de kilomètres, ils pillaient les riches terres cultivées et taxaient les caravanes de la route de la Soie.\n\nLeur pression façonna l'histoire. La Chine bâtit et rebâtit la Grande Muraille pour contenir les Xiongnu, dont la confédération rivalisait de puissance avec les Han. Le roi perse Cyrus le Grand mourut en combattant des nomades des steppes. Loin d'être de simples destructeurs, ces peuples cavaliers transportaient marchandises, techniques et idées entre des civilisations lointaines, tissant le monde antique alors même qu'ils le menaçaient." },
  },
  'ancient-05': {
    en: { heading: "Akhenaten and the Amarna Revolution",
      body: "Around 1350 BCE, the pharaoh Amenhotep IV launched the most radical religious revolution in Egyptian history. He renamed himself Akhenaten, abolished the worship of Egypt's traditional gods, and declared that only the Aten — the life-giving disk of the sun — was divine. He built a brand-new capital, Amarna, in the desert and closed the wealthy temples of Amun, shattering a priesthood that had rivaled the throne.\n\nAkhenaten's revolution transformed Egyptian art, which suddenly portrayed the royal family with intimate, almost tender realism, alongside his famous queen Nefertiti. But the experiment did not outlive him. His young successor — the boy-king Tutankhamun — restored the old gods and moved the court back to Thebes. Priests erased Akhenaten's name from monuments, and his heretic city crumbled into the sand, forgotten until archaeologists uncovered it more than three thousand years later." },
    es: { heading: "Akhenatón y la revolución de Amarna",
      body: "Hacia el 1350 a.C., el faraón Amenhotep IV lanzó la revolución religiosa más radical de la historia egipcia. Se rebautizó como Akhenatón, abolió el culto a los dioses tradicionales de Egipto y declaró que solo el Atón —el disco solar que da la vida— era divino. Construyó una capital totalmente nueva, Amarna, en el desierto, y cerró los ricos templos de Amón, quebrando a un clero que había rivalizado con el trono.\n\nLa revolución de Akhenatón transformó el arte egipcio, que de pronto retrató a la familia real con un realismo íntimo, casi tierno, junto a su célebre reina Nefertiti. Pero el experimento no le sobrevivió. Su joven sucesor —el niño-rey Tutankamón— restauró a los viejos dioses y devolvió la corte a Tebas. Los sacerdotes borraron el nombre de Akhenatón de los monumentos, y su ciudad herética se deshizo en la arena, olvidada hasta que los arqueólogos la descubrieron más de tres mil años después." },
    ru: { heading: "Эхнатон и Амарнская революция",
      body: "Около 1350 г. до н.э. фараон Аменхотеп IV начал самую радикальную религиозную революцию в истории Египта. Он переименовал себя в Эхнатона, отменил почитание традиционных египетских богов и объявил, что божественен лишь Атон — дарующий жизнь солнечный диск. Он построил совершенно новую столицу, Амарну, посреди пустыни и закрыл богатые храмы Амона, сокрушив жречество, которое соперничало с троном.\n\nРеволюция Эхнатона преобразила египетское искусство, которое вдруг стало изображать царскую семью с интимным, почти нежным реализмом, рядом с его знаменитой царицей Нефертити. Но эксперимент не пережил своего создателя. Его юный преемник — мальчик-царь Тутанхамон — восстановил старых богов и вернул двор в Фивы. Жрецы стёрли имя Эхнатона с памятников, а его еретический город рассыпался в песок и был забыт, пока археологи не раскопали его более трёх тысяч лет спустя." },
    mk: { heading: "Ехнатон и револуцијата во Амарна",
      body: "Околу 1350 п.н.е. фараонот Аменхотеп IV ја започна најрадикалната верска револуција во египетската историја. Се преименува во Ехнатон, го укина обожавањето на традиционалните египетски богови и објави дека само Атон — животодавниот сончев диск — е божествен. Изгради сосема нова престолнина, Амарна, во пустината и ги затвори богатите храмови на Амон, кршејќи го свештенството што му конкурираше на престолот.\n\nРеволуцијата на Ехнатон ја преобрази египетската уметност, која одеднаш ја прикажуваше кралската фамилија со интимен, речиси нежен реализам, заедно со неговата прочуена кралица Нефертити. Но експериментот не го надживеа неговиот творец. Неговиот млад наследник — детето-крал Тутанкамон — ги врати старите богови и го премести дворот назад во Теба. Свештениците го избришаа името на Ехнатон од спомениците, а неговиот еретички град се распадна во песокот, заборавен сè додека археолозите не го откопаа повеќе од три илјади години подоцна." },
    de: { heading: "Echnaton und die Amarna-Revolution",
      body: "Um 1350 v. Chr. entfachte der Pharao Amenophis IV. die radikalste religiöse Revolution der ägyptischen Geschichte. Er nannte sich Echnaton, schaffte die Verehrung der traditionellen Götter Ägyptens ab und erklärte allein den Aton — die lebenspendende Sonnenscheibe — für göttlich. Er baute mitten in der Wüste eine völlig neue Hauptstadt, Amarna, und schloss die reichen Amun-Tempel, womit er eine Priesterschaft brach, die mit dem Thron rivalisiert hatte.\n\nEchnatons Revolution wandelte die ägyptische Kunst, die plötzlich die königliche Familie mit inniger, fast zärtlicher Naturtreue zeigte, an seiner Seite die berühmte Königin Nofretete. Doch das Experiment überlebte ihn nicht. Sein junger Nachfolger — der Kindkönig Tutanchamun — stellte die alten Götter wieder her und verlegte den Hof zurück nach Theben. Priester tilgten Echnatons Namen von den Denkmälern, und seine Ketzerstadt zerfiel im Sand, vergessen, bis Archäologen sie mehr als dreitausend Jahre später freilegten." },
    fr: { heading: "Akhénaton et la révolution d'Amarna",
      body: "Vers 1350 av. J.-C., le pharaon Amenhotep IV déclencha la révolution religieuse la plus radicale de l'histoire égyptienne. Il se rebaptisa Akhénaton, abolit le culte des dieux traditionnels de l'Égypte et proclama que seul l'Aton — le disque solaire qui donne la vie — était divin. Il bâtit une capitale entièrement neuve, Amarna, en plein désert, et ferma les riches temples d'Amon, brisant un clergé qui avait rivalisé avec le trône.\n\nLa révolution d'Akhénaton transforma l'art égyptien, qui représenta soudain la famille royale avec un réalisme intime, presque tendre, aux côtés de sa célèbre reine Néfertiti. Mais l'expérience ne lui survécut pas. Son jeune successeur — le roi-enfant Toutânkhamon — rétablit les anciens dieux et ramena la cour à Thèbes. Les prêtres effacèrent le nom d'Akhénaton des monuments, et sa cité hérétique s'effrita dans le sable, oubliée jusqu'à ce que les archéologues la mettent au jour plus de trois mille ans plus tard." },
  },
  'ancient-06': {
    en: { heading: "Carthage: The Phoenician West",
      body: "As Phoenician traders pushed west across the Mediterranean, they planted colonies far from their Levantine homeland. The greatest of these, Carthage, was founded near modern Tunis around 814 BCE according to tradition, and grew into a maritime superpower in its own right. From its double harbor, Carthaginian fleets controlled the western sea lanes, mined silver in Spain, and traded for tin as far as the coasts of Britain.\n\nCarthage carried Phoenician culture — the gods Baal and Tanit, the alphabet, and a genius for commerce — deep into the western world. Its wealth eventually brought it into a titanic collision with Rome in the Punic Wars, a rivalry that would end in Carthage's destruction in 146 BCE. Yet for centuries Carthage had shown that the Phoenician model of seaborne trade could build an empire without the vast conquering armies of the East." },
    es: { heading: "Cartago: el Occidente fenicio",
      body: "A medida que los comerciantes fenicios se adentraban hacia el oeste del Mediterráneo, fundaron colonias lejos de su patria levantina. La mayor de ellas, Cartago, fue fundada cerca de la actual Túnez hacia el 814 a.C. según la tradición, y llegó a ser una superpotencia marítima por derecho propio. Desde su doble puerto, las flotas cartaginesas controlaban las rutas marítimas occidentales, extraían plata en Hispania y comerciaban estaño hasta las costas de Britania.\n\nCartago llevó la cultura fenicia —los dioses Baal y Tanit, el alfabeto y un genio para el comercio— hasta lo más profundo del mundo occidental. Su riqueza acabó llevándola a un choque titánico con Roma en las Guerras Púnicas, una rivalidad que terminaría con la destrucción de Cartago en el 146 a.C. Pero durante siglos Cartago había demostrado que el modelo fenicio de comercio marítimo podía construir un imperio sin los enormes ejércitos conquistadores de Oriente." },
    ru: { heading: "Карфаген: финикийский Запад",
      body: "По мере того как финикийские купцы продвигались на запад по Средиземноморью, они основывали колонии вдали от своей левантийской родины. Крупнейшая из них, Карфаген, по преданию был основан близ современного Туниса около 814 г. до н.э. и сам вырос в морскую сверхдержаву. Из своей двойной гавани карфагенские флоты держали западные морские пути, добывали серебро в Испании и торговали оловом до самых берегов Британии.\n\nКарфаген донёс финикийскую культуру — богов Ваала и Танит, алфавит и торговый гений — вглубь западного мира. Его богатство в конце концов привело к титаническому столкновению с Римом в Пунических войнах — соперничеству, которое завершилось разрушением Карфагена в 146 г. до н.э. Но на протяжении веков Карфаген доказывал, что финикийская модель морской торговли способна создать империю без огромных завоевательных армий Востока." },
    mk: { heading: "Картагина: финикискиот Запад",
      body: "Како што финикиските трговци навлегуваа на запад низ Медитеранот, засадуваа колонии далеку од својата левантска татковина. Најголемата од нив, Картагина, според преданието била основана близу денешен Тунис околу 814 п.н.е. и самата прераснала во поморска суперсила. Од своето двојно пристаниште, картагинските флоти ги контролираа западните морски патишта, копаа сребро во Шпанија и тргуваа со калај дури до бреговите на Британија.\n\nКартагина ја пренесе финикиската култура — боговите Ваал и Танит, азбуката и генијот за трговија — длабоко во западниот свет. Нејзиното богатство на крајот ја доведе до титански судир со Рим во Пунските војни — ривалство што ќе заврши со уништувањето на Картагина во 146 п.н.е. Но со векови Картагина покажуваше дека финикискиот модел на поморска трговија може да изгради империја без огромните освојувачки војски на Истокот." },
    de: { heading: "Karthago: der phönizische Westen",
      body: "Als phönizische Händler nach Westen über das Mittelmeer vorstießen, gründeten sie Kolonien fern ihrer levantinischen Heimat. Die größte davon, Karthago, wurde der Überlieferung nach um 814 v. Chr. nahe dem heutigen Tunis gegründet und wuchs selbst zu einer Seemacht heran. Von ihrem Doppelhafen aus beherrschten karthagische Flotten die westlichen Seewege, förderten Silber in Spanien und handelten Zinn bis zu den Küsten Britanniens.\n\nKarthago trug die phönizische Kultur — die Götter Baal und Tanit, das Alphabet und einen Sinn für Handel — tief in die westliche Welt. Sein Reichtum führte es schließlich in einen titanischen Zusammenstoß mit Rom in den Punischen Kriegen, einer Rivalität, die 146 v. Chr. mit der Zerstörung Karthagos endete. Doch jahrhundertelang hatte Karthago gezeigt, dass das phönizische Modell des Seehandels ein Reich errichten konnte, ohne die gewaltigen Eroberungsheere des Ostens." },
    fr: { heading: "Carthage : l'Occident phénicien",
      body: "À mesure que les marchands phéniciens progressaient vers l'ouest de la Méditerranée, ils fondèrent des colonies loin de leur patrie levantine. La plus grande, Carthage, fut fondée près de l'actuelle Tunis vers 814 av. J.-C. selon la tradition, et devint elle-même une superpuissance maritime. Depuis son double port, les flottes carthaginoises contrôlaient les routes maritimes occidentales, exploitaient l'argent d'Espagne et échangeaient l'étain jusqu'aux côtes de la Bretagne.\n\nCarthage porta la culture phénicienne — les dieux Baal et Tanit, l'alphabet et un génie du commerce — jusqu'au cœur du monde occidental. Sa richesse finit par la précipiter dans un choc titanesque avec Rome lors des guerres puniques, une rivalité qui s'acheva par la destruction de Carthage en 146 av. J.-C. Mais pendant des siècles, Carthage avait montré que le modèle phénicien du commerce maritime pouvait bâtir un empire sans les vastes armées conquérantes de l'Orient." },
  },
  'ancient-07': {
    en: { heading: "Philip's War Machine: The Macedonian Phalanx",
      body: "Alexander the Great conquered the world with an army perfected by his father, King Philip II. Philip reforged the Macedonian infantry into the phalanx, a bristling block of soldiers wielding the sarissa — a pike up to six meters long. Rank upon rank lowered their pikes, presenting the enemy with an impenetrable hedge of iron points that no frontal charge could break.\n\nBut the phalanx was only the anvil. Philip paired it with the hammer: the Companion Cavalry, elite horsemen who charged the enemy's flank at the decisive moment. This 'hammer and anvil' tactic — pinning the foe with pikes while cavalry shattered their side — made the Macedonian army the deadliest of its age. Alexander wielded it with genius at Issus and Gaugamela, toppling the vast Persian Empire with a force a fraction of its size." },
    es: { heading: "La máquina de guerra de Filipo: la falange macedonia",
      body: "Alejandro Magno conquistó el mundo con un ejército perfeccionado por su padre, el rey Filipo II. Filipo reforjó la infantería macedonia en la falange, un bloque erizado de soldados que empuñaban la sarisa, una pica de hasta seis metros de largo. Fila tras fila bajaban sus picas, presentando al enemigo un seto impenetrable de puntas de hierro que ninguna carga frontal podía romper.\n\nPero la falange era solo el yunque. Filipo la combinó con el martillo: la Caballería de los Compañeros, jinetes de élite que cargaban contra el flanco enemigo en el momento decisivo. Esta táctica de 'martillo y yunque' —fijar al adversario con las picas mientras la caballería destrozaba su costado— convirtió al ejército macedonio en el más letal de su época. Alejandro la empleó con genialidad en Issos y Gaugamela, derribando el vasto Imperio persa con una fuerza mucho menor." },
    ru: { heading: "Военная машина Филиппа: македонская фаланга",
      body: "Александр Македонский покорил мир с армией, доведённой до совершенства его отцом, царём Филиппом II. Филипп перековал македонскую пехоту в фалангу — ощетинившийся строй воинов с сариссами, пиками длиной до шести метров. Ряд за рядом опускали свои пики, выставляя перед врагом непроницаемую изгородь железных наконечников, которую не могла пробить никакая лобовая атака.\n\nНо фаланга была лишь наковальней. Филипп соединил её с молотом — гетайрами, отборной конницей, которая в решающий миг обрушивалась на фланг врага. Эта тактика «молота и наковальни» — сковать противника пиками, пока конница крушит его бок, — сделала македонскую армию самой смертоносной в своё время. Александр применял её с гениальностью при Иссе и Гавгамелах, сокрушив огромную Персидскую державу силами во много раз меньшими." },
    mk: { heading: "Воената машина на Филип: македонската фаланга",
      body: "Александар Македонски го освои светот со војска усовршена од неговиот татко, кралот Филип II. Филип ја претвори македонската пешадија во фаланга — наежен блок војници што ја носеа сарисата, копје долго до шест метри. Ред по ред ги спуштаа копјата, покажувајќи му на непријателот непробоен плот од железни врвови што ниеден фронтален јуриш не можеше да го скрши.\n\nНо фалангата беше само наковалната. Филип ја спои со чеканот: Хетајрите, елитни коњаници што во одлучувачкиот миг удираа по крилото на непријателот. Оваа тактика на „чекан и наковална“ — да се закове противникот со копјата додека коњицата му го крши бокот — ја направи македонската војска најсмртоносна во своето време. Александар ја применуваше со гениј кај Ис и Гавгамела, соборувајќи ја огромната Персиска империја со сила многу помала од нејзината." },
    de: { heading: "Philipps Kriegsmaschine: die makedonische Phalanx",
      body: "Alexander der Große eroberte die Welt mit einem Heer, das sein Vater, König Philipp II., vervollkommnet hatte. Philipp formte die makedonische Infanterie zur Phalanx um, einem starrenden Block von Soldaten mit der Sarisse, einer bis zu sechs Meter langen Pike. Reihe um Reihe senkten sie ihre Piken und boten dem Feind eine undurchdringliche Hecke eiserner Spitzen, die kein Frontalangriff brechen konnte.\n\nDoch die Phalanx war nur der Amboss. Philipp verband sie mit dem Hammer: der Hetairenreiterei, edlen Reitern, die im entscheidenden Augenblick die Flanke des Feindes anfielen. Diese Taktik von 'Hammer und Amboss' — den Gegner mit Piken festnageln, während die Reiterei seine Seite zerschlug — machte das makedonische Heer zum tödlichsten seiner Zeit. Alexander führte sie mit Genie bei Issos und Gaugamela und stürzte das riesige Perserreich mit einer weit kleineren Streitmacht." },
    fr: { heading: "La machine de guerre de Philippe : la phalange macédonienne",
      body: "Alexandre le Grand conquit le monde avec une armée perfectionnée par son père, le roi Philippe II. Philippe refondit l'infanterie macédonienne en phalange, un bloc hérissé de soldats maniant la sarisse, une pique longue de six mètres. Rang après rang, ils abaissaient leurs piques, opposant à l'ennemi une haie impénétrable de pointes de fer qu'aucune charge frontale ne pouvait rompre.\n\nMais la phalange n'était que l'enclume. Philippe l'associa au marteau : la cavalerie des Compagnons, cavaliers d'élite qui chargeaient le flanc ennemi à l'instant décisif. Cette tactique du 'marteau et de l'enclume' — fixer l'adversaire avec les piques tandis que la cavalerie brisait son flanc — fit de l'armée macédonienne la plus meurtrière de son temps. Alexandre la manœuvra avec génie à Issos et à Gaugamèles, renversant le vaste Empire perse avec une force bien moindre." },
  },
  'ancient-08': {
    en: { heading: "Machines and Marvels: Hellenistic Science",
      body: "The Hellenistic age was one of the most inventive eras before the modern world. In the cosmopolitan cities founded after Alexander, Greek reasoning met the deep records of Babylon and Egypt, and the result was an explosion of science. Archimedes of Syracuse calculated pi, explained the lever and buoyancy, and built ingenious war machines. Ctesibius and Hero of Alexandria designed pumps, water clocks, and even a spinning sphere driven by steam.\n\nThe most astonishing survival is the Antikythera mechanism, a bronze device of more than thirty interlocking gears recovered from a shipwreck. It could track the movements of the sun, moon, and planets and forecast eclipses — an analog computer two thousand years ahead of anything comparable. Such marvels reveal a Hellenistic world probing nature with a precision and ambition that would not be matched again until the Renaissance." },
    es: { heading: "Máquinas y maravillas: la ciencia helenística",
      body: "La era helenística fue una de las más inventivas antes del mundo moderno. En las ciudades cosmopolitas fundadas tras Alejandro, el razonamiento griego se encontró con los profundos registros de Babilonia y Egipto, y el resultado fue una explosión de ciencia. Arquímedes de Siracusa calculó el número pi, explicó la palanca y la flotabilidad y construyó ingeniosas máquinas de guerra. Ctesibio y Herón de Alejandría diseñaron bombas, relojes de agua e incluso una esfera giratoria impulsada por vapor.\n\nEl hallazgo más asombroso es el mecanismo de Anticitera, un artefacto de bronce con más de treinta engranajes entrelazados rescatado de un naufragio. Podía seguir los movimientos del sol, la luna y los planetas y anticipar eclipses: una computadora analógica dos mil años por delante de cualquier cosa comparable. Tales maravillas revelan un mundo helenístico que sondeaba la naturaleza con una precisión y una ambición que no volverían a igualarse hasta el Renacimiento." },
    ru: { heading: "Машины и чудеса: эллинистическая наука",
      body: "Эллинистическая эпоха была одной из самых изобретательных до Нового времени. В космополитичных городах, основанных после Александра, греческое мышление встретилось с обширными записями Вавилона и Египта, и результатом стал взрыв науки. Архимед из Сиракуз вычислил число пи, объяснил рычаг и закон плавучести и построил хитроумные боевые машины. Ктесибий и Герон Александрийский создавали насосы, водяные часы и даже вращающийся шар, приводимый в движение паром.\n\nСамая поразительная находка — антикитерский механизм, бронзовое устройство из более чем тридцати сцепленных шестерён, поднятое с затонувшего корабля. Оно могло отслеживать движения Солнца, Луны и планет и рассчитывать затмения — аналоговый вычислитель, на две тысячи лет опередивший всё сопоставимое. Такие чудеса открывают эллинистический мир, исследовавший природу с точностью и размахом, которые повторятся лишь в эпоху Возрождения." },
    mk: { heading: "Машини и чуда: хеленистичката наука",
      body: "Хеленистичката ера беше една од најизумителните пред современиот свет. Во космополитските градови основани по Александар, грчкото расудување се сретна со длабоките записи на Вавилон и Египет, и резултатот беше експлозија на наука. Архимед од Сиракуза го пресмета бројот пи, ги објасни полугата и потисокот и изгради досетливи воени машини. Ктесибиј и Херон Александриски создаваа пумпи, водени часовници, па дури и вртлива сфера погонувана од пареа.\n\nНајзачудувачкиот наод е механизмот од Антикитера, бронзена направа од повеќе од триесет заплеткани запчаници извадена од бродолом. Можеше да ги следи движењата на Сонцето, Месечината и планетите и да пресметува затемнувања — аналоген сметач две илјади години пред сè споредливо. Ваквите чуда откриваат хеленистички свет што ја испитуваше природата со прецизност и амбиција што повторно ќе се достигнат дури во ренесансата." },
    de: { heading: "Maschinen und Wunder: hellenistische Wissenschaft",
      body: "Das hellenistische Zeitalter zählte zu den erfinderischsten vor der Neuzeit. In den weltoffenen Städten, die nach Alexander entstanden, traf griechisches Denken auf die reichen Aufzeichnungen Babylons und Ägyptens, und das Ergebnis war ein Aufbruch der Wissenschaft. Archimedes von Syrakus berechnete die Zahl Pi, erklärte Hebel und Auftrieb und baute sinnreiche Kriegsmaschinen. Ktesibios und Heron von Alexandria entwarfen Pumpen, Wasseruhren und sogar eine dampfgetriebene, sich drehende Kugel.\n\nDer erstaunlichste Fund ist der Mechanismus von Antikythera, ein Bronzegerät aus über dreißig ineinandergreifenden Zahnrädern, geborgen aus einem Schiffswrack. Es konnte die Bewegungen von Sonne, Mond und Planeten verfolgen und Finsternisse berechnen — ein Analogrechner, der allem Vergleichbaren um zweitausend Jahre voraus war. Solche Wunder zeigen eine hellenistische Welt, die die Natur mit einer Genauigkeit und einem Ehrgeiz erforschte, die erst in der Renaissance wieder erreicht wurden." },
    fr: { heading: "Machines et merveilles : la science hellénistique",
      body: "L'âge hellénistique fut l'un des plus inventifs avant le monde moderne. Dans les villes cosmopolites fondées après Alexandre, la raison grecque rencontra les archives profondes de Babylone et d'Égypte, et il en résulta une explosion scientifique. Archimède de Syracuse calcula le nombre pi, expliqua le levier et la poussée d'Archimède et bâtit d'ingénieuses machines de guerre. Ctésibios et Héron d'Alexandrie conçurent des pompes, des horloges à eau et même une sphère tournante mue par la vapeur.\n\nLe vestige le plus stupéfiant est la machine d'Anticythère, un appareil de bronze de plus de trente engrenages imbriqués, repêché d'une épave. Elle pouvait suivre les mouvements du soleil, de la lune et des planètes et annoncer les éclipses — un calculateur analogique en avance de deux mille ans sur tout ce qui lui était comparable. De telles merveilles révèlent un monde hellénistique sondant la nature avec une précision et une ambition qui ne seraient égalées qu'à la Renaissance." },
  },
  'ancient-09': {
    en: { heading: "Zoroaster and the Religion of Fire",
      body: "The Persian Empire was bound together not only by roads and satraps but by one of the world's oldest revealed religions: Zoroastrianism. Its prophet, Zarathustra (Zoroaster), taught that the universe is a battleground between Ahura Mazda, the god of light and truth, and the forces of the lie and darkness. Every person, by choosing good thoughts, good words, and good deeds, joins the cosmic struggle on the side of order.\n\nThe Achaemenid kings honored Ahura Mazda and tended sacred fires that symbolized his purity — fires kept burning in temples for generations. Zoroastrian ideas — a single supreme god, a final judgment, heaven and hell, and a coming savior — would echo through Judaism, Christianity, and Islam. Though few Zoroastrians remain today, their faith shaped the moral imagination of half the world." },
    es: { heading: "Zoroastro y la religión del fuego",
      body: "El Imperio persa estaba unido no solo por caminos y sátrapas, sino por una de las religiones reveladas más antiguas del mundo: el zoroastrismo. Su profeta, Zaratustra (Zoroastro), enseñó que el universo es un campo de batalla entre Ahura Mazda, el dios de la luz y la verdad, y las fuerzas de la mentira y la oscuridad. Cada persona, al elegir buenos pensamientos, buenas palabras y buenas obras, se une a la lucha cósmica del lado del orden.\n\nLos reyes aqueménidas honraban a Ahura Mazda y cuidaban fuegos sagrados que simbolizaban su pureza, fuegos mantenidos encendidos en los templos durante generaciones. Las ideas zoroástricas —un único dios supremo, un juicio final, el cielo y el infierno, y un salvador venidero— resonarían en el judaísmo, el cristianismo y el islam. Aunque hoy quedan pocos zoroastrianos, su fe moldeó la imaginación moral de medio mundo." },
    ru: { heading: "Заратустра и религия огня",
      body: "Персидскую державу связывали воедино не только дороги и сатрапы, но и одна из древнейших религий откровения — зороастризм. Его пророк Заратустра (Зороастр) учил, что вселенная есть поле битвы между Ахура-Маздой, богом света и истины, и силами лжи и тьмы. Каждый человек, избирая благие мысли, благие слова и благие дела, встаёт в космической борьбе на сторону порядка.\n\nАхеменидские цари чтили Ахура-Мазду и поддерживали священные огни, символ его чистоты, — огни, горевшие в храмах из поколения в поколение. Зороастрийские идеи — единый верховный бог, окончательный суд, рай и ад, грядущий спаситель — отзовутся в иудаизме, христианстве и исламе. Хотя зороастрийцев ныне немного, их вера сформировала нравственное воображение половины мира." },
    mk: { heading: "Заратустра и религијата на огнот",
      body: "Персиската империја беше поврзана не само со патишта и сатрапи, туку и со една од најстарите откриени религии на светот: зороастризмот. Неговиот пророк Заратустра (Зороастер) учеше дека вселената е бојно поле меѓу Ахура Мазда, богот на светлината и вистината, и силите на лагата и темнината. Секој човек, избирајќи добри мисли, добри зборови и добри дела, се приклучува на космичката борба на страната на редот.\n\nАхеменидските кралеви го почитуваа Ахура Мазда и одржуваа свети огнови што ја симболизираа неговата чистота — огнови што горееја во храмовите со поколенија. Зороастриските идеи — единствен врховен бог, конечен суд, рај и пекол, и иден спасител — ќе одекнат низ јудаизмот, христијанството и исламот. Иако денес останале малку зороастријци, нивната вера ја обликуваше моралната имагинација на половина свет." },
    de: { heading: "Zarathustra und die Religion des Feuers",
      body: "Das Perserreich wurde nicht nur durch Straßen und Satrapen zusammengehalten, sondern durch eine der ältesten Offenbarungsreligionen der Welt: den Zoroastrismus. Sein Prophet Zarathustra (Zoroaster) lehrte, das Universum sei ein Schlachtfeld zwischen Ahura Mazda, dem Gott des Lichts und der Wahrheit, und den Mächten der Lüge und Finsternis. Jeder Mensch tritt, indem er gute Gedanken, gute Worte und gute Taten wählt, im kosmischen Kampf auf die Seite der Ordnung.\n\nDie Achämenidenkönige ehrten Ahura Mazda und pflegten heilige Feuer, die seine Reinheit versinnbildlichten — Feuer, die über Generationen in Tempeln brannten. Zoroastrische Vorstellungen — ein einziger höchster Gott, ein Jüngstes Gericht, Himmel und Hölle und ein kommender Erlöser — sollten in Judentum, Christentum und Islam nachhallen. Auch wenn heute nur wenige Zoroastrier leben, prägte ihr Glaube die moralische Vorstellungswelt der halben Menschheit." },
    fr: { heading: "Zoroastre et la religion du feu",
      body: "L'Empire perse était uni non seulement par des routes et des satrapes, mais par l'une des plus anciennes religions révélées du monde : le zoroastrisme. Son prophète, Zarathoustra (Zoroastre), enseignait que l'univers est un champ de bataille entre Ahura Mazda, le dieu de la lumière et de la vérité, et les forces du mensonge et des ténèbres. Chaque être humain, en choisissant les bonnes pensées, les bonnes paroles et les bonnes actions, rejoint le combat cosmique du côté de l'ordre.\n\nLes rois achéménides honoraient Ahura Mazda et entretenaient des feux sacrés symbolisant sa pureté — des feux maintenus allumés dans les temples pendant des générations. Les idées zoroastriennes — un dieu suprême unique, un jugement dernier, le paradis et l'enfer, et un sauveur à venir — résonneraient dans le judaïsme, le christianisme et l'islam. Bien que peu de zoroastriens subsistent aujourd'hui, leur foi façonna l'imaginaire moral de la moitié du monde." },
  },

  // ══════════════════════════ MIDDLE AGES ══════════════════════════
  'medieval-01': {
    en: { heading: "Monasteries: Islands of Learning",
      body: "As Roman order dissolved, Christian monasteries became the quiet strongholds of learning in Western Europe. Following the Rule of Saint Benedict (c.529), monks lived by the motto 'pray and work,' dividing their days between worship, labor, and study. In their scriptoria, monks copied and recopied the Bible alongside the works of Roman authors, preserving texts that would otherwise have vanished.\n\nIrish monasteries were especially vital. Cut off from the collapse on the continent, Irish monks safeguarded Greek and Latin learning and then sailed out to re-found schools across Britain and Europe. Beyond books, monasteries cleared forests, drained marshes, brewed, farmed, and cared for the sick and the traveler. For centuries they were the single most important institution keeping literacy, agriculture, and charity alive." },
    es: { heading: "Islas de saber: los monasterios",
      body: "A medida que el orden romano se disolvía, los monasterios cristianos se convirtieron en los baluartes silenciosos del saber en Europa occidental. Siguiendo la Regla de San Benito (c.529), los monjes vivían bajo el lema 'ora y trabaja', repartiendo sus días entre el culto, el trabajo y el estudio. En sus scriptoria copiaban y recopiaban la Biblia junto a las obras de autores romanos, preservando textos que de otro modo se habrían perdido.\n\nLos monasterios irlandeses fueron especialmente vitales. Aislados del colapso del continente, los monjes irlandeses custodiaron el saber griego y latino y luego navegaron para refundar escuelas por toda Britania y Europa. Más allá de los libros, los monasterios talaban bosques, drenaban pantanos, elaboraban cerveza, cultivaban y cuidaban a los enfermos y a los viajeros. Durante siglos fueron la institución más importante para mantener vivas la alfabetización, la agricultura y la caridad." },
    ru: { heading: "Монастыри — острова учёности",
      body: "По мере распада римского порядка христианские монастыри стали тихими оплотами учёности в Западной Европе. Следуя Уставу святого Бенедикта (ок. 529), монахи жили по правилу «молись и трудись», деля дни между богослужением, трудом и учением. В своих скрипториях они переписывали и вновь переписывали Библию вместе с сочинениями римских авторов, сохраняя тексты, которые иначе исчезли бы.\n\nОсобенно важны были ирландские монастыри. Отрезанные от катастрофы на континенте, ирландские монахи сберегли греческую и латинскую учёность, а затем отплыли, чтобы заново основать школы по всей Британии и Европе. Помимо книг, монастыри расчищали леса, осушали болота, варили пиво, возделывали землю и заботились о больных и странниках. На протяжении веков они были важнейшим учреждением, поддерживавшим грамотность, земледелие и милосердие." },
    mk: { heading: "Манастирите — острови на учењето",
      body: "Како што римскиот поредок се распаѓаше, христијанските манастири станаа тивки тврдини на учењето во Западна Европа. Следејќи го Правилото на свети Бенедикт (о. 529), монасите живееја под мотото „моли се и работи“, делејќи ги деновите меѓу богослужение, труд и учење. Во своите скрипториуми ја препишуваа и повторно ја препишуваа Библијата заедно со делата на римските автори, зачувувајќи текстови што инаку би исчезнале.\n\nИрските манастири беа особено важни. Отсечени од распадот на континентот, ирските монаси го зачуваа грчкото и латинското знаење, а потоа отпловија за одново да основаат училишта низ Британија и Европа. Освен книгите, манастирите крчеа шуми, исушуваа мочуришта, вареа пиво, обработуваа земја и се грижеа за болните и патниците. Со векови беа најважната институција што ја одржуваше писменоста, земјоделството и милосрдието." },
    de: { heading: "Klöster: Inseln der Gelehrsamkeit",
      body: "Als die römische Ordnung zerfiel, wurden christliche Klöster zu den stillen Bollwerken der Gelehrsamkeit im Westen Europas. Nach der Regel des heiligen Benedikt (um 529) lebten die Mönche unter dem Leitwort 'bete und arbeite' und teilten ihre Tage zwischen Gottesdienst, Arbeit und Studium. In ihren Skriptorien schrieben sie die Bibel neben den Werken römischer Autoren immer wieder ab und bewahrten so Texte, die sonst verschwunden wären.\n\nDie irischen Klöster waren besonders wichtig. Vom Zusammenbruch auf dem Festland abgeschnitten, hüteten irische Mönche das griechische und lateinische Wissen und segelten dann aus, um Schulen in ganz Britannien und Europa neu zu gründen. Über Bücher hinaus rodeten Klöster Wälder, entwässerten Sümpfe, brauten, ackerten und pflegten Kranke und Reisende. Jahrhundertelang waren sie die wichtigste Einrichtung, die Bildung, Landwirtschaft und Nächstenliebe am Leben hielt." },
    fr: { heading: "Les monastères : îlots de savoir",
      body: "À mesure que l'ordre romain se dissolvait, les monastères chrétiens devinrent les bastions silencieux du savoir en Europe occidentale. Suivant la Règle de saint Benoît (v. 529), les moines vivaient selon la devise 'prie et travaille', partageant leurs journées entre le culte, le labeur et l'étude. Dans leurs scriptoria, ils copiaient et recopiaient la Bible aux côtés des œuvres des auteurs romains, préservant des textes qui, sans eux, auraient disparu.\n\nLes monastères irlandais furent particulièrement précieux. Coupés de l'effondrement du continent, les moines irlandais sauvegardèrent le savoir grec et latin, puis prirent la mer pour refonder des écoles à travers la Grande-Bretagne et l'Europe. Au-delà des livres, les monastères défrichaient les forêts, asséchaient les marais, brassaient, cultivaient et soignaient les malades et les voyageurs. Pendant des siècles, ils furent l'institution la plus essentielle au maintien de l'alphabétisation, de l'agriculture et de la charité." },
  },
  'medieval-02': {
    en: { heading: "Manzikert: The Battle That Sparked the Crusades",
      body: "The Crusades did not begin in a vacuum. In 1071, at Manzikert in eastern Anatolia, the Seljuk Turkish sultan Alp Arslan crushed the army of the Byzantine emperor Romanos IV and took him prisoner. The defeat tore open Byzantium's frontier, and Turkish nomads poured into Asia Minor — the empire's richest recruiting ground and breadbasket.\n\nDesperate, the Byzantine emperor Alexios I appealed to the Latin West for mercenaries to help recover his lost lands. Pope Urban II answered in 1095 with something far larger than the emperor expected: a call for an armed pilgrimage to free Jerusalem. Thus a single lost battle on a distant plateau set in motion two centuries of holy war between Christendom and Islam." },
    es: { heading: "Manzikert: la batalla que encendió las Cruzadas",
      body: "Las Cruzadas no surgieron de la nada. En 1071, en Manzikert, en el este de Anatolia, el sultán turco selyúcida Alp Arslan aplastó al ejército del emperador bizantino Romano IV y lo hizo prisionero. La derrota abrió de par en par la frontera de Bizancio, y los nómadas turcos se derramaron por Asia Menor, la región más rica en reclutas y el granero del imperio.\n\nDesesperado, el emperador bizantino Alejo I pidió a Occidente mercenarios para recuperar sus tierras perdidas. El papa Urbano II respondió en 1095 con algo mucho mayor de lo que el emperador esperaba: un llamamiento a una peregrinación armada para liberar Jerusalén. Así, una sola batalla perdida en una meseta lejana puso en marcha dos siglos de guerra santa entre la cristiandad y el islam." },
    ru: { heading: "Манцикерт: битва, зажёгшая Крестовые походы",
      body: "Крестовые походы возникли не на пустом месте. В 1071 году при Манцикерте в восточной Анатолии сельджукский султан Алп-Арслан разгромил войско византийского императора Романа IV и взял его в плен. Поражение распахнуло границу Византии, и турецкие кочевники хлынули в Малую Азию — богатейший источник рекрутов и житницу империи.\n\nВ отчаянии византийский император Алексей I обратился к латинскому Западу за наёмниками, чтобы вернуть утраченные земли. Папа Урбан II ответил в 1095 году чем-то куда большим, чем ожидал император, — призывом к вооружённому паломничеству ради освобождения Иерусалима. Так одна проигранная битва на далёком плоскогорье привела в движение два столетия священной войны между христианством и исламом." },
    mk: { heading: "Манцикерт: битката што ги запали Крстоносните војни",
      body: "Крстоносните војни не се појавија од ништо. Во 1071 година, кај Манцикерт во источна Анадолија, селџучкиот турски султан Алп Арслан ја смачка војската на византискиот император Роман IV и го зароби. Поразот ја отвори границата на Византија, и турските номади се излеаја во Мала Азија — најбогатиот извор на регрути и житницата на империјата.\n\nОчаен, византискиот император Алексиј I побара од латинскиот Запад платеници за да ги врати изгубените земји. Папата Урбан II одговори во 1095 година со нешто многу поголемо отколку што императорот очекуваше: повик за вооружено аџилак за ослободување на Ерусалим. Така една изгубена битка на далечна висорамнина стави во движење два века света војна меѓу христијанството и исламот." },
    de: { heading: "Manzikert: die Schlacht, die die Kreuzzüge entfachte",
      body: "Die Kreuzzüge entstanden nicht aus dem Nichts. 1071 zerschlug bei Manzikert im östlichen Anatolien der seldschukische Sultan Alp Arslan das Heer des byzantinischen Kaisers Romanos IV. und nahm ihn gefangen. Die Niederlage riss die Grenze von Byzanz auf, und türkische Nomaden strömten nach Kleinasien — das reichste Rekrutierungsgebiet und die Kornkammer des Reiches.\n\nVerzweifelt bat der byzantinische Kaiser Alexios I. den lateinischen Westen um Söldner, um seine verlorenen Länder zurückzugewinnen. Papst Urban II. antwortete 1095 mit weit mehr, als der Kaiser erwartet hatte: einem Aufruf zu einer bewaffneten Pilgerfahrt zur Befreiung Jerusalems. So setzte eine einzige verlorene Schlacht auf einem fernen Hochland zwei Jahrhunderte heiligen Krieges zwischen Christenheit und Islam in Gang." },
    fr: { heading: "Manzikert : la bataille qui alluma les croisades",
      body: "Les croisades ne surgirent pas de rien. En 1071, à Manzikert, dans l'est de l'Anatolie, le sultan turc seldjoukide Alp Arslan écrasa l'armée de l'empereur byzantin Romain IV et le fit prisonnier. La défaite ouvrit en grand la frontière de Byzance, et les nomades turcs déferlèrent sur l'Asie Mineure — le plus riche vivier de recrues et le grenier de l'empire.\n\nDésespéré, l'empereur byzantin Alexis Ier demanda à l'Occident latin des mercenaires pour reconquérir ses terres perdues. Le pape Urbain II répondit en 1095 par bien plus que ce que l'empereur attendait : un appel à un pèlerinage armé pour libérer Jérusalem. Ainsi une seule bataille perdue sur un plateau lointain mit en branle deux siècles de guerre sainte entre la chrétienté et l'islam." },
  },
  'medieval-03': {
    en: { heading: "Quarantine and the Birth of Public Health",
      body: "The Black Death killed perhaps a third of Europe, but it also forced the first organized public-health measures in the West. With no understanding of germs, city governments blamed 'bad air' — yet their responses were often shrewd. In 1377 the port of Ragusa (modern Dubrovnik) ordered arriving ships and travelers to wait in isolation before entering; Venice soon extended the wait to forty days, the quaranta giorni that gave us the word 'quarantine.'\n\nCities appointed health boards, isolated the sick in pest houses, and burned the belongings of the dead. These emergency measures hardened over time into permanent institutions of urban government. Long before anyone could see a bacterium, the plague taught Europe that disease could be tracked, contained, and fought by the state — a lesson at the root of modern public health." },
    es: { heading: "La cuarentena y el nacimiento de la salud pública",
      body: "La Peste Negra mató quizá a un tercio de Europa, pero también impuso las primeras medidas organizadas de salud pública en Occidente. Sin comprender los gérmenes, los gobiernos de las ciudades culpaban al 'aire malo', pero sus respuestas solían ser astutas. En 1377 el puerto de Ragusa (la actual Dubrovnik) ordenó que los barcos y viajeros que llegaban esperaran aislados antes de entrar; Venecia pronto amplió la espera a cuarenta días, los quaranta giorni que nos dieron la palabra 'cuarentena'.\n\nLas ciudades nombraron juntas de sanidad, aislaron a los enfermos en lazaretos y quemaron las pertenencias de los muertos. Estas medidas de emergencia se endurecieron con el tiempo hasta convertirse en instituciones permanentes del gobierno urbano. Mucho antes de que nadie pudiera ver una bacteria, la peste enseñó a Europa que la enfermedad podía rastrearse, contenerse y combatirse desde el Estado, una lección en la raíz de la salud pública moderna." },
    ru: { heading: "Карантин и рождение общественного здравоохранения",
      body: "Чёрная смерть унесла, возможно, треть Европы, но она же вынудила ввести первые организованные меры общественного здравоохранения на Западе. Не зная о микробах, городские власти винили «дурной воздух», однако их действия нередко были разумны. В 1377 году порт Рагуза (современный Дубровник) приказал прибывающим кораблям и путникам ждать в изоляции перед въездом; Венеция вскоре продлила ожидание до сорока дней — quaranta giorni, откуда и слово «карантин».\n\nГорода назначали санитарные советы, изолировали больных в чумных домах и сжигали имущество умерших. Эти чрезвычайные меры со временем затвердели в постоянные учреждения городского управления. Задолго до того как кто-либо смог увидеть бактерию, чума научила Европу, что болезнь можно отслеживать, сдерживать и побеждать силами государства, — урок, лежащий в основе современного здравоохранения." },
    mk: { heading: "Карантинот и раѓањето на јавното здравство",
      body: "Црната смрт усмрти можеби третина од Европа, но исто така ги наметна првите организирани мерки за јавно здравје на Западот. Без да знаат за микробите, градските власти го обвинуваа „лошиот воздух“, но нивните одговори често беа умни. Во 1377 година пристаништето Рагуза (денешен Дубровник) им нареди на пристигнатите бродови и патници да чекаат во изолација пред да влезат; Венеција набрзо го продолжи чекањето на четириесет дена — quaranta giorni, од каде што доаѓа зборот „карантин“.\n\nГрадовите именуваа здравствени одбори, ги изолираа болните во кужни куќи и ги палеа работите на мртвите. Овие итни мерки со текот на времето се стврднаа во трајни институции на градската власт. Долго пред некој да може да види бактерија, чумата ја научи Европа дека болеста може да се следи, да се задржи и да се победи од државата — лекција во коренот на современото јавно здравство." },
    de: { heading: "Quarantäne und die Geburt des öffentlichen Gesundheitswesens",
      body: "Der Schwarze Tod tötete vielleicht ein Drittel Europas, doch er erzwang auch die ersten organisierten Maßnahmen des öffentlichen Gesundheitswesens im Westen. Ohne Kenntnis von Krankheitserregern gaben die Stadtregierungen der 'schlechten Luft' die Schuld — ihre Reaktionen aber waren oft klug. 1377 ordnete der Hafen von Ragusa (dem heutigen Dubrovnik) an, dass ankommende Schiffe und Reisende vor dem Einlass in Isolation warten mussten; Venedig verlängerte die Wartezeit bald auf vierzig Tage, die quaranta giorni, die uns das Wort 'Quarantäne' schenkten.\n\nStädte setzten Gesundheitsräte ein, isolierten die Kranken in Pesthäusern und verbrannten die Habe der Toten. Diese Notmaßnahmen verfestigten sich mit der Zeit zu dauerhaften Einrichtungen der Stadtverwaltung. Lange bevor jemand ein Bakterium sehen konnte, lehrte die Pest Europa, dass Krankheit vom Staat verfolgt, eingedämmt und bekämpft werden kann — eine Lektion an der Wurzel des modernen Gesundheitswesens." },
    fr: { heading: "La quarantaine et la naissance de la santé publique",
      body: "La Peste noire tua peut-être un tiers de l'Europe, mais elle imposa aussi les premières mesures organisées de santé publique en Occident. Ignorant tout des germes, les gouvernements des villes accusaient le 'mauvais air' — pourtant leurs réponses étaient souvent judicieuses. En 1377, le port de Raguse (l'actuelle Dubrovnik) ordonna aux navires et voyageurs arrivants d'attendre en isolement avant d'entrer ; Venise porta bientôt l'attente à quarante jours, les quaranta giorni qui nous ont donné le mot 'quarantaine'.\n\nLes villes nommèrent des conseils de santé, isolèrent les malades dans des lazarets et brûlèrent les biens des morts. Ces mesures d'urgence se durcirent avec le temps en institutions permanentes du gouvernement urbain. Bien avant que quiconque pût voir une bactérie, la peste apprit à l'Europe que la maladie pouvait être suivie, contenue et combattue par l'État — une leçon à la racine de la santé publique moderne." },
  },
  'medieval-04': {
    en: { heading: "The Hanseatic League",
      body: "While Mediterranean trade enriched Italy, a very different commercial power rose in the cold north: the Hanseatic League. Beginning in the 13th century, German merchant towns led by Lübeck banded together to dominate trade across the Baltic and North Seas. At its height the League linked some 200 towns and ran trading posts, or kontors, from Novgorod in Russia to Bergen, Bruges, and London.\n\nThe Hansa dealt in the bulk goods of the north — grain, timber, furs, wax, and above all dried and salted fish that fed Catholic Europe on its many fast days. To protect its trade the League negotiated privileges, built warehouses, and even waged war on kings who threatened it. This merchant network showed that commerce alone, without a single ruler or army, could organize an economic empire spanning half a continent." },
    es: { heading: "La Liga Hanseática",
      body: "Mientras el comercio mediterráneo enriquecía a Italia, una potencia comercial muy distinta se alzaba en el frío norte: la Liga Hanseática. A partir del siglo XIII, ciudades mercantiles alemanas encabezadas por Lübeck se unieron para dominar el comercio del Báltico y el mar del Norte. En su apogeo, la Liga enlazaba unas 200 ciudades y gestionaba factorías, o kontors, desde Novgorod en Rusia hasta Bergen, Brujas y Londres.\n\nLa Hansa comerciaba con los productos a granel del norte —grano, madera, pieles, cera y, sobre todo, pescado seco y salado que alimentaba a la Europa católica en sus muchos días de ayuno—. Para proteger su comercio, la Liga negociaba privilegios, construía almacenes e incluso hacía la guerra a los reyes que la amenazaban. Esta red mercantil demostró que el comercio por sí solo, sin un único soberano ni ejército, podía organizar un imperio económico que abarcaba medio continente." },
    ru: { heading: "Ганзейский союз",
      body: "Пока средиземноморская торговля обогащала Италию, на холодном севере поднималась совсем иная торговая сила — Ганзейский союз. Начиная с XIII века немецкие торговые города во главе с Любеком объединились, чтобы господствовать в торговле на Балтийском и Северном морях. На вершине могущества Союз связывал около 200 городов и держал торговые конторы от Новгорода в России до Бергена, Брюгге и Лондона.\n\nГанза торговала объёмными товарами севера — зерном, лесом, мехами, воском и прежде всего сушёной и солёной рыбой, кормившей католическую Европу в многочисленные постные дни. Ради защиты торговли Союз добивался привилегий, строил склады и даже воевал с королями, угрожавшими ему. Эта купеческая сеть показала, что одна лишь торговля, без единого государя и армии, способна выстроить экономическую империю в полконтинента." },
    mk: { heading: "Ханзеатската лига",
      body: "Додека медитеранската трговија ја збогатуваше Италија, сосема поинаква трговска сила се издигна на студениот север: Ханзеатската лига. Почнувајќи од 13 век, германските трговски градови предводени од Либек се здружија за да доминираат во трговијата на Балтичкото и Северното Море. На својот врв, Лигата поврзуваше околу 200 градови и водеше трговски испостави, или контори, од Новгород во Русија до Берген, Бриж и Лондон.\n\nХанзата тргуваше со масовните стоки на северот — жито, дрво, крзна, восок и пред сè сушена и солена риба што ја хранеше католичка Европа во нејзините многубројни постни денови. За да ја заштити трговијата, Лигата преговараше за привилегии, градеше складишта, па дури и војуваше против кралеви што ѝ се закануваа. Оваа трговска мрежа покажа дека самата трговија, без единствен владетел или војска, може да организира економска империја што опфаќа половина континент." },
    de: { heading: "Die Hanse",
      body: "Während der Mittelmeerhandel Italien bereicherte, erhob sich im kalten Norden eine ganz andere Handelsmacht: die Hanse. Ab dem 13. Jahrhundert schlossen sich deutsche Kaufmannsstädte unter Führung Lübecks zusammen, um den Handel über Ostsee und Nordsee zu beherrschen. Auf ihrem Höhepunkt verband die Hanse etwa 200 Städte und unterhielt Handelsniederlassungen, die Kontore, von Nowgorod in Russland bis Bergen, Brügge und London.\n\nDie Hanse handelte mit den Massengütern des Nordens — Getreide, Holz, Pelzen, Wachs und vor allem getrocknetem und gesalzenem Fisch, der das katholische Europa an seinen vielen Fastentagen ernährte. Zum Schutz ihres Handels handelte die Hanse Privilegien aus, baute Lagerhäuser und führte sogar Krieg gegen Könige, die sie bedrohten. Dieses Kaufmannsnetz zeigte, dass Handel allein, ohne einen einzigen Herrscher oder ein Heer, ein Wirtschaftsimperium über einen halben Kontinent hinweg organisieren konnte." },
    fr: { heading: "La Ligue hanséatique",
      body: "Tandis que le commerce méditerranéen enrichissait l'Italie, une puissance marchande bien différente s'élevait dans le froid Nord : la Ligue hanséatique. À partir du XIIIe siècle, des villes marchandes allemandes menées par Lübeck s'unirent pour dominer le commerce de la Baltique et de la mer du Nord. À son apogée, la Ligue reliait quelque 200 villes et tenait des comptoirs, les kontors, de Novgorod en Russie jusqu'à Bergen, Bruges et Londres.\n\nLa Hanse négociait les marchandises de masse du Nord — grain, bois, fourrures, cire et surtout poisson séché et salé qui nourrissait l'Europe catholique lors de ses nombreux jours de jeûne. Pour protéger son commerce, la Ligue négociait des privilèges, bâtissait des entrepôts et faisait même la guerre aux rois qui la menaçaient. Ce réseau marchand montra que le commerce seul, sans souverain unique ni armée, pouvait organiser un empire économique s'étendant sur un demi-continent." },
  },
  'medieval-05': {
    en: { heading: "The Yam: The Mongols' Pony Express",
      body: "The Mongols ruled the largest contiguous land empire in history, and they held it together with a brilliant relay system called the yam. Every 30 to 60 kilometers along the empire's roads stood a relay station stocked with fresh horses, food, and shelter. A rider bearing an official passport — an inscribed tablet called a paiza — could gallop from one station to the next, hand his message to a fresh rider and mount, and so speed news across thousands of kilometers in days.\n\nThe yam carried imperial orders, tax records, and intelligence, binding the vast realm from China to Persia. It also made long-distance trade and travel safer than ever before, protected by Mongol law. It was along these guarded roads that the merchant Marco Polo journeyed to the court of Kublai Khan, and that goods, technologies, and even the plague would later travel between East and West." },
    es: { heading: "El yam: el correo veloz de los mongoles",
      body: "Los mongoles gobernaron el mayor imperio terrestre continuo de la historia, y lo mantuvieron unido con un brillante sistema de postas llamado yam. Cada 30 a 60 kilómetros, a lo largo de los caminos del imperio, había una estación de relevo provista de caballos frescos, comida y refugio. Un jinete que portara un salvoconducto oficial —una tablilla grabada llamada paiza— podía galopar de una estación a la siguiente, entregar su mensaje a un jinete y una montura de refresco, y así llevar noticias a través de miles de kilómetros en pocos días.\n\nEl yam transportaba órdenes imperiales, registros fiscales e información, ligando el vasto reino desde China hasta Persia. También hizo el comercio y los viajes de larga distancia más seguros que nunca, protegidos por la ley mongola. Fue por estos caminos vigilados por donde el mercader Marco Polo viajó a la corte de Kublai Kan, y por donde más tarde viajarían mercancías, tecnologías e incluso la peste entre Oriente y Occidente." },
    ru: { heading: "Ям: монгольская почта",
      body: "Монголы правили крупнейшей в истории непрерывной сухопутной империей и удерживали её благодаря блестящей системе почтовых станций — яму. Через каждые 30–60 километров вдоль имперских дорог стояла станция со свежими лошадьми, едой и кровом. Гонец с официальной подорожной — дощечкой с надписью, называемой пайцза, — мог мчаться от станции к станции, передавать сообщение свежему всаднику и коню и так проносить вести через тысячи километров за считанные дни.\n\nЯм разносил имперские приказы, податные списки и разведданные, связывая огромную державу от Китая до Персии. Он же сделал дальнюю торговлю и путешествия безопаснее, чем когда-либо, под защитой монгольского закона. Именно по этим охраняемым дорогам купец Марко Поло добрался до двора Хубилай-хана, и по ним же позже потекли между Востоком и Западом товары, технологии и даже чума." },
    mk: { heading: "Јам: монголската брза пошта",
      body: "Монголите владееја со најголемата непрекината копнена империја во историјата и ја држеа заедно со брилијантен систем на станици наречен јам. На секои 30 до 60 километри долж империските патишта стоеше станица за смена, снабдена со свежи коњи, храна и засолниште. Јавач со официјален пропусник — врежана плочка наречена пајца — можеше да галопира од една станица до следната, да ја предаде својата порака на свеж јавач и коњ, и така да пренесе вести преку илјадници километри за неколку дена.\n\nЈамот носеше империски наредби, даночни записи и разузнавачки податоци, поврзувајќи го огромното царство од Кина до Персија. Исто така ја направи трговијата и патувањето на долги растојанија побезбедни од кога било, заштитени со монголскиот закон. Токму по овие чувани патишта трговецот Марко Поло отпатува до дворот на Кублај Кан, и по нив подоцна ќе патуваа стоки, технологии, па дури и чумата меѓу Истокот и Западот." },
    de: { heading: "Das Yam: der Ponyexpress der Mongolen",
      body: "Die Mongolen beherrschten das größte zusammenhängende Landreich der Geschichte und hielten es mit einem genialen Relaissystem namens Yam zusammen. Alle 30 bis 60 Kilometer stand entlang der Reichsstraßen eine Relaisstation mit frischen Pferden, Verpflegung und Unterkunft. Ein Reiter mit amtlichem Passierschein — einer beschrifteten Tafel namens Paiza — konnte von einer Station zur nächsten galoppieren, seine Botschaft einem frischen Reiter und Pferd übergeben und so Nachrichten in wenigen Tagen über tausende Kilometer tragen.\n\nDas Yam beförderte kaiserliche Befehle, Steuerlisten und Nachrichten und band das riesige Reich von China bis Persien zusammen. Es machte auch Fernhandel und Reisen sicherer als je zuvor, geschützt durch mongolisches Recht. Auf diesen bewachten Straßen reiste der Kaufmann Marco Polo an den Hof Kublai Khans, und auf ihnen sollten später Waren, Techniken und selbst die Pest zwischen Ost und West wandern." },
    fr: { heading: "Le yam : le pony express des Mongols",
      body: "Les Mongols régnaient sur le plus vaste empire terrestre d'un seul tenant de l'histoire, et ils le tenaient grâce à un brillant système de relais appelé le yam. Tous les 30 à 60 kilomètres, le long des routes de l'empire, se dressait une station de relais pourvue de chevaux frais, de vivres et d'un abri. Un cavalier muni d'un sauf-conduit officiel — une tablette gravée appelée paiza — pouvait galoper d'une station à l'autre, remettre son message à un cavalier et une monture frais, et ainsi porter des nouvelles à travers des milliers de kilomètres en quelques jours.\n\nLe yam acheminait ordres impériaux, registres fiscaux et renseignements, liant le vaste royaume de la Chine à la Perse. Il rendit aussi le commerce et les voyages au long cours plus sûrs que jamais, protégés par la loi mongole. C'est par ces routes gardées que le marchand Marco Polo gagna la cour de Kubilai Khan, et par elles que voyageraient plus tard marchandises, techniques et jusqu'à la peste entre l'Orient et l'Occident." },
  },
  'medieval-06': {
    en: { heading: "The Divine Wind: Japan Repels the Mongols",
      body: "Twice in the 13th century, the Mongol empire of Kublai Khan launched vast seaborne invasions of Japan, and twice Japan was saved as much by the weather as by the sword. In 1274 a Mongol fleet landed at Hakata Bay but withdrew after fierce samurai resistance and a sudden storm. Warned, the Japanese built a defensive stone wall along the coast.\n\nIn 1281 the Mongols returned with one of the largest naval forces in history — perhaps 4,000 ships and over 100,000 men. The samurai held the wall for weeks until a massive typhoon smashed the anchored Mongol fleet against the shore, drowning tens of thousands. The Japanese called these saving storms kamikaze, the 'divine wind,' and took them as proof that the gods themselves protected Japan — a belief that would echo dangerously into the twentieth century." },
    es: { heading: "El viento divino: Japón rechaza a los mongoles",
      body: "Dos veces en el siglo XIII, el imperio mongol de Kublai Kan lanzó enormes invasiones por mar contra Japón, y dos veces Japón se salvó tanto por el clima como por la espada. En 1274 una flota mongola desembarcó en la bahía de Hakata, pero se retiró tras la feroz resistencia de los samuráis y una tormenta repentina. Advertidos, los japoneses levantaron un muro defensivo de piedra a lo largo de la costa.\n\nEn 1281 los mongoles regresaron con una de las mayores fuerzas navales de la historia: quizá 4.000 barcos y más de 100.000 hombres. Los samuráis defendieron el muro durante semanas hasta que un tifón descomunal estrelló la flota mongola anclada contra la orilla, ahogando a decenas de miles. Los japoneses llamaron a estas tormentas salvadoras kamikaze, el 'viento divino', y las tomaron como prueba de que los propios dioses protegían Japón, una creencia que resonaría peligrosamente hasta el siglo XX." },
    ru: { heading: "Божественный ветер: Япония отражает монголов",
      body: "Дважды в XIII веке монгольская империя Хубилай-хана предпринимала огромные морские вторжения в Японию, и дважды Японию спасала погода не меньше, чем меч. В 1274 году монгольский флот высадился в заливе Хаката, но отступил после яростного сопротивления самураев и внезапной бури. Предупреждённые, японцы возвели вдоль побережья оборонительную каменную стену.\n\nВ 1281 году монголы вернулись с одной из крупнейших морских армий в истории — быть может, 4000 кораблей и более 100 000 человек. Самураи удерживали стену неделями, пока чудовищный тайфун не разбил стоявший на якоре монгольский флот о берег, утопив десятки тысяч. Эти спасительные бури японцы назвали камикадзе — «божественный ветер» — и увидели в них доказательство, что саму Японию хранят боги; вера, которая опасно отзовётся в двадцатом веке." },
    mk: { heading: "Божествениот ветер: Јапонија ги одбива Монголите",
      body: "Двапати во 13 век монголската империја на Кублај Кан започна огромни поморски инвазии врз Јапонија, и двапати Јапонија беше спасена колку од времето, толку и од мечот. Во 1274 година монголска флота се истовари во заливот Хаката, но се повлече по жестокиот отпор на самураите и една ненадејна бура. Предупредени, Јапонците подигнаа одбранбен камен ѕид долж крајбрежјето.\n\nВо 1281 година Монголите се вратија со една од најголемите поморски сили во историјата — можеби 4.000 бродови и над 100.000 луѓе. Самураите го држеа ѕидот со недели сè додека огромен тајфун не ја разби закотвената монголска флота од брегот, давејќи десетици илјади. Јапонците овие спасоносни бури ги нарекоа камиказе, „божествениот ветер“, и ги сфатија како доказ дека самите богови ја штитат Јапонија — верување што опасно ќе одекне и во дваесеттиот век." },
    de: { heading: "Der göttliche Wind: Japan wehrt die Mongolen ab",
      body: "Zweimal im 13. Jahrhundert entsandte das Mongolenreich Kublai Khans gewaltige Seeinvasionen gegen Japan, und zweimal wurde Japan ebenso vom Wetter wie vom Schwert gerettet. 1274 landete eine mongolische Flotte in der Bucht von Hakata, zog sich aber nach erbittertem Widerstand der Samurai und einem plötzlichen Sturm zurück. Gewarnt, errichteten die Japaner eine steinerne Schutzmauer entlang der Küste.\n\n1281 kehrten die Mongolen mit einer der größten Seestreitmächte der Geschichte zurück — vielleicht 4.000 Schiffe und über 100.000 Mann. Die Samurai hielten die Mauer wochenlang, bis ein gewaltiger Taifun die vor Anker liegende mongolische Flotte an die Küste schmetterte und Zehntausende ertränkte. Die Japaner nannten diese rettenden Stürme Kamikaze, den 'göttlichen Wind', und nahmen sie als Beweis, dass die Götter selbst Japan beschützten — ein Glaube, der noch im zwanzigsten Jahrhundert gefährlich nachhallen sollte." },
    fr: { heading: "Le vent divin : le Japon repousse les Mongols",
      body: "Deux fois au XIIIe siècle, l'empire mongol de Kubilai Khan lança d'immenses invasions maritimes contre le Japon, et deux fois le Japon fut sauvé autant par le temps que par l'épée. En 1274, une flotte mongole débarqua dans la baie de Hakata, mais se retira après la farouche résistance des samouraïs et une soudaine tempête. Avertis, les Japonais élevèrent un mur de pierre défensif le long de la côte.\n\nEn 1281, les Mongols revinrent avec l'une des plus grandes forces navales de l'histoire — peut-être 4 000 navires et plus de 100 000 hommes. Les samouraïs tinrent le mur des semaines durant, jusqu'à ce qu'un typhon colossal fracasse la flotte mongole à l'ancre contre le rivage, noyant des dizaines de milliers d'hommes. Les Japonais nommèrent ces tempêtes salvatrices kamikaze, le 'vent divin', et y virent la preuve que les dieux eux-mêmes protégeaient le Japon — une croyance qui résonnerait dangereusement jusqu'au XXe siècle." },
  },
  'medieval-07': {
    en: { heading: "Gods and Sagas: The Norse Imagination",
      body: "The Vikings carried with them a rich pagan religion and a towering body of story. They worshipped a family of gods led by one-eyed Odin, god of war, wisdom, and poetry, and by red-bearded Thor, whose hammer Mjölnir guarded the world against giants. Their cosmos was bound together by the world-tree Yggdrasil and shadowed by the certainty of Ragnarök, the doom in which gods and monsters would destroy one another and the world be reborn.\n\nMuch of what we know survives thanks to Iceland, where settlers preserved and later wrote down the myths and the sagas — vivid prose tales of feuds, voyages, and heroes that stand among the great literature of the Middle Ages. Even as the Norse gradually converted to Christianity after 1000 CE, these stories endured, shaping European imagination down to the names of our days of the week." },
    es: { heading: "Dioses y sagas: la imaginación nórdica",
      body: "Los vikingos llevaban consigo una rica religión pagana y un imponente acervo de relatos. Adoraban a una familia de dioses encabezada por Odín, el tuerto, dios de la guerra, la sabiduría y la poesía, y por Thor, el de la barba roja, cuyo martillo Mjölnir protegía el mundo de los gigantes. Su cosmos estaba unido por el árbol del mundo, Yggdrasil, y ensombrecido por la certeza del Ragnarök, la perdición en la que dioses y monstruos se destruirían mutuamente y el mundo renacería.\n\nGran parte de lo que sabemos sobrevive gracias a Islandia, donde los colonos conservaron y más tarde pusieron por escrito los mitos y las sagas: vívidos relatos en prosa de disputas, viajes y héroes que figuran entre la gran literatura de la Edad Media. Aun cuando los nórdicos se convirtieron poco a poco al cristianismo después del año 1000, estas historias perduraron, moldeando la imaginación europea hasta en los nombres de nuestros días de la semana." },
    ru: { heading: "Боги и саги: воображение северян",
      body: "Викинги несли с собой богатую языческую религию и грандиозный свод преданий. Они почитали семью богов во главе с одноглазым Одином, богом войны, мудрости и поэзии, и рыжебородым Тором, чей молот Мьёльнир хранил мир от великанов. Их мироздание держалось на мировом древе Иггдрасиль и было омрачено неизбежностью Рагнарёка — гибели, в которой боги и чудовища истребят друг друга, а мир возродится.\n\nМногое из того, что мы знаем, уцелело благодаря Исландии, где поселенцы сберегли, а позже записали мифы и саги — яркие прозаические повести о распрях, плаваниях и героях, стоящие среди великой литературы Средневековья. Даже когда северяне после 1000 года постепенно приняли христианство, эти истории уцелели, формируя европейское воображение вплоть до названий наших дней недели." },
    mk: { heading: "Богови и саги: нордиската имагинација",
      body: "Викинзите носеа со себе богата паганска религија и величествен корпус приказни. Обожаваа семејство богови предводено од еднооокиот Один, богот на војната, мудроста и поезијата, и од црвенобрадиот Тор, чиј чекан Мјолнир го чуваше светот од џиновите. Нивниот космос беше сврзан со светското дрво Игдрасил и засенет од извесноста на Рагнарок — пропаста во која боговите и чудовиштата ќе се уништат меѓусебно, а светот ќе се прероди.\n\nМногу од она што го знаеме преживеало благодарение на Исланд, каде што доселениците ги зачувале, а подоцна ги запишале митовите и сагите — живописни прозни приказни за крвни одмазди, патувања и херои што спаѓаат меѓу големата литература на Средниот век. Дури и додека нордијците постепено се преобратуваа во христијанство по 1000 година, овие приказни опстанаа, обликувајќи ја европската имагинација сè до имињата на деновите во неделата." },
    de: { heading: "Götter und Sagas: die nordische Vorstellungswelt",
      body: "Die Wikinger trugen eine reiche heidnische Religion und einen gewaltigen Schatz an Erzählungen mit sich. Sie verehrten eine Götterfamilie unter dem einäugigen Odin, dem Gott des Krieges, der Weisheit und der Dichtkunst, und dem rotbärtigen Thor, dessen Hammer Mjölnir die Welt vor den Riesen schützte. Ihr Kosmos wurde vom Weltenbaum Yggdrasil zusammengehalten und von der Gewissheit des Ragnarök überschattet — dem Untergang, in dem Götter und Ungeheuer einander vernichten und die Welt neu geboren wird.\n\nVieles von dem, was wir wissen, überlebte dank Island, wo Siedler die Mythen und Sagas bewahrten und später niederschrieben — lebendige Prosaerzählungen von Fehden, Fahrten und Helden, die zur großen Literatur des Mittelalters zählen. Auch als die Nordleute sich nach 1000 allmählich zum Christentum bekehrten, überdauerten diese Geschichten und prägten die europäische Vorstellungswelt bis hinein in die Namen unserer Wochentage." },
    fr: { heading: "Dieux et sagas : l'imaginaire nordique",
      body: "Les Vikings portaient avec eux une riche religion païenne et un immense corpus de récits. Ils vénéraient une famille de dieux menée par Odin le borgne, dieu de la guerre, de la sagesse et de la poésie, et par Thor à la barbe rousse, dont le marteau Mjöllnir protégeait le monde des géants. Leur cosmos était tenu par l'arbre-monde Yggdrasil et assombri par la certitude du Ragnarök, la fin où dieux et monstres se détruiraient et où le monde renaîtrait.\n\nUne grande part de ce que nous savons a survécu grâce à l'Islande, où les colons préservèrent puis mirent par écrit les mythes et les sagas — de vivants récits en prose de querelles, de voyages et de héros qui comptent parmi la grande littérature du Moyen Âge. Même lorsque les Scandinaves se convertirent peu à peu au christianisme après l'an 1000, ces récits perdurèrent, façonnant l'imaginaire européen jusque dans les noms de nos jours de la semaine." },
  },
  'medieval-08': {
    en: { heading: "Convivencia: Three Faiths in Iberia",
      body: "For much of the Middle Ages, Islamic Spain was the most sophisticated society in Western Europe, and its cities became a meeting place for three faiths. Under Muslim rule, Córdoba grew into one of the world's great cities, with paved and lamp-lit streets, running water, libraries, and hundreds of thousands of books at a time when most European towns were small and dark. Muslims, Christians, and Jews lived side by side in an often-fragile coexistence later called la convivencia.\n\nThis mingling made Iberia a bridge for knowledge. In cities like Toledo, teams of Muslim, Jewish, and Christian scholars translated Arabic and Greek works — Aristotle, medicine, astronomy, and mathematics — into Latin. Thinkers such as the Muslim philosopher Averroes and the Jewish sage Maimonides shaped European thought for centuries. Through Spain, the learning of the ancient and Islamic worlds flowed north to spark the revival of European universities." },
    es: { heading: "La convivencia: tres religiones en Iberia",
      body: "Durante buena parte de la Edad Media, la España islámica fue la sociedad más avanzada de Europa occidental, y sus ciudades se volvieron lugar de encuentro de tres religiones. Bajo el dominio musulmán, Córdoba llegó a ser una de las grandes ciudades del mundo, con calles pavimentadas e iluminadas, agua corriente, bibliotecas y cientos de miles de libros en una época en que la mayoría de las villas europeas eran pequeñas y oscuras. Musulmanes, cristianos y judíos vivían codo con codo en una coexistencia a menudo frágil, llamada más tarde la convivencia.\n\nEsa mezcla hizo de Iberia un puente para el saber. En ciudades como Toledo, equipos de sabios musulmanes, judíos y cristianos tradujeron al latín obras árabes y griegas —Aristóteles, medicina, astronomía y matemáticas—. Pensadores como el filósofo musulmán Averroes y el sabio judío Maimónides moldearon el pensamiento europeo durante siglos. A través de España, el saber de los mundos antiguo e islámico fluyó hacia el norte y encendió el renacer de las universidades europeas." },
    ru: { heading: "Конвивенсия: три веры на Пиренеях",
      body: "Значительную часть Средневековья исламская Испания была самым развитым обществом Западной Европы, а её города стали местом встречи трёх вер. Под властью мусульман Кордова выросла в один из величайших городов мира — с мощёными и освещёнными улицами, водопроводом, библиотеками и сотнями тысяч книг в то время, когда большинство европейских городков были малы и темны. Мусульмане, христиане и иудеи жили бок о бок в зачастую хрупком сосуществовании, позже названном la convivencia.\n\nЭто смешение сделало Пиренеи мостом для знаний. В таких городах, как Толедо, коллективы мусульманских, иудейских и христианских учёных переводили на латынь арабские и греческие труды — Аристотеля, медицину, астрономию и математику. Мыслители вроде мусульманского философа Аверроэса и иудейского мудреца Маймонида веками формировали европейскую мысль. Через Испанию учёность античного и исламского миров текла на север, разжигая возрождение европейских университетов." },
    mk: { heading: "Конвивенсија: три вери на Пиринејскиот Полуостров",
      body: "Голем дел од Средниот век, исламска Шпанија беше најнапредното општество во Западна Европа, а нејзините градови станаа место на средба на три вери. Под муслиманска власт, Кордоба прерасна во еден од најголемите градови во светот — со поплочени и осветлени улици, водовод, библиотеки и стотици илјади книги во време кога повеќето европски градчиња беа мали и темни. Муслиманите, христијаните и Евреите живееја рамо до рамо во често кревко сожителство, подоцна наречено la convivencia.\n\nТоа мешање го направи Полуостровот мост за знаењето. Во градови како Толедо, екипи муслимански, еврејски и христијански учени преведуваа на латински арапски и грчки дела — Аристотел, медицина, астрономија и математика. Мислители како муслиманскиот филозоф Авероес (Ибн Рушд) и еврејскиот мудрец Мајмонид го обликуваа европското мислење со векови. Преку Шпанија, знаењето на античкиот и исламскиот свет течеше на север и ја запали преродбата на европските универзитети." },
    de: { heading: "Convivencia: drei Glaubensrichtungen in Iberien",
      body: "Über weite Teile des Mittelalters war das islamische Spanien die höchstentwickelte Gesellschaft Westeuropas, und seine Städte wurden zum Treffpunkt dreier Glaubensrichtungen. Unter muslimischer Herrschaft wuchs Córdoba zu einer der großen Städte der Welt heran — mit gepflasterten und beleuchteten Straßen, fließendem Wasser, Bibliotheken und Hunderttausenden von Büchern, zu einer Zeit, als die meisten europäischen Städte klein und dunkel waren. Muslime, Christen und Juden lebten Seite an Seite in einem oft brüchigen Zusammenleben, das später la convivencia genannt wurde.\n\nDiese Vermischung machte Iberien zu einer Brücke des Wissens. In Städten wie Toledo übersetzten Teams muslimischer, jüdischer und christlicher Gelehrter arabische und griechische Werke — Aristoteles, Medizin, Astronomie und Mathematik — ins Lateinische. Denker wie der muslimische Philosoph Averroes und der jüdische Weise Maimonides prägten das europäische Denken über Jahrhunderte. Über Spanien floss das Wissen der antiken und der islamischen Welt nach Norden und entfachte die Wiederbelebung der europäischen Universitäten." },
    fr: { heading: "La convivencia : trois confessions en Ibérie",
      body: "Pendant une grande partie du Moyen Âge, l'Espagne islamique fut la société la plus raffinée d'Europe occidentale, et ses villes devinrent un lieu de rencontre de trois confessions. Sous domination musulmane, Cordoue devint l'une des grandes villes du monde — rues pavées et éclairées, eau courante, bibliothèques et des centaines de milliers de livres, à une époque où la plupart des villes européennes étaient petites et obscures. Musulmans, chrétiens et juifs vivaient côte à côte dans une coexistence souvent fragile, plus tard appelée la convivencia.\n\nCe mélange fit de l'Ibérie un pont pour le savoir. Dans des villes comme Tolède, des équipes de savants musulmans, juifs et chrétiens traduisirent en latin des œuvres arabes et grecques — Aristote, la médecine, l'astronomie et les mathématiques. Des penseurs comme le philosophe musulman Averroès et le sage juif Maïmonide façonnèrent la pensée européenne pendant des siècles. Par l'Espagne, le savoir des mondes antique et islamique s'écoula vers le nord et alluma le renouveau des universités européennes." },
  },
  'medieval-09': {
    en: { heading: "The Longbow and the Twilight of the Knight",
      body: "The Hundred Years' War between England and France became a graveyard for the age of mounted chivalry. At Crécy in 1346 and again at Agincourt in 1415, outnumbered English armies destroyed the flower of French knighthood — not with knights of their own, but with massed common archers wielding the longbow. A trained archer could loose ten or more arrows a minute, and clouds of them brought down horses and men before they could close.\n\nThe lesson was brutal and clear: a wall of disciplined commoners could shatter the mounted elite who had dominated European warfare for centuries. As the war dragged on, gunpowder artillery joined the longbow in making castles and armored knights obsolete. Out of this long, grinding conflict the modern nations of England and France were forged — and with them a new kind of warfare in which numbers, discipline, and technology mattered more than noble birth." },
    es: { heading: "El arco largo y el ocaso del caballero",
      body: "La Guerra de los Cien Años entre Inglaterra y Francia se convirtió en el cementerio de la era de la caballería montada. En Crécy en 1346 y de nuevo en Agincourt en 1415, ejércitos ingleses en inferioridad numérica destruyeron la flor de la caballería francesa, no con caballeros propios, sino con masas de arqueros plebeyos armados con el arco largo. Un arquero adiestrado podía disparar diez o más flechas por minuto, y nubes de ellas derribaban caballos y hombres antes de que pudieran acercarse.\n\nLa lección fue brutal y clara: un muro de plebeyos disciplinados podía destrozar a la élite montada que había dominado la guerra europea durante siglos. A medida que la guerra se prolongaba, la artillería de pólvora se sumó al arco largo para volver obsoletos los castillos y los caballeros con armadura. De este conflicto largo y desgastador nacieron las naciones modernas de Inglaterra y Francia, y con ellas una nueva forma de guerra en la que el número, la disciplina y la tecnología importaban más que la cuna noble." },
    ru: { heading: "Длинный лук и закат рыцарства",
      body: "Столетняя война между Англией и Францией стала могилой эпохи конного рыцарства. При Креси в 1346 году и вновь при Азенкуре в 1415-м уступавшие в числе английские армии истребляли цвет французского рыцарства — не своими рыцарями, а массами простых лучников с длинными луками. Обученный лучник мог выпускать десять и более стрел в минуту, и их тучи валили коней и людей прежде, чем те успевали сблизиться.\n\nУрок был жесток и ясен: стена дисциплинированных простолюдинов способна сокрушить конную знать, веками господствовавшую в европейской войне. По мере того как война тянулась, к длинному луку присоединилась пороховая артиллерия, делая замки и латников устаревшими. Из этого долгого, изматывающего противостояния выковались современные нации Англии и Франции — а с ними и новый вид войны, где число, дисциплина и техника значили больше знатного рождения." },
    mk: { heading: "Долгиот лак и самракот на витезот",
      body: "Стогодишната војна меѓу Англија и Франција стана гробница на ерата на коњаничкото витештво. Кај Креси во 1346 година и повторно кај Аженкур во 1415 година, бројчано послабите англиски војски го уништија цветот на француското витештво — не со свои витези, туку со маси обични стрелци вооружени со долгиот лак. Извежбан стрелец можеше да испука десет или повеќе стрели во минута, и облаци од нив соборуваа коњи и луѓе пред тие да успеат да се доближат.\n\nПоуката беше сурова и јасна: ѕид од дисциплинирани простолуѓе можеше да ја скрши коњаничката елита што со векови доминираше во европската војна. Како што војната се влечеше, барутната артилерија му се придружи на долгиот лак правејќи ги замоците и оклопените витези застарени. Од овој долг, исцрпувачки судир се исковаа модерните нации на Англија и Франција — а со нив и нов вид војна во која бројот, дисциплината и технологијата значеа повеќе од благородничкото потекло." },
    de: { heading: "Der Langbogen und die Dämmerung des Ritters",
      body: "Der Hundertjährige Krieg zwischen England und Frankreich wurde zum Grab des Zeitalters des berittenen Rittertums. Bei Crécy 1346 und erneut bei Azincourt 1415 vernichteten zahlenmäßig unterlegene englische Heere die Blüte des französischen Rittertums — nicht mit eigenen Rittern, sondern mit Massen gemeiner Bogenschützen, die den Langbogen führten. Ein geübter Schütze konnte zehn oder mehr Pfeile pro Minute abschießen, und ihre Wolken streckten Pferde und Männer nieder, ehe diese herankamen.\n\nDie Lehre war brutal und klar: eine Wand disziplinierter Gemeiner konnte die berittene Elite zerschlagen, die die europäische Kriegführung jahrhundertelang beherrscht hatte. Während sich der Krieg hinzog, gesellte sich die Pulverartillerie zum Langbogen und machte Burgen und geharnischte Ritter überflüssig. Aus diesem langen, zermürbenden Konflikt wurden die modernen Nationen England und Frankreich geschmiedet — und mit ihnen eine neue Art der Kriegführung, in der Zahl, Disziplin und Technik mehr zählten als edle Geburt." },
    fr: { heading: "L'arc long et le crépuscule du chevalier",
      body: "La guerre de Cent Ans entre l'Angleterre et la France devint le tombeau de l'âge de la chevalerie montée. À Crécy en 1346 et de nouveau à Azincourt en 1415, des armées anglaises en infériorité numérique détruisirent la fleur de la chevalerie française — non avec leurs propres chevaliers, mais avec des masses d'archers roturiers maniant l'arc long. Un archer entraîné pouvait décocher dix flèches ou plus par minute, et leurs nuées abattaient chevaux et hommes avant qu'ils ne pussent joindre.\n\nLa leçon fut brutale et claire : un mur de roturiers disciplinés pouvait briser l'élite montée qui dominait la guerre européenne depuis des siècles. À mesure que la guerre s'éternisait, l'artillerie à poudre rejoignit l'arc long pour rendre châteaux et chevaliers en armure obsolètes. De ce long conflit épuisant furent forgées les nations modernes d'Angleterre et de France — et avec elles une nouvelle forme de guerre où le nombre, la discipline et la technique comptaient plus que la naissance noble." },
  },

  // ══════════════════════════ EARLY MODERN ══════════════════════════
  'earlymod-01': {
    en: { heading: "The Columbian Exchange",
      body: "Columbus's voyages did more than link two hemispheres politically — they set off the largest biological exchange in human history. Ships carried maize, potatoes, tomatoes, cacao, and tobacco from the Americas to the Old World, while wheat, rice, sugar, horses, cattle, and pigs crossed the other way. The humble potato would eventually feed the population booms of Europe and China; chili peppers transformed the cuisines of India and Asia.\n\nBut the exchange had a catastrophic side. Old World diseases — smallpox, measles, influenza — met populations with no immunity and swept through the Americas, killing perhaps 90 percent of the indigenous peoples within a century. This demographic collapse, more than any army, shattered the great civilizations of the Aztecs and Incas and reshaped the human map of an entire hemisphere." },
    es: { heading: "El intercambio colombino",
      body: "Los viajes de Colón hicieron más que unir políticamente dos hemisferios: desataron el mayor intercambio biológico de la historia humana. Los barcos llevaron maíz, patatas, tomates, cacao y tabaco de América al Viejo Mundo, mientras que el trigo, el arroz, el azúcar, los caballos, el ganado y los cerdos cruzaron en sentido contrario. La humilde patata acabaría alimentando las explosiones demográficas de Europa y China; los chiles transformaron las cocinas de la India y Asia.\n\nPero el intercambio tuvo una cara catastrófica. Las enfermedades del Viejo Mundo —viruela, sarampión, gripe— encontraron poblaciones sin inmunidad y arrasaron las Américas, matando quizá al 90 por ciento de los pueblos indígenas en un siglo. Este colapso demográfico, más que cualquier ejército, destrozó las grandes civilizaciones de aztecas e incas y rehízo el mapa humano de todo un hemisferio." },
    ru: { heading: "Колумбов обмен",
      body: "Плавания Колумба не только связали два полушария политически — они запустили крупнейший биологический обмен в истории человечества. Корабли везли кукурузу, картофель, помидоры, какао и табак из Америки в Старый Свет, а пшеница, рис, сахар, лошади, скот и свиньи шли навстречу. Скромный картофель со временем прокормит демографические взрывы Европы и Китая; перец чили преобразил кухни Индии и Азии.\n\nНо у обмена была катастрофическая сторона. Болезни Старого Света — оспа, корь, грипп — встретили население без иммунитета и прокатились по Америкам, погубив, быть может, 90 процентов коренных народов за столетие. Этот демографический крах, сильнее любой армии, сокрушил великие цивилизации ацтеков и инков и переделал человеческую карту целого полушария." },
    mk: { heading: "Колумбовата размена",
      body: "Патувањата на Колумбо направија повеќе од само политичко поврзување на две полутопки — тие ја поттикнаа најголемата биолошка размена во човечката историја. Бродовите носеа пченка, компири, домати, какао и тутун од Америка во Стариот Свет, додека пченицата, оризот, шеќерот, коњите, говедата и свињите патуваа во спротивна насока. Скромниот компир на крајот ќе ги нахрани демографските бумови на Европа и Кина; лутите пиперки ги преобразија кујните на Индија и Азија.\n\nНо размената имаше и катастрофална страна. Болестите на Стариот Свет — сипаници, мали сипаници, грип — наидоа на население без имунитет и ги прегазија Америките, усмртувајќи можеби 90 отсто од домородните народи за еден век. Овој демографски колапс, посилен од која било војска, ги скрши големите цивилизации на Ацтеките и Инките и ја преобликуваше човечката карта на цела полутопка." },
    de: { heading: "Der Kolumbische Austausch",
      body: "Kolumbus' Fahrten verbanden nicht nur zwei Hemisphären politisch — sie lösten den größten biologischen Austausch der Menschheitsgeschichte aus. Schiffe brachten Mais, Kartoffeln, Tomaten, Kakao und Tabak aus Amerika in die Alte Welt, während Weizen, Reis, Zucker, Pferde, Rinder und Schweine den umgekehrten Weg nahmen. Die bescheidene Kartoffel sollte einst die Bevölkerungsexplosionen Europas und Chinas ernähren; Chilischoten verwandelten die Küchen Indiens und Asiens.\n\nDoch der Austausch hatte eine katastrophale Seite. Krankheiten der Alten Welt — Pocken, Masern, Grippe — trafen auf Bevölkerungen ohne Immunität und fegten durch Amerika, wobei sie binnen eines Jahrhunderts vielleicht 90 Prozent der indigenen Völker töteten. Dieser demografische Zusammenbruch zerschlug, mehr als jedes Heer, die großen Zivilisationen der Azteken und Inka und zeichnete die menschliche Landkarte einer ganzen Hemisphäre neu." },
    fr: { heading: "L'échange colombien",
      body: "Les voyages de Colomb firent plus que relier deux hémisphères sur le plan politique : ils déclenchèrent le plus vaste échange biologique de l'histoire humaine. Les navires transportèrent maïs, pommes de terre, tomates, cacao et tabac d'Amérique vers l'Ancien Monde, tandis que blé, riz, sucre, chevaux, bovins et porcs firent le trajet inverse. L'humble pomme de terre finirait par nourrir les explosions démographiques de l'Europe et de la Chine ; les piments transformèrent les cuisines de l'Inde et de l'Asie.\n\nMais l'échange eut une face catastrophique. Les maladies de l'Ancien Monde — variole, rougeole, grippe — rencontrèrent des populations sans immunité et balayèrent les Amériques, tuant peut-être 90 pour cent des peuples autochtones en un siècle. Cet effondrement démographique, plus que toute armée, brisa les grandes civilisations aztèque et inca et redessina la carte humaine d'un hémisphère entier." },
  },
  'earlymod-02': {
    en: { heading: "The Press That Spread the Reformation",
      body: "When Martin Luther nailed his Ninety-Five Theses to a church door in 1517, he lit a fire that an older world could never have contained — because of a machine invented only decades earlier. Around 1440, Johannes Gutenberg had perfected printing with movable metal type, and by Luther's day presses were spreading across Europe. His theses, meant for scholarly debate in Latin, were translated into German, printed, and read across the continent within weeks.\n\nLuther grasped the power of print as no one before him. He poured out pamphlets in plain German, and his translation of the Bible let ordinary people read scripture for themselves. Cheap, illustrated broadsheets carried the new ideas to those who could not read at all. Without the printing press, the Reformation might have been a local quarrel; with it, it became a movement that permanently split Western Christianity." },
    es: { heading: "La imprenta que difundió la Reforma",
      body: "Cuando Martín Lutero clavó sus Noventa y cinco tesis en la puerta de una iglesia en 1517, encendió un fuego que un mundo más antiguo nunca habría podido contener, gracias a una máquina inventada solo décadas antes. Hacia 1440, Johannes Gutenberg había perfeccionado la impresión con tipos móviles de metal, y en tiempos de Lutero las imprentas se extendían por Europa. Sus tesis, pensadas para el debate erudito en latín, fueron traducidas al alemán, impresas y leídas por todo el continente en pocas semanas.\n\nLutero comprendió el poder de la imprenta como nadie antes que él. Vertió panfletos en alemán sencillo, y su traducción de la Biblia permitió a la gente común leer las Escrituras por sí misma. Baratas hojas ilustradas llevaron las nuevas ideas incluso a quienes no sabían leer. Sin la imprenta, la Reforma podría haber sido una disputa local; con ella, se convirtió en un movimiento que dividió para siempre el cristianismo occidental." },
    ru: { heading: "Печать, разнёсшая Реформацию",
      body: "Когда в 1517 году Мартин Лютер прибил свои Девяносто пять тезисов к церковной двери, он зажёг огонь, который прежний мир не смог бы сдержать, — благодаря машине, изобретённой лишь десятилетия назад. Около 1440 года Иоганн Гутенберг довёл до совершенства печать подвижными металлическими литерами, и ко времени Лютера типографии распространялись по Европе. Его тезисы, задуманные для учёного спора на латыни, за считанные недели были переведены на немецкий, напечатаны и прочитаны по всему континенту.\n\nЛютер осознал силу печати как никто до него. Он изливал памфлеты на простом немецком, а его перевод Библии позволил простым людям читать Писание самим. Дешёвые иллюстрированные листки несли новые идеи и тем, кто вовсе не умел читать. Без печатного станка Реформация могла бы остаться местной ссорой; с ним она стала движением, навсегда расколовшим западное христианство." },
    mk: { heading: "Печатницата што ја рашири Реформацијата",
      body: "Кога Мартин Лутер ги закова своите Деведесет и пет тези на црковната врата во 1517 година, запали оган што еден постар свет никогаш не би можел да го задржи — благодарение на машина измислена само децении претходно. Околу 1440 година, Јоханес Гутенберг ја усоврши печатницата со подвижни метални букви, и во времето на Лутер печатниците се ширеа низ Европа. Неговите тези, наменети за научна расправа на латински, за неколку недели беа преведени на германски, испечатени и читани низ целиот континент.\n\nЛутер ја сфати моќта на печатот како никој пред него. Излеваше памфлети на едноставен германски, а неговиот превод на Библијата им овозможи на обичните луѓе сами да го читаат Писмото. Евтините илустрирани листови ги носеа новите идеи дури и до оние што воопшто не знаеја да читаат. Без печатницата, Реформацијата можеше да биде локална кавга; со неа, стана движење што трајно го расцепи западното христијанство." },
    de: { heading: "Die Presse, die die Reformation verbreitete",
      body: "Als Martin Luther 1517 seine Fünfundneunzig Thesen an eine Kirchentür schlug, entfachte er ein Feuer, das eine ältere Welt niemals hätte eindämmen können — dank einer Maschine, die erst Jahrzehnte zuvor erfunden worden war. Um 1440 hatte Johannes Gutenberg den Druck mit beweglichen Metalllettern vervollkommnet, und zu Luthers Zeit breiteten sich die Druckpressen über Europa aus. Seine Thesen, für die gelehrte Debatte in Latein gedacht, wurden binnen Wochen ins Deutsche übersetzt, gedruckt und auf dem ganzen Kontinent gelesen.\n\nLuther begriff die Macht des Drucks wie niemand vor ihm. Er goss Flugschriften in klarem Deutsch aus, und seine Bibelübersetzung ließ einfache Menschen die Schrift selbst lesen. Billige, bebilderte Einblattdrucke trugen die neuen Ideen selbst zu jenen, die gar nicht lesen konnten. Ohne die Druckerpresse wäre die Reformation vielleicht ein örtlicher Streit geblieben; mit ihr wurde sie zu einer Bewegung, die das westliche Christentum für immer spaltete." },
    fr: { heading: "La presse qui répandit la Réforme",
      body: "Lorsque Martin Luther cloua ses Quatre-vingt-quinze thèses à la porte d'une église en 1517, il alluma un feu qu'un monde plus ancien n'aurait jamais pu contenir — grâce à une machine inventée quelques décennies plus tôt seulement. Vers 1440, Johannes Gutenberg avait perfectionné l'impression à caractères métalliques mobiles, et du temps de Luther les presses se répandaient à travers l'Europe. Ses thèses, destinées au débat savant en latin, furent traduites en allemand, imprimées et lues à travers le continent en quelques semaines.\n\nLuther saisit le pouvoir de l'imprimé comme nul avant lui. Il déversa des pamphlets en allemand simple, et sa traduction de la Bible permit aux gens ordinaires de lire eux-mêmes les Écritures. De bon marché, des feuilles illustrées portèrent les idées nouvelles jusqu'à ceux qui ne savaient pas lire du tout. Sans l'imprimerie, la Réforme aurait pu n'être qu'une querelle locale ; avec elle, elle devint un mouvement qui scinda à jamais le christianisme occidental." },
  },
  'earlymod-03': {
    en: { heading: "Newton's Clockwork Universe",
      body: "The Scientific Revolution reached its summit in 1687, when Isaac Newton published the Principia Mathematica. In it he showed that a single law — universal gravitation — governs both the fall of an apple and the orbit of the Moon, and he set out three laws of motion that describe how everything from cannonballs to planets moves. To do it, he helped invent an entirely new branch of mathematics: calculus.\n\nNewton's achievement was staggering in its ambition. He revealed a universe running like a vast, precise clock, governed by mathematical laws that human reason could discover and predict. This vision electrified the age. If the heavens obeyed rational laws, thinkers asked, might not society, government, and human nature obey discoverable laws too? Newton's clockwork cosmos became the model for the whole Enlightenment faith in reason." },
    es: { heading: "El universo mecánico de Newton",
      body: "La Revolución Científica alcanzó su cima en 1687, cuando Isaac Newton publicó los Principia Mathematica. En ellos demostró que una sola ley —la gravitación universal— rige tanto la caída de una manzana como la órbita de la Luna, y expuso tres leyes del movimiento que describen cómo se mueve todo, desde las balas de cañón hasta los planetas. Para lograrlo, ayudó a inventar una rama enteramente nueva de las matemáticas: el cálculo.\n\nEl logro de Newton fue asombroso en su ambición. Reveló un universo que funcionaba como un vasto y preciso reloj, gobernado por leyes matemáticas que la razón humana podía descubrir y predecir. Esta visión electrizó la época. Si los cielos obedecían leyes racionales, se preguntaban los pensadores, ¿no podrían la sociedad, el gobierno y la naturaleza humana obedecer también leyes descubribles? El cosmos mecánico de Newton se convirtió en el modelo de toda la fe ilustrada en la razón." },
    ru: { heading: "Часовой механизм Вселенной Ньютона",
      body: "Научная революция достигла вершины в 1687 году, когда Исаак Ньютон опубликовал «Математические начала». В них он показал, что единый закон — всемирное тяготение — управляет и падением яблока, и орбитой Луны, и изложил три закона движения, описывающие, как движется всё, от пушечных ядер до планет. Чтобы это сделать, он помог изобрести совершенно новую ветвь математики — исчисление.\n\nДостижение Ньютона поражало своим размахом. Он открыл вселенную, работающую как огромные, точные часы, управляемые математическими законами, которые человеческий разум способен раскрыть и предсказать. Это видение наэлектризовало эпоху. Если небеса подчиняются разумным законам, спрашивали мыслители, не подчиняются ли и общество, власть и человеческая природа законам, которые можно открыть? Часовой космос Ньютона стал образцом для всей просвещенческой веры в разум." },
    mk: { heading: "Часовниковата вселена на Њутн",
      body: "Научната револуција го достигна својот врв во 1687 година, кога Исак Њутн ги објави „Математичките принципи“. Во нив покажа дека еден единствен закон — универзалната гравитација — управува и со паѓањето на јаболкото и со орбитата на Месечината, и изложи три закони на движење што опишуваат како се движи сè, од топовски ѓулиња до планети. За да го стори тоа, помогна да се измисли сосема нова гранка на математиката: сметањето (калкулус).\n\nПостигнувањето на Њутн беше вчудоневидувачко во својата амбиција. Откри вселена што работи како огромен, прецизен часовник, управувана од математички закони што човечкиот разум може да ги открие и предвиди. Оваа визија ја наелектризира епохата. Ако небесата се покоруваат на разумни закони, се прашуваа мислителите, зарем и општеството, власта и човечката природа не би се покорувале на закони што можат да се откријат? Часовниковиот космос на Њутн стана образец за целата просветителска вера во разумот." },
    de: { heading: "Newtons Uhrwerk-Universum",
      body: "Die wissenschaftliche Revolution erreichte 1687 ihren Gipfel, als Isaac Newton die Principia Mathematica veröffentlichte. Darin zeigte er, dass ein einziges Gesetz — die universelle Gravitation — sowohl den Fall eines Apfels als auch die Umlaufbahn des Mondes lenkt, und stellte drei Bewegungsgesetze auf, die beschreiben, wie sich alles von Kanonenkugeln bis zu Planeten bewegt. Dazu half er, einen völlig neuen Zweig der Mathematik zu erfinden: die Infinitesimalrechnung.\n\nNewtons Leistung war atemberaubend in ihrem Anspruch. Er enthüllte ein Universum, das wie ein gewaltiges, präzises Uhrwerk lief, gelenkt von mathematischen Gesetzen, die die menschliche Vernunft entdecken und vorhersagen konnte. Diese Sicht elektrisierte das Zeitalter. Wenn der Himmel vernünftigen Gesetzen gehorchte, fragten die Denker, sollten dann nicht auch Gesellschaft, Regierung und die menschliche Natur entdeckbaren Gesetzen gehorchen? Newtons Uhrwerk-Kosmos wurde zum Vorbild für den ganzen aufklärerischen Glauben an die Vernunft." },
    fr: { heading: "L'univers-horloge de Newton",
      body: "La révolution scientifique atteignit son sommet en 1687, lorsque Isaac Newton publia les Principia Mathematica. Il y montra qu'une seule loi — la gravitation universelle — régit aussi bien la chute d'une pomme que l'orbite de la Lune, et énonça trois lois du mouvement décrivant comment se meut tout, des boulets de canon aux planètes. Pour y parvenir, il contribua à inventer une branche entièrement nouvelle des mathématiques : le calcul infinitésimal.\n\nL'exploit de Newton était stupéfiant d'ambition. Il révéla un univers fonctionnant comme une vaste et précise horloge, régie par des lois mathématiques que la raison humaine pouvait découvrir et prédire. Cette vision électrisa l'époque. Si les cieux obéissaient à des lois rationnelles, se demandaient les penseurs, la société, le gouvernement et la nature humaine ne pourraient-ils pas obéir aussi à des lois décelables ? Le cosmos-horloge de Newton devint le modèle de toute la foi des Lumières en la raison." },
  },
  'earlymod-04': {
    en: { heading: "Versailles: A Palace as Political Machine",
      body: "Louis XIV built the palace of Versailles not merely to dazzle, but to rule. After nobles had rebelled against the crown in his youth, the Sun King devised a subtler cage. He required the great aristocrats of France to live with him at Versailles, where they competed for the honor of handing him his shirt or watching him dine. Absorbed in ceremony and gossip, they had no time to plot rebellion in their own provinces.\n\nEvery detail served power. The dazzling Hall of Mirrors, the vast gardens, the rigid etiquette that governed each hour — all proclaimed that the king was the sun around which France revolved. 'L'état, c'est moi' — 'I am the state' — expressed his claim to absolute authority. Versailles became the envy of Europe, and rulers from Vienna to St. Petersburg built palaces in imitation, spreading the theatre of absolute monarchy across the continent." },
    es: { heading: "Versalles: un palacio como máquina política",
      body: "Luis XIV construyó el palacio de Versalles no solo para deslumbrar, sino para gobernar. Después de que los nobles se rebelaran contra la corona en su juventud, el Rey Sol ideó una jaula más sutil. Exigió que los grandes aristócratas de Francia vivieran con él en Versalles, donde competían por el honor de entregarle la camisa o de verlo cenar. Absortos en el ceremonial y los chismes, no tenían tiempo de tramar rebeliones en sus propias provincias.\n\nCada detalle servía al poder. La deslumbrante Galería de los Espejos, los vastos jardines, la rígida etiqueta que regía cada hora, todo proclamaba que el rey era el sol en torno al cual giraba Francia. 'L'état, c'est moi' —'El Estado soy yo'— expresaba su pretensión de autoridad absoluta. Versalles se convirtió en la envidia de Europa, y soberanos desde Viena hasta San Petersburgo construyeron palacios a imitación suya, extendiendo el teatro de la monarquía absoluta por el continente." },
    ru: { heading: "Версаль: дворец как политическая машина",
      body: "Людовик XIV построил Версальский дворец не только чтобы ослеплять, но чтобы править. После того как в его юности знать восстала против короны, Король-солнце придумал более тонкую клетку. Он потребовал, чтобы крупнейшие аристократы Франции жили при нём в Версале, где они соперничали за честь подать ему рубашку или смотреть, как он обедает. Поглощённые церемониями и сплетнями, они не имели времени готовить мятеж в своих провинциях.\n\nКаждая деталь служила власти. Ослепительная Зеркальная галерея, огромные сады, строгий этикет, размерявший каждый час, — всё возвещало, что король есть солнце, вокруг которого вращается Франция. «L'état, c'est moi» — «Государство — это я» — выражало его притязание на абсолютную власть. Версаль стал предметом зависти Европы, и правители от Вены до Петербурга строили дворцы в подражание ему, разнося театр абсолютной монархии по континенту." },
    mk: { heading: "Версај: палата како политичка машина",
      body: "Луј XIV ја изгради палатата Версај не само за да заслепува, туку за да владее. Откако благородниците се побунија против круната во неговата младост, Кралот-Сонце смисли посуптилен кафез. Побара најголемите аристократи на Франција да живеат со него во Версај, каде што се натпреваруваа за честа да му ја подадат кошулата или да го гледаат како вечера. Обземени од церемонии и озборувања, немаа време да ковеат бунт во своите провинции.\n\nСекој детаљ ѝ служеше на власта. Заслепувачката Огледална сала, огромните градини, крутиот бонтон што управуваше со секој час — сè прогласуваше дека кралот е сонцето околу кое се врти Франција. „L'état, c'est moi“ — „Државата, тоа сум јас“ — ја изразуваше неговата претензија за апсолутна власт. Версај стана предмет на завист во Европа, и владетели од Виена до Санкт Петербург градеа палати по негов углед, ширејќи го театарот на апсолутната монархија низ континентот." },
    de: { heading: "Versailles: ein Schloss als politische Maschine",
      body: "Ludwig XIV. baute das Schloss von Versailles nicht nur, um zu blenden, sondern um zu herrschen. Nachdem sich in seiner Jugend Adlige gegen die Krone erhoben hatten, ersann der Sonnenkönig einen subtileren Käfig. Er verlangte, dass die großen Aristokraten Frankreichs mit ihm in Versailles lebten, wo sie um die Ehre wetteiferten, ihm das Hemd zu reichen oder ihm beim Speisen zuzusehen. In Zeremoniell und Klatsch versunken, hatten sie keine Zeit, in ihren eigenen Provinzen Aufruhr zu schmieden.\n\nJede Einzelheit diente der Macht. Der blendende Spiegelsaal, die weiten Gärten, die strenge Etikette, die jede Stunde regelte — all das verkündete, dass der König die Sonne war, um die sich Frankreich drehte. 'L'état, c'est moi' — 'Der Staat bin ich' — drückte seinen Anspruch auf absolute Herrschaft aus. Versailles wurde zum Neid Europas, und Herrscher von Wien bis St. Petersburg bauten Schlösser nach seinem Vorbild und trugen das Theater der absoluten Monarchie über den Kontinent." },
    fr: { heading: "Versailles : un palais comme machine politique",
      body: "Louis XIV bâtit le château de Versailles non pour éblouir seulement, mais pour régner. Après que des nobles se furent révoltés contre la couronne dans sa jeunesse, le Roi-Soleil conçut une cage plus subtile. Il exigea que les grands aristocrates de France vécussent auprès de lui à Versailles, où ils rivalisaient pour l'honneur de lui tendre sa chemise ou de le regarder dîner. Absorbés par le cérémonial et les commérages, ils n'avaient plus le temps de comploter des rébellions dans leurs propres provinces.\n\nChaque détail servait le pouvoir. L'éblouissante galerie des Glaces, les vastes jardins, l'étiquette rigide qui réglait chaque heure — tout proclamait que le roi était le soleil autour duquel tournait la France. 'L'État, c'est moi' exprimait sa prétention à l'autorité absolue. Versailles devint l'envie de l'Europe, et des souverains de Vienne à Saint-Pétersbourg bâtirent des palais à son imitation, répandant le théâtre de la monarchie absolue à travers le continent." },
  },
  'earlymod-05': {
    en: { heading: "Resistance and the Haitian Revolution",
      body: "The enslaved never accepted their bondage quietly. From the first, they resisted — breaking tools, escaping to form free 'maroon' communities in the mountains, and rising in revolt. The greatest of these uprisings erupted in 1791 in Saint-Domingue, France's richest sugar colony and one of the most brutal.\n\nUnder leaders like the brilliant Toussaint Louverture, the enslaved of Saint-Domingue defeated the armies of France, Spain, and Britain in turn. In 1804 they declared independence as Haiti — the first nation born of a successful slave revolt, and the first modern state to abolish slavery outright. Haiti's revolution terrified slaveholders across the Americas and inspired the enslaved everywhere. It proved that the ideals of liberty proclaimed in Paris and Philadelphia belonged to all people — a truth their authors had tried to deny." },
    es: { heading: "La resistencia y la Revolución haitiana",
      body: "Los esclavizados nunca aceptaron su servidumbre en silencio. Desde el principio resistieron: rompiendo herramientas, huyendo para formar comunidades libres de 'cimarrones' en las montañas y alzándose en revuelta. La mayor de estas rebeliones estalló en 1791 en Saint-Domingue, la colonia azucarera más rica de Francia y una de las más brutales.\n\nBajo líderes como el brillante Toussaint Louverture, los esclavizados de Saint-Domingue derrotaron por turnos a los ejércitos de Francia, España y Gran Bretaña. En 1804 declararon la independencia como Haití: la primera nación nacida de una revuelta de esclavos triunfante y el primer Estado moderno en abolir por completo la esclavitud. La revolución de Haití aterrorizó a los esclavistas de toda América e inspiró a los esclavizados en todas partes. Demostró que los ideales de libertad proclamados en París y Filadelfia pertenecían a todos, una verdad que sus autores habían intentado negar." },
    ru: { heading: "Сопротивление и Гаитянская революция",
      body: "Порабощённые никогда не принимали своё рабство молча. С самого начала они сопротивлялись — ломали орудия, бежали, чтобы основать свободные общины «маронов» в горах, и поднимались на восстания. Величайшее из этих восстаний вспыхнуло в 1791 году в Сан-Доминго, богатейшей и одной из самых жестоких сахарных колоний Франции.\n\nПод началом таких вождей, как блистательный Туссен-Лувертюр, порабощённые Сан-Доминго поочерёдно разбили армии Франции, Испании и Британии. В 1804 году они провозгласили независимость как Гаити — первую нацию, рождённую победившим восстанием рабов, и первое современное государство, полностью упразднившее рабство. Гаитянская революция привела в ужас рабовладельцев по всей Америке и вдохновила порабощённых повсюду. Она доказала, что идеалы свободы, провозглашённые в Париже и Филадельфии, принадлежат всем людям, — истина, которую их авторы пытались отрицать." },
    mk: { heading: "Отпорот и Хаитската револуција",
      body: "Поробените никогаш не го прифаќаа своето ропство молкум. Од самиот почеток пружаа отпор — кршејќи алат, бегајќи за да формираат слободни заедници на „маруни“ во планините и креваа буни. Најголемата од овие буни избувна во 1791 година во Сен-Доменг, најбогатата шеќерна колонија на Франција и една од најсуровите.\n\nПод водачи како брилијантниот Тусен Лувертир, поробените од Сен-Доменг ги победија по ред армиите на Франција, Шпанија и Британија. Во 1804 година прогласија независност како Хаити — првата нација родена од успешна робовска буна и првата модерна држава што целосно го укина ропството. Хаитската револуција ги ужаса робовладетелите низ Америките и ги инспирираше поробените насекаде. Докажа дека идеалите на слободата прогласени во Париз и Филаделфија им припаѓаат на сите луѓе — вистина што нивните автори се обидоа да ја негираат." },
    de: { heading: "Widerstand und die Haitianische Revolution",
      body: "Die Versklavten nahmen ihre Knechtschaft nie stillschweigend hin. Von Anfang an leisteten sie Widerstand — zerbrachen Werkzeuge, entflohen, um in den Bergen freie 'Maroon'-Gemeinschaften zu bilden, und erhoben sich zum Aufstand. Der größte dieser Aufstände brach 1791 in Saint-Domingue aus, Frankreichs reichster und einer der brutalsten Zuckerkolonien.\n\nUnter Anführern wie dem brillanten Toussaint Louverture besiegten die Versklavten von Saint-Domingue nacheinander die Heere Frankreichs, Spaniens und Britanniens. 1804 erklärten sie die Unabhängigkeit als Haiti — die erste Nation, aus einem erfolgreichen Sklavenaufstand geboren, und der erste moderne Staat, der die Sklaverei gänzlich abschaffte. Haitis Revolution versetzte Sklavenhalter in ganz Amerika in Schrecken und beflügelte die Versklavten überall. Sie bewies, dass die in Paris und Philadelphia verkündeten Ideale der Freiheit allen Menschen gehörten — eine Wahrheit, die ihre Urheber zu leugnen versucht hatten." },
    fr: { heading: "La résistance et la révolution haïtienne",
      body: "Les esclaves n'acceptèrent jamais leur servitude en silence. Dès le début, ils résistèrent : brisant les outils, fuyant pour former de libres communautés de 'marrons' dans les montagnes, et se soulevant en révolte. La plus grande de ces insurrections éclata en 1791 à Saint-Domingue, la plus riche colonie sucrière de France et l'une des plus brutales.\n\nSous des chefs comme le brillant Toussaint Louverture, les esclaves de Saint-Domingue défirent tour à tour les armées de la France, de l'Espagne et de la Grande-Bretagne. En 1804, ils proclamèrent l'indépendance sous le nom d'Haïti — la première nation née d'une révolte d'esclaves victorieuse, et le premier État moderne à abolir purement et simplement l'esclavage. La révolution haïtienne terrifia les esclavagistes de toute l'Amérique et inspira les esclaves partout. Elle prouva que les idéaux de liberté proclamés à Paris et à Philadelphie appartenaient à tous les hommes — une vérité que leurs auteurs avaient tenté de nier." },
  },
  'earlymod-06': {
    en: { heading: "The Devshirme: Slaves Who Ruled an Empire",
      body: "The Ottoman Empire was run in large part by a remarkable and paradoxical institution: the devshirme, or 'child levy.' Every few years, Ottoman officials traveled through the empire's Christian villages in the Balkans and took a quota of boys. Converted to Islam and trained intensively, they became the personal servants of the sultan — technically his slaves, yet the most powerful men in the state.\n\nThe most promising rose through palace schools to become governors, generals, and even grand viziers. The rest formed the Janissaries, the disciplined, gunpowder-armed infantry that made the Ottoman army the terror of Europe. Because these men owed everything to the sultan and could own no hereditary estates, they could not build rival dynasties. It was a striking answer to the problem that plagued every monarchy — how to command a loyal, capable elite that would not turn on the throne." },
    es: { heading: "El devshirme: esclavos que gobernaron un imperio",
      body: "El Imperio otomano funcionaba en gran parte gracias a una institución notable y paradójica: el devshirme, o 'leva de niños'. Cada pocos años, funcionarios otomanos recorrían las aldeas cristianas del imperio en los Balcanes y tomaban una cuota de muchachos. Convertidos al islam y adiestrados intensamente, se convertían en los siervos personales del sultán —técnicamente sus esclavos, y sin embargo los hombres más poderosos del Estado—.\n\nLos más prometedores ascendían por las escuelas de palacio hasta ser gobernadores, generales e incluso grandes visires. El resto formaba los jenízaros, la disciplinada infantería armada con pólvora que hizo del ejército otomano el terror de Europa. Como estos hombres se lo debían todo al sultán y no podían poseer feudos hereditarios, no podían fundar dinastías rivales. Fue una respuesta llamativa al problema que aquejaba a toda monarquía: cómo mandar sobre una élite leal y capaz que no se volviera contra el trono." },
    ru: { heading: "Девширме: рабы, правившие империей",
      body: "Османская империя во многом держалась на замечательном и парадоксальном учреждении — девширме, или «наборе мальчиков». Раз в несколько лет османские чиновники объезжали христианские сёла империи на Балканах и брали положенное число мальчиков. Обращённые в ислам и усиленно обученные, они становились личными слугами султана — формально его рабами и всё же самыми могущественными людьми государства.\n\nНаиболее одарённые поднимались через дворцовые школы до наместников, полководцев и даже великих визирей. Остальные составляли янычар — дисциплинированную, вооружённую огнестрельным оружием пехоту, сделавшую османскую армию грозой Европы. Поскольку эти люди были всем обязаны султану и не могли владеть наследственными поместьями, они не могли создать соперничающих династий. Это был поразительный ответ на проблему, мучившую всякую монархию, — как повелевать верной и способной элитой, которая не восстанет против трона." },
    mk: { heading: "Девширме: робови што владееја со империја",
      body: "Отоманската империја во голем дел се потпираше на една извонредна и парадоксална институција: девширме, или „данок во крв“. На секои неколку години, отомански службеници ги обиколуваа христијанските села на империјата на Балканот и земаа определен број момчиња. Преобратени во ислам и интензивно обучени, тие стануваа лични слуги на султанот — технички негови робови, а сепак најмоќните луѓе во државата.\n\nНајперспективните се искачуваа преку дворските училишта до гувернери, генерали, па дури и велики везири. Останатите ги сочинуваа јаничарите, дисциплинираната пешадија вооружена со барут што ја направи отоманската војска ужас на Европа. Бидејќи овие луѓе му должеа сè на султанот и не можеа да поседуваат наследни имоти, не можеа да градат ривалски династии. Тоа беше впечатлив одговор на проблемот што ја мачеше секоја монархија — како да се командува лојална, способна елита што нема да се сврти против престолот." },
    de: { heading: "Die Devschirme: Sklaven, die ein Reich beherrschten",
      body: "Das Osmanische Reich wurde zu großen Teilen von einer bemerkenswerten und paradoxen Einrichtung getragen: der Devschirme, der 'Knabenlese'. Alle paar Jahre zogen osmanische Beamte durch die christlichen Dörfer des Reiches auf dem Balkan und hoben ein Kontingent Jungen aus. Zum Islam bekehrt und straff ausgebildet, wurden sie die persönlichen Diener des Sultans — förmlich seine Sklaven und doch die mächtigsten Männer des Staates.\n\nDie Vielversprechendsten stiegen über die Palastschulen zu Statthaltern, Feldherren und sogar Großwesiren auf. Die übrigen bildeten die Janitscharen, die disziplinierte, mit Feuerwaffen bewaffnete Infanterie, die das osmanische Heer zum Schrecken Europas machte. Weil diese Männer dem Sultan alles verdankten und keine Erbgüter besitzen durften, konnten sie keine rivalisierenden Dynastien gründen. Es war eine erstaunliche Antwort auf das Problem, das jede Monarchie plagte — wie man eine treue, fähige Elite befehligt, die sich nicht gegen den Thron wendet." },
    fr: { heading: "Le devchirmé : des esclaves qui gouvernèrent un empire",
      body: "L'Empire ottoman reposait en grande partie sur une institution remarquable et paradoxale : le devchirmé, ou 'ramassage d'enfants'. Tous les quelques années, des fonctionnaires ottomans parcouraient les villages chrétiens de l'empire dans les Balkans et prélevaient un quota de garçons. Convertis à l'islam et formés intensivement, ils devenaient les serviteurs personnels du sultan — techniquement ses esclaves, et pourtant les hommes les plus puissants de l'État.\n\nLes plus prometteurs s'élevaient par les écoles du palais jusqu'à devenir gouverneurs, généraux et même grands vizirs. Les autres formaient les janissaires, l'infanterie disciplinée et armée de poudre qui fit de l'armée ottomane la terreur de l'Europe. Comme ces hommes devaient tout au sultan et ne pouvaient posséder de domaines héréditaires, ils ne pouvaient fonder de dynasties rivales. Ce fut une réponse frappante au problème qui rongeait toute monarchie : comment commander une élite loyale et capable qui ne se retournerait pas contre le trône." },
  },
  'earlymod-07': {
    en: { heading: "The Rights of Man — and of Woman",
      body: "The Age of Revolution was above all a war of ideas, and its most explosive weapon was the claim that all people are born with rights. The American Declaration of Independence (1776) held it 'self-evident' that all men are created equal; France's Declaration of the Rights of Man (1789) proclaimed liberty, equality, and popular sovereignty. These documents electrified the world and still underlie modern democracy.\n\nYet their promises were incomplete, and contemporaries noticed. In 1791 the French writer Olympe de Gouges published a Declaration of the Rights of Woman, insisting that women too were born free and equal; she was later guillotined. In England, Mary Wollstonecraft demanded education and rights for women. The enslaved of Haiti took the revolutionaries at their word and won their freedom. The Age of Revolution thus launched not a finished idea but an argument — over who exactly was included in the word 'everyone' — that would drive two centuries of struggle." },
    es: { heading: "Los derechos del hombre… y de la mujer",
      body: "La Era de las Revoluciones fue ante todo una guerra de ideas, y su arma más explosiva fue la afirmación de que todas las personas nacen con derechos. La Declaración de Independencia estadounidense (1776) sostuvo como 'evidente' que todos los hombres son creados iguales; la Declaración de los Derechos del Hombre de Francia (1789) proclamó la libertad, la igualdad y la soberanía popular. Estos documentos electrizaron al mundo y aún sustentan la democracia moderna.\n\nPero sus promesas eran incompletas, y los contemporáneos lo notaron. En 1791 la escritora francesa Olympe de Gouges publicó una Declaración de los Derechos de la Mujer, insistiendo en que también las mujeres nacían libres e iguales; más tarde fue guillotinada. En Inglaterra, Mary Wollstonecraft exigió educación y derechos para las mujeres. Los esclavizados de Haití tomaron a los revolucionarios por su palabra y conquistaron su libertad. La Era de las Revoluciones lanzó así no una idea acabada, sino una discusión —sobre quién estaba exactamente incluido en la palabra 'todos'— que impulsaría dos siglos de lucha." },
    ru: { heading: "Права человека — и женщины",
      body: "Эпоха революций была прежде всего войной идей, и её самым взрывоопасным оружием стало утверждение, что все люди рождаются с правами. Американская Декларация независимости (1776) провозгласила «самоочевидным», что все люди созданы равными; французская Декларация прав человека (1789) объявила свободу, равенство и народный суверенитет. Эти документы наэлектризовали мир и по сей день лежат в основе современной демократии.\n\nОднако их обещания были неполны, и современники это замечали. В 1791 году французская писательница Олимпия де Гуж опубликовала Декларацию прав женщины, настаивая, что и женщины рождаются свободными и равными; позже её гильотинировали. В Англии Мэри Уолстонкрафт требовала образования и прав для женщин. Порабощённые Гаити поймали революционеров на слове и завоевали свободу. Так эпоха революций породила не готовую идею, а спор — о том, кто именно включён в слово «все», — которому предстояло двигать два столетия борьбы." },
    mk: { heading: "Правата на човекот — и на жената",
      body: "Ерата на револуциите беше пред сè војна на идеи, а нејзиното најексплозивно оружје беше тврдењето дека сите луѓе се раѓаат со права. Американската Декларација за независност (1776) го сметаше за „самоочигледно“ дека сите луѓе се создадени еднакви; француската Декларација за правата на човекот (1789) ги прогласи слободата, еднаквоста и народниот суверенитет. Овие документи го наелектризираа светот и сè уште ја темелат модерната демократија.\n\nНо нивните ветувања беа нецелосни, и современиците го забележаа тоа. Во 1791 година француската писателка Олимп де Гуж објави Декларација за правата на жената, инсистирајќи дека и жените се раѓаат слободни и еднакви; подоцна беше гилотинирана. Во Англија, Мери Волстонкрафт бараше образование и права за жените. Поробените од Хаити ги сфатија револуционерите буквално и си ја извојуваа слободата. Ерата на револуциите така лансираше не завршена идеја, туку расправа — за тоа кој точно е вклучен во зборот „сите“ — што ќе поттикне два века борба." },
    de: { heading: "Die Rechte des Menschen — und der Frau",
      body: "Das Zeitalter der Revolutionen war vor allem ein Krieg der Ideen, und seine explosivste Waffe war die Behauptung, dass alle Menschen mit Rechten geboren werden. Die amerikanische Unabhängigkeitserklärung (1776) hielt es für 'selbstverständlich', dass alle Menschen gleich geschaffen sind; Frankreichs Erklärung der Menschenrechte (1789) verkündete Freiheit, Gleichheit und Volkssouveränität. Diese Dokumente elektrisierten die Welt und liegen noch heute der modernen Demokratie zugrunde.\n\nDoch ihre Versprechen waren unvollständig, und Zeitgenossen bemerkten es. 1791 veröffentlichte die französische Schriftstellerin Olympe de Gouges eine Erklärung der Rechte der Frau und beharrte darauf, dass auch Frauen frei und gleich geboren seien; später wurde sie guillotiniert. In England forderte Mary Wollstonecraft Bildung und Rechte für Frauen. Die Versklavten Haitis nahmen die Revolutionäre beim Wort und erkämpften ihre Freiheit. So brachte das Zeitalter der Revolutionen keine fertige Idee hervor, sondern einen Streit — darüber, wer genau in das Wort 'alle' eingeschlossen war —, der zwei Jahrhunderte des Ringens antreiben sollte." },
    fr: { heading: "Les droits de l'homme — et de la femme",
      body: "L'âge des révolutions fut avant tout une guerre d'idées, et son arme la plus explosive fut l'affirmation que tous les êtres humains naissent avec des droits. La Déclaration d'indépendance américaine (1776) tenait pour 'évident' que tous les hommes sont créés égaux ; la Déclaration des droits de l'homme française (1789) proclama la liberté, l'égalité et la souveraineté populaire. Ces textes électrisèrent le monde et fondent encore la démocratie moderne.\n\nMais leurs promesses étaient incomplètes, et les contemporains le remarquèrent. En 1791, l'écrivaine française Olympe de Gouges publia une Déclaration des droits de la femme, insistant sur le fait que les femmes aussi naissaient libres et égales ; elle fut plus tard guillotinée. En Angleterre, Mary Wollstonecraft réclama l'éducation et des droits pour les femmes. Les esclaves d'Haïti prirent les révolutionnaires au mot et conquirent leur liberté. L'âge des révolutions lança ainsi non une idée achevée, mais une dispute — sur qui exactement était compris dans le mot 'tous' — qui allait animer deux siècles de luttes." },
  },
  'earlymod-08': {
    en: { heading: "The Taj Mahal and Mughal Splendor",
      body: "At its height, the Mughal Empire ruled most of the Indian subcontinent and dazzled the world with its wealth and art. Mughal culture fused Persian, Islamic, and Indian traditions into something wholly new — in miniature painting, poetry, garden design, and above all architecture. Emperor Akbar had set the tone with a policy of religious tolerance, even inviting scholars of many faiths to debate at his court.\n\nThe empire's art reached its summit under Akbar's grandson Shah Jahan, who between 1632 and 1653 built the Taj Mahal at Agra as a tomb for his beloved wife Mumtaz Mahal. A vision of white marble inlaid with precious stones, perfectly symmetrical and mirrored in still pools, it is often called the most beautiful building on Earth. It stands as the supreme monument of an empire whose splendor made 'Mughal' a byword for magnificence." },
    es: { heading: "El Taj Mahal y el esplendor mogol",
      body: "En su apogeo, el Imperio mogol gobernó la mayor parte del subcontinente indio y deslumbró al mundo con su riqueza y su arte. La cultura mogol fusionó las tradiciones persa, islámica e india en algo enteramente nuevo: en la pintura en miniatura, la poesía, el diseño de jardines y, sobre todo, la arquitectura. El emperador Akbar había marcado la pauta con una política de tolerancia religiosa, e incluso invitaba a sabios de muchas religiones a debatir en su corte.\n\nEl arte del imperio alcanzó su cima bajo el nieto de Akbar, Sha Jahan, quien entre 1632 y 1653 construyó el Taj Mahal en Agra como tumba para su amada esposa Mumtaz Mahal. Una visión de mármol blanco con incrustaciones de piedras preciosas, perfectamente simétrica y reflejada en estanques inmóviles, a menudo se le llama el edificio más hermoso de la Tierra. Se alza como el monumento supremo de un imperio cuyo esplendor hizo de 'mogol' un sinónimo de magnificencia." },
    ru: { heading: "Тадж-Махал и великолепие Моголов",
      body: "На вершине могущества империя Великих Моголов правила большей частью Индийского субконтинента и поражала мир своим богатством и искусством. Могольская культура сплавила персидские, исламские и индийские традиции в нечто совершенно новое — в миниатюре, поэзии, устройстве садов и прежде всего в архитектуре. Император Акбар задал тон политикой религиозной терпимости, даже приглашая учёных разных вер спорить при своём дворе.\n\nИскусство империи достигло вершины при внуке Акбара Шах-Джахане, который между 1632 и 1653 годами построил Тадж-Махал в Агре как усыпальницу для любимой жены Мумтаз-Махал. Видение из белого мрамора, инкрустированного драгоценными камнями, совершенно симметричное и отражённое в недвижных прудах, — его часто называют красивейшим зданием на Земле. Он стоит как высший памятник империи, чьё великолепие сделало слово «могольский» синонимом роскоши." },
    mk: { heading: "Таџ Махал и раскошот на Моголите",
      body: "На својот врв, Моголската империја владееше со поголемиот дел од Индискиот потконтинент и го заслепуваше светот со своето богатство и уметност. Моголската култура ги споија персиските, исламските и индиските традиции во нешто сосема ново — во минијатурното сликарство, поезијата, обликувањето градини и пред сè во архитектурата. Императорот Акбар го зададе тонот со политика на верска толеранција, дури повикувајќи учени од многу вери да расправаат на неговиот двор.\n\nУметноста на империјата го достигна својот врв под внукот на Акбар, Шах Џахан, кој меѓу 1632 и 1653 година го изгради Таџ Махал во Агра како гробница за својата сакана сопруга Мумтаз Махал. Визија од бел мермер обложен со скапоцени камења, совршено симетричен и огледан во мирни базени, честопати се нарекува најубавата градба на Земјата. Стои како врвен споменик на империја чиј раскош го направи зборот „моголски“ синоним за величественост." },
    de: { heading: "Der Taj Mahal und die Pracht der Moguln",
      body: "Auf seinem Höhepunkt beherrschte das Mogulreich den größten Teil des indischen Subkontinents und blendete die Welt mit seinem Reichtum und seiner Kunst. Die Mogulkultur verschmolz persische, islamische und indische Traditionen zu etwas völlig Neuem — in der Miniaturmalerei, der Dichtung, der Gartenkunst und vor allem der Architektur. Kaiser Akbar hatte mit einer Politik religiöser Toleranz den Ton angegeben und lud sogar Gelehrte vieler Glaubensrichtungen ein, an seinem Hof zu disputieren.\n\nDie Kunst des Reiches erreichte ihren Gipfel unter Akbars Enkel Shah Jahan, der zwischen 1632 und 1653 den Taj Mahal in Agra als Grabmal für seine geliebte Frau Mumtaz Mahal errichtete. Eine Vision aus weißem Marmor mit Edelsteineinlagen, vollkommen symmetrisch und in stillen Wasserbecken gespiegelt, wird er oft das schönste Gebäude der Erde genannt. Er steht als das höchste Denkmal eines Reiches, dessen Pracht das Wort 'Mogul' zum Inbegriff der Herrlichkeit machte." },
    fr: { heading: "Le Taj Mahal et la splendeur moghole",
      body: "À son apogée, l'Empire moghol régnait sur la plus grande partie du sous-continent indien et éblouissait le monde par sa richesse et son art. La culture moghole fondit les traditions persane, islamique et indienne en quelque chose d'entièrement nouveau — dans la peinture de miniatures, la poésie, l'art des jardins et surtout l'architecture. L'empereur Akbar avait donné le ton par une politique de tolérance religieuse, invitant même des savants de nombreuses confessions à débattre à sa cour.\n\nL'art de l'empire atteignit son sommet sous le petit-fils d'Akbar, Shah Jahan, qui entre 1632 et 1653 fit édifier le Taj Mahal à Agra comme tombeau pour son épouse bien-aimée Mumtaz Mahal. Vision de marbre blanc incrusté de pierres précieuses, parfaitement symétrique et reflétée dans des bassins immobiles, on le nomme souvent le plus beau bâtiment de la Terre. Il se dresse comme le monument suprême d'un empire dont la splendeur fit du mot 'moghol' un synonyme de magnificence." },
  },
  'earlymod-09': {
    en: { heading: "The Floating World of Edo",
      body: "Under the Tokugawa shoguns, Japan closed itself to the outside world for over two centuries — and turned that isolation into a hothouse of culture. Peace allowed the castle town of Edo (modern Tokyo) to swell into perhaps the largest city on Earth, home to a million people. A wealthy merchant class, though ranked low in the rigid social order, spent its money on pleasure and art.\n\nOut of this world came the ukiyo, the 'floating world' of theatres, teahouses, and entertainment districts. Its artists produced ukiyo-e woodblock prints — including Hokusai's Great Wave — that would later astonish Europe. Kabuki theatre thrilled crowds, and the poet Bashō perfected the haiku, capturing whole seasons in seventeen syllables. When Japan finally reopened in the 19th century, it emerged not backward but with a deep, distinctive culture that captivated the world." },
    es: { heading: "El mundo flotante de Edo",
      body: "Bajo los shogunes Tokugawa, Japón se cerró al mundo exterior durante más de dos siglos, y convirtió ese aislamiento en un invernadero de cultura. La paz permitió que la ciudad-castillo de Edo (el actual Tokio) creciera hasta ser quizá la mayor ciudad de la Tierra, hogar de un millón de personas. Una próspera clase mercantil, aunque de bajo rango en el rígido orden social, gastaba su dinero en el placer y el arte.\n\nDe este mundo surgió el ukiyo, el 'mundo flotante' de teatros, casas de té y distritos de entretenimiento. Sus artistas produjeron las estampas ukiyo-e —incluida la Gran Ola de Hokusai— que más tarde asombrarían a Europa. El teatro kabuki emocionaba a las multitudes, y el poeta Bashō perfeccionó el haiku, capturando estaciones enteras en diecisiete sílabas. Cuando Japón por fin se reabrió en el siglo XIX, no emergió atrasado, sino con una cultura profunda y singular que cautivó al mundo." },
    ru: { heading: "Плывущий мир Эдо",
      body: "При сёгунах Токугава Япония более двух веков была закрыта от внешнего мира — и превратила эту изоляцию в теплицу культуры. Мир позволил замковому городу Эдо (современный Токио) разрастись, быть может, в крупнейший город на Земле с миллионным населением. Богатое купечество, хотя и стоявшее низко в жёстком сословном порядке, тратило деньги на удовольствия и искусство.\n\nИз этого мира вышел укиё — «плывущий мир» театров, чайных домов и кварталов развлечений. Его художники создавали гравюры укиё-э — включая «Большую волну» Хокусая, — которые позже поразят Европу. Театр кабуки будоражил толпы, а поэт Басё довёл до совершенства хайку, вмещая целые времена года в семнадцать слогов. Когда Япония наконец вновь открылась в XIX веке, она предстала не отсталой, а с глубокой, самобытной культурой, покорившей мир." },
    mk: { heading: "Пловечкиот свет на Едо",
      body: "Под шогуните Токугава, Јапонија се затвори од надворешниот свет повеќе од два века — и таа изолација ја претвори во стакленик на културата. Мирот ѝ овозможи на градот-замок Едо (денешен Токио) да набабри во можеби најголемиот град на Земјата, дом на еден милион луѓе. Богатата трговска класа, иако ниско рангирана во крутиот општествен поредок, ги трошеше своите пари на уживање и уметност.\n\nОд овој свет произлезе укијо, „пловечкиот свет“ на театри, чајни и забавни квартови. Неговите уметници создаваа укијо-е дрворезни отпечатоци — вклучувајќи го „Големиот бран“ на Хокусаи — што подоцна ќе ја зачудат Европа. Кабуки театарот ги воодушевуваше толпите, а поетот Башо го усоврши хаикуто, фаќајќи цели годишни времиња во седумнаесет слогови. Кога Јапонија конечно повторно се отвори во 19 век, не се појави заостаната, туку со длабока, самобитна култура што го освои светот." },
    de: { heading: "Die fließende Welt von Edo",
      body: "Unter den Tokugawa-Shogunen schloss sich Japan über zwei Jahrhunderte lang von der Außenwelt ab — und verwandelte diese Isolation in ein Treibhaus der Kultur. Der Friede ließ die Burgstadt Edo (das heutige Tokio) zur vielleicht größten Stadt der Erde anschwellen, Heimat von einer Million Menschen. Eine wohlhabende Kaufmannsschicht, obgleich niedrig in der starren Ständeordnung, gab ihr Geld für Vergnügen und Kunst aus.\n\nAus dieser Welt entstand das Ukiyo, die 'fließende Welt' der Theater, Teehäuser und Vergnügungsviertel. Ihre Künstler schufen Ukiyo-e-Holzschnitte — darunter Hokusais Große Welle —, die später Europa in Staunen versetzen sollten. Das Kabuki-Theater begeisterte die Menge, und der Dichter Bashō vervollkommnete das Haiku, das ganze Jahreszeiten in siebzehn Silben einfing. Als Japan sich im 19. Jahrhundert endlich wieder öffnete, trat es nicht rückständig hervor, sondern mit einer tiefen, unverwechselbaren Kultur, die die Welt bezauberte." },
    fr: { heading: "Le monde flottant d'Edo",
      body: "Sous les shoguns Tokugawa, le Japon se ferma au monde extérieur pendant plus de deux siècles — et transforma cet isolement en une serre de culture. La paix permit à la ville-château d'Edo (l'actuelle Tokyo) de gonfler jusqu'à devenir peut-être la plus grande ville de la Terre, peuplée d'un million d'habitants. Une riche classe marchande, quoique de bas rang dans l'ordre social rigide, dépensait son argent en plaisirs et en art.\n\nDe ce monde naquit l'ukiyo, le 'monde flottant' des théâtres, des maisons de thé et des quartiers de divertissement. Ses artistes produisirent les estampes ukiyo-e — dont la Grande Vague de Hokusai — qui allaient plus tard étonner l'Europe. Le théâtre kabuki enflammait les foules, et le poète Bashō perfectionna le haïku, saisissant des saisons entières en dix-sept syllabes. Lorsque le Japon rouvrit enfin ses portes au XIXe siècle, il n'apparut pas arriéré, mais doté d'une culture profonde et singulière qui captiva le monde." },
  },

  // ══════════════════════════ MODERN ══════════════════════════
  'modern-01': {
    en: { heading: "Steam, Coal, and the Railway Age",
      body: "The heart of the Industrial Revolution beat with steam. James Watt's improved steam engine, perfected in the 1770s, gave humanity a source of power that did not depend on wind, water, or muscle — and it ran on coal, which Britain possessed in abundance. Factories could now be built anywhere, running day and night, and their output exploded.\n\nSteam's most dramatic child was the railway. When the Liverpool and Manchester Railway opened in 1830, people who had never traveled faster than a galloping horse were suddenly hurtled across the country at unheard-of speed. Railways collapsed distances, carried coal and cotton to the ports, and stitched nations together. They also created the modern sense of time: to keep trains from colliding, Britain imposed a single standard time, ending the patchwork of local clocks that had governed human life for millennia." },
    es: { heading: "Vapor, carbón y la era del ferrocarril",
      body: "El corazón de la Revolución Industrial latía con vapor. La máquina de vapor mejorada de James Watt, perfeccionada en la década de 1770, dio a la humanidad una fuente de energía que no dependía del viento, el agua ni el músculo, y funcionaba con carbón, que Gran Bretaña poseía en abundancia. Las fábricas podían construirse ahora en cualquier lugar, funcionando día y noche, y su producción se disparó.\n\nEl hijo más espectacular del vapor fue el ferrocarril. Cuando el ferrocarril de Liverpool a Mánchester se inauguró en 1830, personas que jamás habían viajado más rápido que un caballo al galope se vieron de pronto lanzadas por el país a una velocidad inaudita. Los ferrocarriles acortaron las distancias, llevaron carbón y algodón a los puertos y cosieron las naciones. También crearon el sentido moderno del tiempo: para evitar choques de trenes, Gran Bretaña impuso una hora estándar única, poniendo fin al mosaico de relojes locales que había regido la vida humana durante milenios." },
    ru: { heading: "Пар, уголь и век железных дорог",
      body: "Сердце промышленной революции билось паром. Усовершенствованная паровая машина Джеймса Уатта, доведённая до совершенства в 1770-х годах, дала человечеству источник силы, не зависящий от ветра, воды или мышц, — и работала она на угле, которого у Британии было в избытке. Фабрики теперь можно было строить где угодно, они работали день и ночь, и их выпуск взрывообразно вырос.\n\nСамым впечатляющим детищем пара стала железная дорога. Когда в 1830 году открылась дорога Ливерпуль — Манчестер, люди, никогда не ездившие быстрее скачущей лошади, вдруг понеслись через страну с неслыханной скоростью. Железные дороги сократили расстояния, повезли уголь и хлопок к портам и сшили нации воедино. Они же создали современное чувство времени: чтобы поезда не сталкивались, Британия ввела единое стандартное время, покончив с лоскутным одеялом местных часов, правивших человеческой жизнью тысячелетиями." },
    mk: { heading: "Пареа, јаглен и ерата на железницата",
      body: "Срцето на Индустриската револуција чукаше со пареа. Подобрената парна машина на Џејмс Ват, усовршена во 1770-тите, ѝ даде на човештвото извор на моќ што не зависеше од ветар, вода или мускул — а работеше на јаглен, што Британија го поседуваше во изобилство. Фабриките сега можеа да се градат каде било, работејќи дење и ноќе, и нивното производство експлодира.\n\nНајдраматичното чедо на пареата беше железницата. Кога железницата Ливерпул–Манчестер се отвори во 1830 година, луѓето што никогаш не патувале побрзо од коњ во галоп одеднаш беа фрлени низ земјата со нечуена брзина. Железниците ги збија растојанијата, носеа јаглен и памук до пристаништата и ги сошија нациите. Исто така го создадоа модерното чувство за време: за да не се судираат возовите, Британија наметна единствено стандардно време, ставајќи крај на шаренилото локални часовници што управувале со човечкиот живот со милениуми." },
    de: { heading: "Dampf, Kohle und das Zeitalter der Eisenbahn",
      body: "Das Herz der Industriellen Revolution schlug mit Dampf. James Watts verbesserte Dampfmaschine, in den 1770er Jahren vervollkommnet, gab der Menschheit eine Kraftquelle, die nicht von Wind, Wasser oder Muskeln abhing — und sie lief mit Kohle, die Britannien im Überfluss besaß. Fabriken konnten nun überall gebaut werden, liefen Tag und Nacht, und ihr Ausstoß explodierte.\n\nDas dramatischste Kind des Dampfes war die Eisenbahn. Als 1830 die Bahn zwischen Liverpool und Manchester eröffnet wurde, wurden Menschen, die nie schneller als ein galoppierendes Pferd gereist waren, plötzlich mit unerhörter Geschwindigkeit durchs Land geschleudert. Eisenbahnen ließen Entfernungen schrumpfen, brachten Kohle und Baumwolle zu den Häfen und nähten Nationen zusammen. Sie schufen auch das moderne Zeitgefühl: um Zusammenstöße zu verhindern, führte Britannien eine einheitliche Standardzeit ein und beendete das Flickwerk lokaler Uhren, das das menschliche Leben Jahrtausende lang bestimmt hatte." },
    fr: { heading: "Vapeur, charbon et l'âge du chemin de fer",
      body: "Le cœur de la révolution industrielle battait à la vapeur. La machine à vapeur améliorée de James Watt, perfectionnée dans les années 1770, donna à l'humanité une source d'énergie indépendante du vent, de l'eau ou du muscle — et elle fonctionnait au charbon, que la Grande-Bretagne possédait en abondance. Les usines pouvaient désormais se bâtir n'importe où, tournant jour et nuit, et leur production explosa.\n\nL'enfant le plus spectaculaire de la vapeur fut le chemin de fer. Quand la ligne Liverpool-Manchester ouvrit en 1830, des gens qui n'avaient jamais voyagé plus vite qu'un cheval au galop furent soudain projetés à travers le pays à une vitesse inouïe. Les chemins de fer réduisirent les distances, portèrent charbon et coton vers les ports et cousirent les nations. Ils créèrent aussi le sens moderne du temps : pour éviter les collisions de trains, la Grande-Bretagne imposa une heure standard unique, mettant fin à la mosaïque d'horloges locales qui avait réglé la vie humaine pendant des millénaires." },
  },
  'modern-02': {
    en: { heading: "The Home Front and Total War",
      body: "The World Wars were 'total wars' — they consumed not just armies but entire societies. Victory depended as much on factories, farms, and morale as on the front line. Governments took command of their economies, rationing food, directing industry, and pouring out propaganda. The line between soldier and civilian blurred as cities themselves became targets of bombing.\n\nThe demands of total war reshaped society in lasting ways. With men at the front, millions of women entered factories, offices, and fields, doing work long thought beyond them — and afterward, the argument that they should not vote or hold office grew impossible to sustain. War accelerated technology too, from aircraft and radio to antibiotics and, ultimately, the atomic bomb. The world that emerged in 1945 was more industrial, more centralized, and more transformed by the state than any that had gone before." },
    es: { heading: "El frente interno y la guerra total",
      body: "Las Guerras Mundiales fueron 'guerras totales': consumieron no solo a los ejércitos, sino a sociedades enteras. La victoria dependía tanto de las fábricas, las granjas y la moral como del frente. Los gobiernos tomaron el mando de sus economías, racionando alimentos, dirigiendo la industria y volcando propaganda. La línea entre soldado y civil se difuminó cuando las propias ciudades se volvieron blanco de los bombardeos.\n\nLas exigencias de la guerra total remodelaron la sociedad de forma duradera. Con los hombres en el frente, millones de mujeres entraron en fábricas, oficinas y campos, haciendo trabajos que durante mucho tiempo se creyeron fuera de su alcance; y después, el argumento de que no debían votar ni ocupar cargos se volvió insostenible. La guerra también aceleró la tecnología, desde los aviones y la radio hasta los antibióticos y, finalmente, la bomba atómica. El mundo que surgió en 1945 era más industrial, más centralizado y más transformado por el Estado que ninguno anterior." },
    ru: { heading: "Тыл и тотальная война",
      body: "Мировые войны были «тотальными» — они поглощали не только армии, но и целые общества. Победа зависела от заводов, ферм и боевого духа не меньше, чем от линии фронта. Правительства взяли экономику под контроль, вводя карточки на продовольствие, направляя промышленность и обрушивая потоки пропаганды. Грань между солдатом и мирным жителем стёрлась, когда сами города стали целями бомбардировок.\n\nТребования тотальной войны надолго преобразили общество. Пока мужчины были на фронте, миллионы женщин пришли на заводы, в конторы и на поля, выполняя работу, которую долго считали им не под силу, — и после этого доводы, что им нельзя голосовать или занимать должности, стало невозможно отстаивать. Война ускорила и технику — от самолётов и радио до антибиотиков и, в конце концов, атомной бомбы. Мир, возникший в 1945 году, был более промышленным, более централизованным и сильнее преображённым государством, чем любой прежде." },
    mk: { heading: "Домашниот фронт и тоталната војна",
      body: "Светските војни беа „тотални војни“ — гутаа не само војски туку цели општества. Победата зависеше колку од фабриките, фармите и моралот, толку и од фронтот. Владите ги презедоа своите економии, воведувајќи следување на храна, насочувајќи ја индустријата и излевајќи пропаганда. Границата меѓу војник и цивил се замати кога самите градови станаа цел на бомбардирања.\n\nБарањата на тоталната војна го преобликуваа општеството на траен начин. Со мажите на фронтот, милиони жени влегоа во фабриките, канцелариите и полињата, вршејќи работа долго сметана за над нивните сили — а потоа, аргументот дека не треба да гласаат или да заземаат функции стана неодржлив. Војната ја забрза и технологијата, од авиони и радио до антибиотици и, конечно, атомската бомба. Светот што се појави во 1945 година беше поиндустриски, поцентрализиран и повеќе преобразен од државата отколку кој било претходно." },
    de: { heading: "Die Heimatfront und der totale Krieg",
      body: "Die Weltkriege waren 'totale Kriege' — sie verschlangen nicht nur Heere, sondern ganze Gesellschaften. Der Sieg hing ebenso von Fabriken, Höfen und Moral ab wie von der Front. Die Regierungen übernahmen das Kommando über ihre Wirtschaft, rationierten Lebensmittel, lenkten die Industrie und ergossen Propaganda. Die Grenze zwischen Soldat und Zivilist verwischte, als die Städte selbst zum Ziel von Bombenangriffen wurden.\n\nDie Anforderungen des totalen Krieges formten die Gesellschaft dauerhaft um. Während die Männer an der Front waren, traten Millionen Frauen in Fabriken, Büros und Felder ein und verrichteten Arbeit, die man ihnen lange nicht zugetraut hatte — und danach ließ sich das Argument, sie sollten nicht wählen oder Ämter bekleiden, nicht mehr halten. Der Krieg beschleunigte auch die Technik, von Flugzeug und Funk bis zu Antibiotika und schließlich der Atombombe. Die Welt, die 1945 hervorging, war industrieller, zentralisierter und stärker vom Staat verwandelt als jede zuvor." },
    fr: { heading: "Le front intérieur et la guerre totale",
      body: "Les guerres mondiales furent des 'guerres totales' — elles dévorèrent non seulement les armées, mais des sociétés entières. La victoire dépendait autant des usines, des fermes et du moral que de la ligne de front. Les gouvernements prirent le commandement de leur économie, rationnant les vivres, dirigeant l'industrie et déversant la propagande. La ligne entre soldat et civil s'estompa lorsque les villes elles-mêmes devinrent la cible des bombardements.\n\nLes exigences de la guerre totale remodelèrent durablement la société. Les hommes au front, des millions de femmes entrèrent dans les usines, les bureaux et les champs, accomplissant un travail longtemps jugé au-dessus d'elles — et ensuite, l'argument selon lequel elles ne devaient ni voter ni exercer de charge devint intenable. La guerre accéléra aussi la technique, de l'avion et la radio aux antibiotiques et, finalement, à la bombe atomique. Le monde qui émergea en 1945 était plus industriel, plus centralisé et plus transformé par l'État qu'aucun auparavant." },
  },
  'modern-03': {
    en: { heading: "The Nuclear Balance of Terror",
      body: "The Cold War never became a direct war between the United States and the Soviet Union for one overriding reason: nuclear weapons. After the Soviets tested their own bomb in 1949, both sides built arsenals capable of destroying each other many times over. Strategists called the resulting standoff 'mutually assured destruction' — the grim knowledge that any full attack would mean the attacker's own annihilation.\n\nThis balance of terror made the whole world hostage to a handful of decisions. In October 1962 the Cuban Missile Crisis brought humanity within days of nuclear war before the two superpowers stepped back from the brink. The fear was constant enough that schoolchildren practiced hiding under desks. Yet the sheer horror of the weapons may also have kept the peace — pushing the rivalry into proxy wars, propaganda, and a race to the Moon rather than a final, unthinkable battle." },
    es: { heading: "El equilibrio nuclear del terror",
      body: "La Guerra Fría nunca se convirtió en una guerra directa entre Estados Unidos y la Unión Soviética por una razón primordial: las armas nucleares. Después de que los soviéticos probaran su propia bomba en 1949, ambos bandos construyeron arsenales capaces de destruirse mutuamente muchas veces. Los estrategas llamaron a ese punto muerto 'destrucción mutua asegurada': la sombría certeza de que cualquier ataque total significaría la aniquilación del propio atacante.\n\nEste equilibrio del terror mantuvo al mundo entero como rehén de un puñado de decisiones. En octubre de 1962 la crisis de los misiles de Cuba llevó a la humanidad a pocos días de la guerra nuclear antes de que las dos superpotencias se apartaran del abismo. El miedo era tan constante que los escolares practicaban esconderse bajo los pupitres. Sin embargo, el puro horror de las armas quizá también mantuvo la paz, empujando la rivalidad hacia guerras indirectas, propaganda y una carrera a la Luna en lugar de una batalla final e impensable." },
    ru: { heading: "Ядерное равновесие страха",
      body: "Холодная война так и не переросла в прямую войну между США и Советским Союзом по одной главенствующей причине — ядерному оружию. После того как в 1949 году Советы испытали собственную бомбу, обе стороны создали арсеналы, способные многократно уничтожить друг друга. Стратеги назвали возникшее противостояние «гарантированным взаимным уничтожением» — мрачным сознанием того, что любое полномасштабное нападение будет означать гибель самого нападающего.\n\nЭто равновесие страха сделало весь мир заложником горстки решений. В октябре 1962 года Карибский кризис привёл человечество к порогу ядерной войны, прежде чем две сверхдержавы отступили от края пропасти. Страх был столь постоянным, что школьники отрабатывали, как прятаться под партами. И всё же сам ужас этого оружия, возможно, и сохранил мир — направив соперничество в опосредованные войны, пропаганду и гонку к Луне вместо последней, немыслимой битвы." },
    mk: { heading: "Нуклеарната рамнотежа на стравот",
      body: "Студената војна никогаш не прерасна во директна војна меѓу Соединетите Држави и Советскиот Сојуз поради една надредена причина: нуклеарното оружје. Откако Советите ја тестираа сопствената бомба во 1949 година, двете страни изградија арсенали способни да се уништат меѓусебно многупати. Стратезите го нарекоа настанатиот ќор-сокак „загарантирано заемно уништување“ — мрачното сознание дека секој целосен напад би значел уништување на самиот напаѓач.\n\nОваа рамнотежа на стравот го држеше целиот свет заложник на неколку одлуки. Во октомври 1962 година Кубанската ракетна криза го доведе човештвото на неколку дена од нуклеарна војна пред двете суперсили да отстапат од работ. Стравот беше толку постојан што учениците вежбаа да се кријат под клупите. Сепак, самиот ужас на ова оружје можеби и го зачува мирот — туркајќи го ривалството кон посреднички војни, пропаганда и трка до Месечината наместо кон последна, незамислива битка." },
    de: { heading: "Das nukleare Gleichgewicht des Schreckens",
      body: "Der Kalte Krieg wurde aus einem überragenden Grund nie ein direkter Krieg zwischen den Vereinigten Staaten und der Sowjetunion: den Kernwaffen. Nachdem die Sowjets 1949 ihre eigene Bombe getestet hatten, bauten beide Seiten Arsenale, die einander viele Male zerstören konnten. Strategen nannten das entstandene Patt 'gesicherte gegenseitige Zerstörung' — das düstere Wissen, dass jeder umfassende Angriff die eigene Vernichtung des Angreifers bedeuten würde.\n\nDieses Gleichgewicht des Schreckens machte die ganze Welt zur Geisel einer Handvoll Entscheidungen. Im Oktober 1962 brachte die Kubakrise die Menschheit bis auf wenige Tage an einen Atomkrieg heran, ehe die beiden Supermächte vom Abgrund zurücktraten. Die Furcht war so beständig, dass Schulkinder übten, sich unter Pulten zu verstecken. Doch der schiere Schrecken der Waffen mag auch den Frieden bewahrt haben — er drängte die Rivalität in Stellvertreterkriege, Propaganda und ein Wettrennen zum Mond statt in eine letzte, undenkbare Schlacht." },
    fr: { heading: "L'équilibre nucléaire de la terreur",
      body: "La guerre froide ne devint jamais une guerre directe entre les États-Unis et l'Union soviétique pour une raison primordiale : les armes nucléaires. Après que les Soviétiques eurent testé leur propre bombe en 1949, les deux camps bâtirent des arsenaux capables de s'anéantir mutuellement de nombreuses fois. Les stratèges nommèrent l'impasse qui en résulta 'destruction mutuelle assurée' — la sombre certitude que toute attaque totale signifierait l'anéantissement de l'attaquant lui-même.\n\nCet équilibre de la terreur tint le monde entier en otage d'une poignée de décisions. En octobre 1962, la crise des missiles de Cuba amena l'humanité à quelques jours d'une guerre nucléaire avant que les deux superpuissances ne reculent au bord du gouffre. La peur était assez constante pour que les écoliers s'exercent à se cacher sous les pupitres. Pourtant, l'horreur même de ces armes a peut-être aussi préservé la paix — poussant la rivalité vers des guerres par procuration, la propagande et une course à la Lune plutôt qu'une bataille finale et impensable." },
  },
  'modern-04': {
    en: { heading: "The Digital Revolution",
      body: "If steam powered the first industrial age, information powers ours. In the second half of the twentieth century, the invention of the transistor and then the microchip let engineers pack ever more computing power into ever smaller spaces — a trend so reliable it was named Moore's Law. Room-sized machines shrank into desktop computers, then into phones that fit in a pocket yet outperform the computers that guided the Apollo astronauts to the Moon.\n\nThe true earthquake came when these machines were linked. The Internet, opened to the public in the 1990s, and the World Wide Web wove the planet into a single network of instant communication. Knowledge, commerce, and conversation that once moved at the speed of ships and letters now crossed the world in seconds. This digital revolution reshaped work, politics, and daily life as profoundly as the steam engine once did — and it is still unfolding." },
    es: { heading: "La revolución digital",
      body: "Si el vapor impulsó la primera era industrial, la información impulsa la nuestra. En la segunda mitad del siglo XX, la invención del transistor y luego del microchip permitió a los ingenieros concentrar cada vez más potencia de cálculo en espacios cada vez menores, una tendencia tan fiable que se llamó ley de Moore. Máquinas del tamaño de una habitación se encogieron hasta ser ordenadores de escritorio y luego teléfonos que caben en un bolsillo pero superan a los ordenadores que guiaron a los astronautas del Apolo a la Luna.\n\nEl verdadero terremoto llegó cuando estas máquinas se conectaron. Internet, abierto al público en la década de 1990, y la World Wide Web tejieron el planeta en una única red de comunicación instantánea. El conocimiento, el comercio y la conversación que antes viajaban a la velocidad de los barcos y las cartas cruzaban ahora el mundo en segundos. Esta revolución digital remodeló el trabajo, la política y la vida cotidiana tan profundamente como lo hizo en su día la máquina de vapor, y aún se está desplegando." },
    ru: { heading: "Цифровая революция",
      body: "Если пар двигал первую индустриальную эпоху, то нашей движет информация. Во второй половине XX века изобретение транзистора, а затем микрочипа позволило инженерам вмещать всё больше вычислительной мощности во всё меньшее пространство — тенденция настолько устойчивая, что её назвали законом Мура. Машины размером с комнату сжались до настольных компьютеров, а затем до телефонов, которые помещаются в карман, но превосходят компьютеры, приведшие астронавтов «Аполлона» к Луне.\n\nНастоящее землетрясение случилось, когда эти машины связали воедино. Интернет, открытый для публики в 1990-х годах, и Всемирная паутина сплели планету в единую сеть мгновенной связи. Знания, торговля и разговор, некогда двигавшиеся со скоростью кораблей и писем, теперь пересекали мир за секунды. Эта цифровая революция преобразила труд, политику и повседневную жизнь так же глубоко, как когда-то паровая машина, — и она всё ещё разворачивается." },
    mk: { heading: "Дигиталната револуција",
      body: "Ако пареата ја движеше првата индустриска ера, информацијата ја движи нашата. Во втората половина на дваесеттиот век, пронајдокот на транзисторот, а потоа и на микрочипот, им овозможи на инженерите да збијат сè повеќе пресметковна моќ во сè помал простор — тренд толку сигурен што беше наречен Муров закон. Машините големи колку соба се стумнаа во десктоп компјутери, а потоа во телефони што собираат во џеб, а сепак ги надминуваат компјутерите што ги водеа астронаутите на Аполо до Месечината.\n\nВистинскиот земјотрес дојде кога овие машини беа поврзани. Интернетот, отворен за јавноста во 1990-тите, и Светската мрежа ја исплетоа планетата во единствена мрежа на моментална комуникација. Знаењето, трговијата и разговорот што некогаш се движеа со брзината на бродови и писма, сега го преминуваа светот за секунди. Оваа дигитална револуција ги преобликуваше работата, политиката и секојдневниот живот исто толку длабоко колку што некогаш го стори парната машина — и сè уште се одвива." },
    de: { heading: "Die digitale Revolution",
      body: "Trieb der Dampf das erste Industriezeitalter an, so treibt die Information das unsere. In der zweiten Hälfte des zwanzigsten Jahrhunderts erlaubten die Erfindung des Transistors und dann des Mikrochips den Ingenieuren, immer mehr Rechenkraft auf immer kleinerem Raum zu bündeln — ein Trend, so verlässlich, dass er das Mooresche Gesetz genannt wurde. Zimmergroße Maschinen schrumpften zu Tischcomputern und dann zu Telefonen, die in eine Tasche passen und doch die Computer übertreffen, die die Apollo-Astronauten zum Mond lenkten.\n\nDas eigentliche Erdbeben kam, als diese Maschinen verbunden wurden. Das Internet, in den 1990er Jahren der Öffentlichkeit geöffnet, und das World Wide Web verwoben den Planeten zu einem einzigen Netz sofortiger Kommunikation. Wissen, Handel und Gespräch, die sich einst mit der Geschwindigkeit von Schiffen und Briefen bewegten, überquerten nun die Welt in Sekunden. Diese digitale Revolution formte Arbeit, Politik und Alltag ebenso tiefgreifend um wie einst die Dampfmaschine — und sie entfaltet sich noch immer." },
    fr: { heading: "La révolution numérique",
      body: "Si la vapeur anima le premier âge industriel, l'information anime le nôtre. Dans la seconde moitié du XXe siècle, l'invention du transistor puis du microprocesseur permit aux ingénieurs de concentrer toujours plus de puissance de calcul dans un espace toujours plus petit — une tendance si fiable qu'on la nomma loi de Moore. Des machines grandes comme une pièce se réduisirent en ordinateurs de bureau, puis en téléphones tenant dans une poche mais surpassant les ordinateurs qui guidèrent les astronautes d'Apollo jusqu'à la Lune.\n\nLe véritable séisme survint lorsque ces machines furent reliées. Internet, ouvert au public dans les années 1990, et le World Wide Web tissèrent la planète en un unique réseau de communication instantanée. Le savoir, le commerce et la conversation qui voyageaient jadis à la vitesse des navires et des lettres traversaient désormais le monde en quelques secondes. Cette révolution numérique remodela le travail, la politique et la vie quotidienne aussi profondément que le fit jadis la machine à vapeur — et elle se déploie encore." },
  },
  'modern-05': {
    en: { heading: "The Berlin Conference and the Partition of Africa",
      body: "In the winter of 1884–85, the powers of Europe gathered at a conference in Berlin to carve up an entire continent — and not a single African was invited. Over a map of Africa, diplomats drew borders through kingdoms, peoples, and languages they neither knew nor cared about, setting rules for a 'scramble' in which European empires seized almost the whole continent within a generation.\n\nThe consequences were catastrophic and long-lasting. New technologies — the machine gun, quinine against malaria, the steamship and railway — let small European forces conquer vast territories. In the Congo, the personal colony of Belgium's King Leopold II, forced rubber collection killed millions. The arbitrary borders drawn in Berlin ignored the realities on the ground, and when African nations won independence in the twentieth century, they inherited those same lines — a source of conflict that endures to this day." },
    es: { heading: "La Conferencia de Berlín y el reparto de África",
      body: "En el invierno de 1884-85, las potencias de Europa se reunieron en una conferencia en Berlín para repartirse un continente entero, y no se invitó a un solo africano. Sobre un mapa de África, los diplomáticos trazaron fronteras a través de reinos, pueblos y lenguas que ni conocían ni les importaban, fijando las reglas de un 'reparto' en el que los imperios europeos se apoderaron de casi todo el continente en una generación.\n\nLas consecuencias fueron catastróficas y duraderas. Nuevas tecnologías —la ametralladora, la quinina contra la malaria, el barco de vapor y el ferrocarril— permitieron a pequeñas fuerzas europeas conquistar vastos territorios. En el Congo, la colonia personal del rey Leopoldo II de Bélgica, la recolección forzada de caucho mató a millones. Las fronteras arbitrarias trazadas en Berlín ignoraron las realidades sobre el terreno, y cuando las naciones africanas lograron la independencia en el siglo XX, heredaron esas mismas líneas: una fuente de conflicto que perdura hasta hoy." },
    ru: { heading: "Берлинская конференция и раздел Африки",
      body: "Зимой 1884–85 годов державы Европы собрались на конференцию в Берлине, чтобы поделить целый континент, — и ни один африканец не был приглашён. Над картой Африки дипломаты проводили границы сквозь царства, народы и языки, которых они не знали и до которых им не было дела, устанавливая правила «гонки», в которой европейские империи захватили почти весь континент за одно поколение.\n\nПоследствия были катастрофическими и долгими. Новые технологии — пулемёт, хинин против малярии, пароход и железная дорога — позволили малым европейским силам покорять огромные территории. В Конго, личной колонии бельгийского короля Леопольда II, принудительный сбор каучука убил миллионы. Произвольные границы, проведённые в Берлине, игнорировали реальность на местах, и когда африканские нации обрели независимость в XX веке, они унаследовали те же самые линии — источник конфликтов, не иссякший и поныне." },
    mk: { heading: "Берлинската конференција и поделбата на Африка",
      body: "Во зимата 1884–85 година, силите на Европа се собраа на конференција во Берлин за да поделат цел континент — а ниту еден Африканец не беше поканет. Над картата на Африка, дипломатите повлекуваа граници низ кралства, народи и јазици што ниту ги знаеја ниту им беше грижа за нив, поставувајќи ги правилата на едно „грабење“ во кое европските империи го зазедоа речиси целиот континент за една генерација.\n\nПоследиците беа катастрофални и долготрајни. Новите технологии — митралезот, кининот против маларија, парниот брод и железницата — им овозможија на малите европски сили да освојат огромни територии. Во Конго, личната колонија на белгискиот крал Леополд II, присилното собирање каучук усмрти милиони. Произволните граници повлечени во Берлин ги игнорираа реалностите на терен, и кога африканските нации извојуваа независност во дваесеттиот век, ги наследија истите тие линии — извор на конфликт што трае до денес." },
    de: { heading: "Die Berliner Konferenz und die Aufteilung Afrikas",
      body: "Im Winter 1884–85 versammelten sich die Mächte Europas zu einer Konferenz in Berlin, um einen ganzen Kontinent aufzuteilen — und kein einziger Afrikaner war eingeladen. Über einer Karte Afrikas zogen Diplomaten Grenzen durch Königreiche, Völker und Sprachen, die sie weder kannten noch kümmerten, und setzten die Regeln für ein 'Wettrennen', in dem die europäischen Reiche binnen einer Generation fast den ganzen Kontinent an sich rissen.\n\nDie Folgen waren katastrophal und langlebig. Neue Techniken — das Maschinengewehr, Chinin gegen Malaria, Dampfschiff und Eisenbahn — erlaubten kleinen europäischen Truppen, weite Gebiete zu erobern. Im Kongo, der Privatkolonie des belgischen Königs Leopold II., tötete die erzwungene Kautschukgewinnung Millionen. Die willkürlichen, in Berlin gezogenen Grenzen missachteten die Wirklichkeit vor Ort, und als die afrikanischen Nationen im zwanzigsten Jahrhundert die Unabhängigkeit errangen, erbten sie eben diese Linien — eine Quelle des Konflikts, die bis heute fortdauert." },
    fr: { heading: "La conférence de Berlin et le partage de l'Afrique",
      body: "Durant l'hiver 1884-85, les puissances de l'Europe se réunirent à une conférence à Berlin pour se partager un continent entier — et pas un seul Africain ne fut invité. Sur une carte de l'Afrique, les diplomates tracèrent des frontières à travers des royaumes, des peuples et des langues qu'ils ne connaissaient ni ne se souciaient de connaître, fixant les règles d'une 'ruée' où les empires européens s'emparèrent de presque tout le continent en une génération.\n\nLes conséquences furent catastrophiques et durables. De nouvelles techniques — la mitrailleuse, la quinine contre le paludisme, le bateau à vapeur et le chemin de fer — permirent à de petites forces européennes de conquérir de vastes territoires. Au Congo, colonie personnelle du roi Léopold II de Belgique, la récolte forcée du caoutchouc tua des millions de personnes. Les frontières arbitraires tracées à Berlin ignorèrent les réalités du terrain, et quand les nations africaines conquirent leur indépendance au XXe siècle, elles héritèrent de ces mêmes lignes — une source de conflit qui perdure jusqu'à aujourd'hui." },
  },
  'modern-06': {
    en: { heading: "Sarajevo Besieged",
      body: "As Yugoslavia broke apart in the 1990s, the city of Sarajevo became the symbol of the wars' cruelty. For nearly four years — the longest siege of a capital in modern history — Bosnian Serb forces in the surrounding hills bombarded and sniped at a city that had long been a proud model of coexistence, where Muslims, Croats, Serbs, and Jews had lived intertwined for centuries.\n\nCitizens queued for water under sniper fire and crossed streets renamed 'Sniper Alley' at a run. Yet Sarajevo did not surrender its spirit: newspapers still printed, a string quartet played in the ruins, and residents improvised to survive. The siege, and atrocities such as the 1995 Srebrenica massacre, shocked the world and eventually drew in international intervention. They stand as a warning of how quickly a diverse, modern society can be torn apart when nationalism is turned into a weapon." },
    es: { heading: "Sarajevo sitiada",
      body: "Cuando Yugoslavia se desmembró en la década de 1990, la ciudad de Sarajevo se convirtió en el símbolo de la crueldad de las guerras. Durante casi cuatro años —el asedio más largo de una capital en la historia moderna—, las fuerzas serbobosnias en las colinas circundantes bombardearon y dispararon contra una ciudad que había sido durante mucho tiempo un orgulloso modelo de convivencia, donde musulmanes, croatas, serbios y judíos habían vivido entrelazados durante siglos.\n\nLos ciudadanos hacían cola para conseguir agua bajo el fuego de los francotiradores y cruzaban corriendo calles rebautizadas como 'la avenida de los francotiradores'. Sin embargo, Sarajevo no rindió su espíritu: los periódicos seguían imprimiéndose, un cuarteto de cuerda tocaba entre las ruinas y los vecinos improvisaban para sobrevivir. El asedio, y atrocidades como la masacre de Srebrenica de 1995, conmocionaron al mundo y acabaron por provocar la intervención internacional. Son una advertencia de la rapidez con que una sociedad diversa y moderna puede desgarrarse cuando el nacionalismo se convierte en arma." },
    ru: { heading: "Осада Сараева",
      body: "Когда в 1990-х годах Югославия распадалась, город Сараево стал символом жестокости этих войн. Почти четыре года — самая долгая осада столицы в новейшей истории — боснийско-сербские силы на окрестных холмах обстреливали из орудий и снайперских винтовок город, который долго был гордым образцом сосуществования, где мусульмане, хорваты, сербы и евреи веками жили переплетённо.\n\nЖители стояли в очередях за водой под снайперским огнём и перебегали улицы, прозванные «аллеей снайперов». Но Сараево не сдало свой дух: газеты по-прежнему печатались, струнный квартет играл среди руин, а горожане изобретали способы выжить. Осада и такие злодеяния, как резня в Сребренице в 1995 году, потрясли мир и в конце концов вызвали международное вмешательство. Они стоят как предостережение о том, как быстро разнообразное, современное общество может быть разорвано, когда национализм превращают в оружие." },
    mk: { heading: "Опколеното Сараево",
      body: "Како што Југославија се распаѓаше во 1990-тите, градот Сараево стана симбол на суровоста на војните. Речиси четири години — најдолгата опсада на престолнина во модерната историја — босанско-српските сили на околните ридови бомбардираа и снајпераа град што долго беше горд модел на сожителство, каде што муслиманите, Хрватите, Србите и Евреите живееле испреплетено со векови.\n\nГраѓаните чекаа во редици за вода под снајперски оган и трчаа преку улиците преименувани во „Снајперска алеја“. Сепак, Сараево не го предаде својот дух: весниците сè уште се печатеа, гудачки квартет свиреше меѓу урнатините, а жителите импровизираа за да преживеат. Опсадата, и злосторства како масакрот во Сребреница во 1995 година, го шокираа светот и на крајот повлекоа меѓународна интервенција. Тие стојат како предупредување колку брзо едно разнолико, модерно општество може да биде раскинато кога национализмот ќе се претвори во оружје." },
    de: { heading: "Das belagerte Sarajevo",
      body: "Als Jugoslawien in den 1990er Jahren zerfiel, wurde die Stadt Sarajevo zum Sinnbild der Grausamkeit dieser Kriege. Fast vier Jahre lang — die längste Belagerung einer Hauptstadt in der neueren Geschichte — beschossen bosnisch-serbische Kräfte von den umliegenden Hügeln eine Stadt, die lange ein stolzes Vorbild des Zusammenlebens gewesen war, wo Muslime, Kroaten, Serben und Juden über Jahrhunderte eng verflochten gelebt hatten.\n\nDie Bürger standen unter Scharfschützenfeuer nach Wasser an und überquerten im Laufschritt Straßen, die man 'Sniper Alley' nannte. Doch Sarajevo gab seinen Geist nicht auf: Zeitungen erschienen weiter, ein Streichquartett spielte in den Ruinen, und die Bewohner improvisierten, um zu überleben. Die Belagerung und Gräueltaten wie das Massaker von Srebrenica 1995 erschütterten die Welt und zogen schließlich eine internationale Intervention nach sich. Sie stehen als Warnung, wie rasch eine vielfältige, moderne Gesellschaft zerrissen werden kann, wenn Nationalismus zur Waffe gemacht wird." },
    fr: { heading: "Sarajevo assiégée",
      body: "Tandis que la Yougoslavie se disloquait dans les années 1990, la ville de Sarajevo devint le symbole de la cruauté de ces guerres. Pendant près de quatre ans — le plus long siège d'une capitale de l'histoire moderne — les forces serbes de Bosnie, sur les collines environnantes, bombardèrent et tirèrent au fusil sur une ville longtemps fière modèle de coexistence, où musulmans, Croates, Serbes et juifs avaient vécu entremêlés pendant des siècles.\n\nLes habitants faisaient la queue pour l'eau sous le feu des tireurs embusqués et traversaient au pas de course des rues rebaptisées 'l'allée des snipers'. Pourtant, Sarajevo ne rendit pas son âme : les journaux paraissaient encore, un quatuor à cordes jouait dans les ruines, et les habitants improvisaient pour survivre. Le siège, et des atrocités comme le massacre de Srebrenica en 1995, choquèrent le monde et finirent par susciter une intervention internationale. Ils demeurent un avertissement : combien vite une société diverse et moderne peut être déchirée quand on fait du nationalisme une arme." },
  },
  'modern-07': {
    en: { heading: "Nations and the Redrawing of the Balkans",
      body: "The Macedonian Struggle unfolded at a moment when the crumbling of the Ottoman Empire in Europe unleashed a fierce contest over its lands. Across the Balkans in the nineteenth and early twentieth centuries, the modern idea of the nation — a people bound by language, faith, and history who deserved a state of their own — collided with a reality of astonishingly mixed populations, where villages of different tongues and churches stood side by side.\n\nRival national movements, backed by neighboring states, competed for the loyalty of the same populations through schools, churches, propaganda, and armed bands. The Balkan Wars of 1912–13 finally expelled the Ottomans from most of Europe but left the region's peoples divided by new borders. This tangled struggle over identity and territory helped ignite the First World War — and shows how the powerful, double-edged idea of nationhood remade the modern map." },
    es: { heading: "Naciones y el nuevo trazado de los Balcanes",
      body: "La Lucha Macedonia se desarrolló en un momento en que el desmoronamiento del Imperio otomano en Europa desató una feroz disputa por sus tierras. Por los Balcanes, en el siglo XIX y comienzos del XX, la idea moderna de nación —un pueblo unido por la lengua, la fe y la historia que merecía un Estado propio— chocó con una realidad de poblaciones asombrosamente mezcladas, donde aldeas de distintas lenguas e iglesias se alzaban unas junto a otras.\n\nMovimientos nacionales rivales, respaldados por Estados vecinos, competían por la lealtad de las mismas poblaciones mediante escuelas, iglesias, propaganda y bandas armadas. Las Guerras Balcánicas de 1912-13 expulsaron por fin a los otomanos de casi toda Europa, pero dejaron a los pueblos de la región divididos por nuevas fronteras. Esta enredada lucha por la identidad y el territorio ayudó a encender la Primera Guerra Mundial, y muestra cómo la poderosa idea de nación, de doble filo, rehízo el mapa moderno." },
    ru: { heading: "Нации и передел Балкан",
      body: "Македонская борьба развернулась в тот момент, когда распад Османской империи в Европе развязал ожесточённое соперничество за её земли. По всем Балканам в XIX и начале XX века современная идея нации — народа, связанного языком, верой и историей и заслуживающего собственного государства, — столкнулась с реальностью поразительно смешанного населения, где деревни разных языков и церквей стояли бок о бок.\n\nСоперничающие национальные движения, поддержанные соседними государствами, боролись за верность одного и того же населения через школы, церкви, пропаганду и вооружённые отряды. Балканские войны 1912–13 годов наконец изгнали османов почти из всей Европы, но оставили народы региона разделёнными новыми границами. Эта запутанная борьба за самосознание и территорию помогла разжечь Первую мировую войну и показывает, как мощная, обоюдоострая идея нации перекроила современную карту." },
    mk: { heading: "Нациите и прекројувањето на Балканот",
      body: "Македонската борба се одвиваше во момент кога распаѓањето на Отоманската империја во Европа разгоре жестока борба за нејзините земји. Низ Балканот, во деветнаесеттиот и раниот дваесетти век, модерната идеја за нацијата — народ поврзан со јазик, вера и историја што заслужува своја држава — се судри со реалност на зачудувачки измешани населенија, каде што села со различни јазици и цркви стоеја едно до друго.\n\nРивалски национални движења, поддржани од соседните држави, се натпреваруваа за лојалноста на истите населенија преку училишта, цркви, пропаганда и вооружени чети. Балканските војни од 1912–13 година конечно ги истераа Отоманите од поголемиот дел на Европа, но ги оставија народите на регионот поделени со нови граници. Оваа заплеткана борба за идентитет и територија помогна да се запали Првата светска војна — и покажува како моќната, двосечна идеја за нацијата ја прекрои модерната карта." },
    de: { heading: "Nationen und die Neuvermessung des Balkans",
      body: "Der Makedonische Kampf entfaltete sich in einem Augenblick, als der Zerfall des Osmanischen Reiches in Europa einen erbitterten Wettstreit um seine Länder entfesselte. Auf dem ganzen Balkan prallte im neunzehnten und frühen zwanzigsten Jahrhundert die moderne Idee der Nation — ein durch Sprache, Glaube und Geschichte verbundenes Volk, das einen eigenen Staat verdiene — auf eine Wirklichkeit erstaunlich gemischter Bevölkerungen, wo Dörfer verschiedener Zungen und Kirchen dicht beieinander lagen.\n\nRivalisierende Nationalbewegungen, gestützt von Nachbarstaaten, warben durch Schulen, Kirchen, Propaganda und bewaffnete Banden um die Treue derselben Bevölkerung. Die Balkankriege von 1912–13 vertrieben schließlich die Osmanen aus fast ganz Europa, ließen aber die Völker der Region durch neue Grenzen geteilt zurück. Dieser verworrene Kampf um Identität und Gebiet trug dazu bei, den Ersten Weltkrieg zu entzünden — und zeigt, wie die mächtige, zweischneidige Idee der Nation die moderne Landkarte neu gestaltete." },
    fr: { heading: "Les nations et le redécoupage des Balkans",
      body: "La lutte macédonienne se déroula au moment où l'effritement de l'Empire ottoman en Europe déchaîna une âpre rivalité pour ses terres. Dans tous les Balkans, au XIXe et au début du XXe siècle, l'idée moderne de la nation — un peuple uni par la langue, la foi et l'histoire, méritant un État propre — se heurta à une réalité de populations étonnamment mêlées, où des villages de langues et d'églises différentes se dressaient côte à côte.\n\nDes mouvements nationaux rivaux, soutenus par les États voisins, se disputaient la loyauté des mêmes populations par les écoles, les églises, la propagande et des bandes armées. Les guerres balkaniques de 1912-13 chassèrent enfin les Ottomans de presque toute l'Europe, mais laissèrent les peuples de la région divisés par de nouvelles frontières. Cette lutte enchevêtrée autour de l'identité et du territoire contribua à embraser la Première Guerre mondiale — et montre comment la puissante idée, à double tranchant, de la nation refit la carte moderne." },
  },
  'modern-08': {
    en: { heading: "The Gulag and the Cost of Utopia",
      body: "The Soviet Union promised a workers' paradise, but building it under Stalin cost tens of millions of lives. To industrialize at breakneck speed and crush all opposition, the state created a vast network of forced-labor camps known as the Gulag. Millions — peasants who resisted collectivization, imagined 'enemies of the people,' and countless innocents — were worked, starved, and frozen in Siberian camps.\n\nThe terror reached its height in the purges of the late 1930s, when Stalin's secret police arrested, tortured, and shot huge numbers on invented charges, including many loyal Communists and army officers. Meanwhile the forced collectivization of farming triggered famines that killed millions more, especially in Ukraine. The Soviet century achieved real feats — mass literacy, industrial might, victory over Nazi Germany, the first satellite in orbit — but the human price of its utopian ambition stands as one of history's gravest warnings." },
    es: { heading: "El Gulag y el precio de la utopía",
      body: "La Unión Soviética prometía un paraíso de los trabajadores, pero construirlo bajo Stalin costó decenas de millones de vidas. Para industrializarse a un ritmo vertiginoso y aplastar toda oposición, el Estado creó una vasta red de campos de trabajos forzados conocida como el Gulag. Millones —campesinos que resistían la colectivización, imaginados 'enemigos del pueblo' e incontables inocentes— fueron explotados, hambreados y congelados en campos de Siberia.\n\nEl terror alcanzó su apogeo en las purgas de finales de la década de 1930, cuando la policía secreta de Stalin detuvo, torturó y fusiló a enormes cantidades de personas con cargos inventados, incluidos muchos comunistas leales y oficiales del ejército. Mientras tanto, la colectivización forzada de la agricultura desató hambrunas que mataron a millones más, sobre todo en Ucrania. El siglo soviético logró hazañas reales —alfabetización masiva, poderío industrial, la victoria sobre la Alemania nazi, el primer satélite en órbita—, pero el precio humano de su ambición utópica queda como una de las advertencias más graves de la historia." },
    ru: { heading: "ГУЛАГ и цена утопии",
      body: "Советский Союз обещал рай для трудящихся, но его строительство при Сталине стоило десятков миллионов жизней. Ради стремительной индустриализации и подавления всякого сопротивления государство создало обширную сеть лагерей принудительного труда, известную как ГУЛАГ. Миллионы — крестьяне, сопротивлявшиеся коллективизации, мнимые «враги народа» и бесчисленные невиновные — надрывались, голодали и замерзали в сибирских лагерях.\n\nТеррор достиг вершины в чистках конца 1930-х годов, когда тайная полиция Сталина арестовывала, пытала и расстреливала огромное число людей по вымышленным обвинениям, включая многих верных коммунистов и армейских командиров. Тем временем насильственная коллективизация сельского хозяйства вызвала голод, унёсший ещё миллионы жизней, особенно на Украине. Советский век достиг подлинных свершений — массовой грамотности, промышленной мощи, победы над нацистской Германией, первого спутника на орбите, — но человеческая цена его утопической мечты остаётся одним из тягчайших предостережений истории." },
    mk: { heading: "Гулагот и цената на утопијата",
      body: "Советскиот Сојуз ветуваше рај за работниците, но неговото градење под Сталин чинеше десетици милиони животи. За да се индустријализира со вртоглаво темпо и да го скрши секој отпор, државата создаде огромна мрежа логори за присилна работа позната како Гулаг. Милиони — селани што ѝ се спротивставија на колективизацијата, замислени „непријатели на народот“ и безброј невини — беа изнемоштувани, гладувани и смрзнувани во сибирските логори.\n\nТеророт го достигна својот врв во чистките во доцните 1930-ти, кога тајната полиција на Сталин апсеше, мачеше и стрелаше огромен број луѓе по измислени обвиненија, вклучувајќи многу верни комунисти и армиски офицери. Во меѓувреме, присилната колективизација на земјоделството предизвика гладови што усмртија уште милиони, особено во Украина. Советскиот век постигна вистински подвизи — масовна писменост, индустриска моќ, победа над нацистичка Германија, првиот сателит во орбита — но човечката цена на неговата утописка амбиција останува едно од најтешките предупредувања во историјата." },
    de: { heading: "Der Gulag und der Preis der Utopie",
      body: "Die Sowjetunion versprach ein Arbeiterparadies, doch es unter Stalin zu errichten kostete zig Millionen Menschenleben. Um in halsbrecherischem Tempo zu industrialisieren und jede Opposition zu zerschlagen, schuf der Staat ein riesiges Netz von Zwangsarbeitslagern, den Gulag. Millionen — Bauern, die sich der Kollektivierung widersetzten, eingebildete 'Volksfeinde' und zahllose Unschuldige — wurden in sibirischen Lagern zu Tode geschunden, ausgehungert und erfroren.\n\nDer Terror erreichte seinen Höhepunkt in den Säuberungen der späten 1930er Jahre, als Stalins Geheimpolizei riesige Zahlen von Menschen aufgrund erfundener Anklagen verhaftete, folterte und erschoss, darunter viele treue Kommunisten und Armeeoffiziere. Zugleich löste die erzwungene Kollektivierung der Landwirtschaft Hungersnöte aus, die weitere Millionen töteten, besonders in der Ukraine. Das sowjetische Jahrhundert vollbrachte echte Leistungen — Massenalphabetisierung, industrielle Macht, den Sieg über Nazideutschland, den ersten Satelliten im Orbit —, doch der menschliche Preis seines utopischen Ehrgeizes zählt zu den schwersten Warnungen der Geschichte." },
    fr: { heading: "Le Goulag et le prix de l'utopie",
      body: "L'Union soviétique promettait un paradis des travailleurs, mais le bâtir sous Staline coûta des dizaines de millions de vies. Pour s'industrialiser à un rythme effréné et écraser toute opposition, l'État créa un vaste réseau de camps de travail forcé connu sous le nom de Goulag. Des millions de personnes — paysans résistant à la collectivisation, prétendus 'ennemis du peuple' et innombrables innocents — furent exténuées, affamées et glacées dans les camps de Sibérie.\n\nLa terreur atteignit son sommet lors des purges de la fin des années 1930, quand la police secrète de Staline arrêta, tortura et fusilla un nombre immense de gens sur des accusations inventées, dont beaucoup de communistes fidèles et d'officiers de l'armée. Pendant ce temps, la collectivisation forcée de l'agriculture déclencha des famines qui tuèrent des millions d'autres, surtout en Ukraine. Le siècle soviétique accomplit de vrais exploits — alphabétisation de masse, puissance industrielle, victoire sur l'Allemagne nazie, premier satellite en orbite — mais le prix humain de son ambition utopique demeure l'un des plus graves avertissements de l'histoire." },
  },
  'modern-09': {
    en: { heading: "Satyagraha: The Weapon of the Unarmed",
      body: "Gandhi's great contribution to history was not just Indian independence but a method of achieving it: satyagraha, or 'truth-force' — mass, disciplined, nonviolent resistance. Rather than meet the British Empire with weapons it could easily crush, Gandhi taught Indians to refuse cooperation with injustice: to boycott British cloth, disobey unjust laws, and accept punishment without striking back, exposing the violence of the powerful.\n\nThe classic example came in 1930, when Gandhi led a 385-kilometer march to the sea to make salt in defiance of the British monopoly. The simple, symbolic act electrified India and drew the eyes of the world. Nonviolent resistance did not spare India suffering, and independence in 1947 came amid tragic partition — but Gandhi's method proved that ordinary people, without arms, could shake an empire. It would later inspire Martin Luther King Jr. and freedom movements across the globe." },
    es: { heading: "Satyagraha: el arma de los desarmados",
      body: "La gran contribución de Gandhi a la historia no fue solo la independencia de la India, sino un método para lograrla: la satyagraha, o 'fuerza de la verdad', la resistencia masiva, disciplinada y no violenta. En lugar de enfrentar al Imperio británico con armas que este podía aplastar fácilmente, Gandhi enseñó a los indios a negar la cooperación con la injusticia: boicotear la tela británica, desobedecer leyes injustas y aceptar el castigo sin devolver el golpe, poniendo al descubierto la violencia de los poderosos.\n\nEl ejemplo clásico llegó en 1930, cuando Gandhi encabezó una marcha de 385 kilómetros hasta el mar para fabricar sal desafiando el monopolio británico. El acto, simple y simbólico, electrizó a la India y atrajo la mirada del mundo. La resistencia no violenta no libró a la India del sufrimiento, y la independencia de 1947 llegó en medio de una trágica partición, pero el método de Gandhi demostró que gente común, sin armas, podía sacudir a un imperio. Más tarde inspiraría a Martin Luther King y a movimientos de libertad por todo el planeta." },
    ru: { heading: "Сатьяграха: оружие безоружных",
      body: "Великий вклад Ганди в историю — не только независимость Индии, но и метод её достижения: сатьяграха, «сила истины», массовое, дисциплинированное, ненасильственное сопротивление. Вместо того чтобы встречать Британскую империю оружием, которое та легко сокрушила бы, Ганди учил индийцев отказываться от сотрудничества с несправедливостью: бойкотировать британскую ткань, не подчиняться несправедливым законам и принимать наказание, не отвечая ударом, обнажая насилие власть имущих.\n\nКлассический пример пришёлся на 1930 год, когда Ганди возглавил марш длиной 385 километров к морю, чтобы выпаривать соль вопреки британской монополии. Простое, символическое действие наэлектризовало Индию и приковало взгляды всего мира. Ненасильственное сопротивление не избавило Индию от страданий, и независимость 1947 года пришла среди трагического раздела, — но метод Ганди доказал, что простые люди, без оружия, способны потрясти империю. Позже он вдохновит Мартина Лютера Кинга и освободительные движения по всему миру." },
    mk: { heading: "Сатјаграха: оружјето на невооружените",
      body: "Големиот придонес на Ганди во историјата не беше само индиската независност туку и методот за нејзино постигнување: сатјаграха, или „сила на вистината“ — масовен, дисциплиниран, ненасилен отпор. Наместо да ја пречека Британската империја со оружје што таа лесно би го скршила, Ганди ги научи Индијците да одбијат соработка со неправдата: да ја бојкотираат британската ткаенина, да не се покоруваат на неправедните закони и да ја прифатат казната без да возвратат, разоткривајќи го насилството на моќните.\n\nКласичниот пример дојде во 1930 година, кога Ганди предводеше марш долг 385 километри до морето за да прави сол пркосејќи му на британскиот монопол. Едноставниот, симболичен чин ја наелектризира Индија и ги привлече очите на светот. Ненасилниот отпор не ја поштеди Индија од страдање, и независноста во 1947 година дојде среде трагична поделба — но методот на Ганди докажа дека обичните луѓе, без оружје, можат да протресат империја. Подоцна ќе ги инспирира Мартин Лутер Кинг и движењата за слобода низ целиот свет." },
    de: { heading: "Satyagraha: die Waffe der Unbewaffneten",
      body: "Gandhis großer Beitrag zur Geschichte war nicht nur die Unabhängigkeit Indiens, sondern eine Methode, sie zu erringen: Satyagraha, die 'Kraft der Wahrheit' — massenhafter, disziplinierter, gewaltloser Widerstand. Statt dem Britischen Empire mit Waffen zu begegnen, die es leicht zerschlagen konnte, lehrte Gandhi die Inder, die Zusammenarbeit mit dem Unrecht zu verweigern: britisches Tuch zu boykottieren, ungerechte Gesetze zu missachten und Strafe hinzunehmen, ohne zurückzuschlagen, und so die Gewalt der Mächtigen bloßzustellen.\n\nDas klassische Beispiel kam 1930, als Gandhi einen 385 Kilometer langen Marsch zum Meer anführte, um dem britischen Monopol zum Trotz Salz zu gewinnen. Der schlichte, symbolische Akt elektrisierte Indien und zog die Augen der Welt auf sich. Der gewaltlose Widerstand ersparte Indien kein Leid, und die Unabhängigkeit von 1947 kam inmitten einer tragischen Teilung — doch Gandhis Methode bewies, dass einfache Menschen ohne Waffen ein Weltreich erschüttern können. Sie sollte später Martin Luther King Jr. und Freiheitsbewegungen auf dem ganzen Erdball inspirieren." },
    fr: { heading: "Satyagraha : l'arme des désarmés",
      body: "La grande contribution de Gandhi à l'histoire ne fut pas seulement l'indépendance de l'Inde, mais une méthode pour l'obtenir : la satyagraha, ou 'force de la vérité' — une résistance de masse, disciplinée et non violente. Plutôt que d'affronter l'Empire britannique avec des armes qu'il pouvait aisément écraser, Gandhi apprit aux Indiens à refuser toute coopération avec l'injustice : boycotter le tissu britannique, désobéir aux lois injustes et accepter le châtiment sans riposter, exposant ainsi la violence des puissants.\n\nL'exemple classique survint en 1930, lorsque Gandhi mena une marche de 385 kilomètres jusqu'à la mer pour y fabriquer du sel au mépris du monopole britannique. Ce geste simple et symbolique électrisa l'Inde et attira les regards du monde. La résistance non violente n'épargna pas la souffrance à l'Inde, et l'indépendance de 1947 advint au milieu d'une tragique partition — mais la méthode de Gandhi prouva que des gens ordinaires, sans armes, pouvaient ébranler un empire. Elle allait plus tard inspirer Martin Luther King et des mouvements de libération à travers le monde." },
  },
};
